/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200819-6","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"区民委員会","time":"午後 １時００分～午後 ２時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"令和２年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"令和２年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"２年間で３分の１ぐらいに事業規模が縮小してしまっているという部分で、今回１年目、新規の助成の申請がなかった理由の分析をお聞かせいただきたい。今後増やしていくべき方向性に向かっていくために、現段階でどういった形で検討しているのか、そこの部分をまず説明を求めました。","respondent":"宮澤協働・国際担当課長","answer":"７月に各団体と直接お話しする機会があったのですが、今年度１年間、非常に多く聞きました。広報しながわやホームページ等で事業説明というのはしているところですが、閲覧する方を含めて、周知を強化していきたいと思っているところです。","id":"exchange-001"},{"speaker":"くにば委員","kind":"質問","question":"今おっしゃった形で、相談に来たけれども数件に関しては辞退ということでした。申請書を書いてやり取りしたのが２２団体、最終審査が１５事業というふうに、今年応募自体は何件あったのか尋ねました。","respondent":"宮澤協働・国際担当課長","answer":"説明会というのも開催しましたが、４月のタイミングでしたので電話でお問い合わせがあったり、電話でなるべく済ませるような形にしました。ですので、説明会にいらっしゃったのは２団体、２名という形になっております。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"おっしゃるように１年間活動を休止しますという声を聞きつつも、そういったプラスアルファの取り組みがないと、やはり一番あるのです。せっかく４００万円から５００万円まで助成総額を上げたという思いがあるはずなので、そういった方法は何かお考えにあるか尋ねました。","respondent":"宮澤協働・国際担当課長","answer":"ＮＰＯを支援するＮＰＯ、こちらに委託をしまして、相談というのも個別に受けてお話しさせていただいています。ノウハウとして、感染症対策を徹底するとか、そういったやり方というのをアドバイスさせていただいたりしている状況です。","id":"exchange-003"},{"speaker":"くにば委員","kind":"提案","question":"例えば広報として区からの提案として掲載するなり、プラスアルファで区のほうから広報していただくというお考えについて、最後にご答弁をお願いしますとの意見を述べました。","respondent":"宮澤協働・国際担当課長","answer":"すまいるネットのリニューアルを、来年度に向けて今、構築しておりますので、その中でそういった周知という部分も考えていきたいと考えています。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"今、すまいるネットの話が出たのですけれど、すまいるネットに登録している団体数はどのぐらいになるのか尋ねました。","respondent":"宮澤協働・国際担当課長","answer":"登録団体数は５３４団体です。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"それ以外のこれから活動しようとしている人たち、活動している人たちに、どう広報するのかというのが大事なのではないかとも思うのです。その辺り今年度、具体的に広報手段として何をとられたのか、お願いいたしますとの意見を述べました。","respondent":"宮澤協働・国際担当課長","answer":"区民活動助成制度の周知方法につきましては、広報しながわ、区ホームページで周知したところです。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"できればやっていただきたいというのと、そういったところで広報していただきたいというのは、要望としてあります。先ほど委託の話もありましたが、Ｚｏｏｍ等を使ってオンラインの説明会というのも実施してほしいと求めましたが、その辺りはいかがか尋ねました。","respondent":"宮澤協働・国際担当課長","answer":"今年度につきましては、説明会は直接区役所の会場で開くという形で、その後の個別相談会につきましては、直接いらっしゃった団体もありますし、今年度から一応オンラインで相談というのも取り入れて、やりました。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問・要望","question":"個別の相談はオンラインということで、先進的にやっていただいているなと思いますので、始めの事業説明の相談会も、オンラインという選択肢もできればご検討いただければと、これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"２ページの、学識経験委員１名はどのような方でしょうか。有識者委員２名はどのような方か尋ねました。","respondent":"宮澤協働・国際担当課長","answer":"続いて有識者委員２名のうち、お一人につきましては、東京都社会福祉協議会の、東京ボランティア・市民活動センターの職員の方にお願いしております。もうお一人の方につきましては、中小企業診断士の資格を持つ区の商工相談員の方にお願いしているものです。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"審査委員会が開かれたと思うのですけれど、この方たちに対しての謝礼というのですか、支払われているのであるならば、その金額を教えていただけますか。","respondent":"宮澤協働・国際担当課長","answer":"金額につきましては後ほどでよろしいでしょうか。調べます。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる常連さん、今までやったところが２回、３回という形でいただいているということではないですか。そういう意味で、コストパフォーマンスを含めて１００万円以下の助成に関して、その辺についてはいかがか尋ねました。","respondent":"宮澤協働・国際担当課長","answer":"区職員２名を含めて、公募委員の方の意見を踏まえて、実施するべきと考えているところです。審査を通じまして、各団体の今後の活動の育成という観点も踏まえまして、行っているところです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"せっかく学識経験者、有識者の方、今、どういう方ですかという質問を最初にさせていただきました。答弁でいただきましたけれど改めて、そういうことにも力を入れていっていただきたいと思うのですけれど、いかがか尋ねました。","respondent":"宮澤協働・国際担当課長","answer":"あわせて、先ほどの委員のご質問の謝礼につきまして、回答します。委員長の謝礼につきましては２万３,０００円、その他の委員につきましては１万４,０００円です。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうすると８万円に少し欠けるぐらいのお金がかかるわけですから、そういう方々に来ていただけるのですから本当に活用していただいて。あのとき委員がいかがなものかと言ったけれども、ここまで来ましたというような事業に育ててほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"この団体の活動状況というのは把握されているのでしょうかということと、このコロナで休止しているところ、把握されているのでしょうか。申請団体数を見ても感じるので、そういったところの変化というのは区として把握されているのか、伺いたいと思います。","respondent":"宮澤協働・国際担当課長","answer":"しながわすまいるネットの登録団体５３４団体ですが、各団体が情報発信をしておりますが、その各団体の活動状況までは、全てを細かく把握しているということはございません。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"この申請してきた６事業は続いているということなので、活動中というのは分かるのですけれど、そのほかは休止ということなのでしょうか。休止してしまっている、もう解散してしまったというところはどれだけあるのか、伺いたいと思います。","respondent":"宮澤協働・国際担当課長","answer":"先ほどの説明でございましたが、２年目で今年度申請がなかったところにつきましては、個別に状況をお聞きしました。ただ、コロナ禍の中でということで、今回は申請しないというか、活動ができませんというお話は聞いているところです。","id":"exchange-015"}]},{"id":"topic-02","title":"「五反田バレーアクセラレーションプログラム」Kick-Offイベントの開催","agenda":"「五反田バレーアクセラレーションプログラム」Kick-Offイベントの開催","exchanges":[{"speaker":"松本委員","kind":"意見","question":"事業の作り方とか、創業後に事業計画を立てたりという講座というのがあると、もう始まってから軌道修正するのは結構大変なのかなと思うのですね。こういった事業なら創業前の段階で入ってこられるというのも大事かなと思いますが、その辺りはどういうお考えなのか…","respondent":"遠藤商業・ものづくり課長","answer":"いわゆる創業前の段階から５年以内と、多分支援としてはこちらのアクセラレーションプログラムよりも、また別の支援もあるのかなと考えています。ＩＴスタートアップ支援事業につきましては、ふるいにかけるというのも変ですけれども、というふうに思っているところです。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと質問ですけれど、そもそも論ですけれど、これは品川区の事業なのですか、それとも品川区がバックアップというか助成をしてやる事業なのですか。どういうふうに関わっているのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは委託事業ということでやっておりますので、品川区の事業となっております。そういうところでいいものを出し合って、一緒にやっていこうということで、費用につきましては私どものほうが出しているということになってあります。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"問い合わせ先が株式会社キャンパスクリエイトとなっているのですけれども、なぜこういう形になっているのかという説明をしていただきたいのが１点。これはどうしてか、教えていただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"ですので、いろいろな関係で入ってくるですが、品川ビジネスクラブに委託させていただいているです。お声をかけたところ、私どもも大崎地区ということで盛り上がればということで、一緒にやらせていただくという形になったところです。","id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"なぜ伺ったかというと、なぜ今回こういうふうに入れたのかなという思いがあったので、改めて質問させていただいたのですけれど。西五反田と線路で分かれるではないですか、東だではなく、五反田ということで一体でこれから物事を考えていくと思っていてよろしいのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"地区につきましては、特にここと決めているわけではなく、全体的に品川区が五反田地区を応援しているよという形になればいいかと思います。品川区の中で広がればいいなとは思っておりますので…","id":"exchange-019"},{"speaker":"くにば委員","kind":"質問","question":"立ち上げをさらに推進するという部分、非常にいいイベントを行われるなと、大変評価しております。１点まず伺いたいのが、経費７９７万円余りということは、Kick-Offイベントのみでの経費か尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"記載のほうが、申し訳ございません、こちらは全てのイベント、先ほどの運営とか、募集とかも含めての経費が８００万円弱という形になっております。","id":"exchange-020"},{"speaker":"くにば委員","kind":"質問","question":"このプログラムの最初のKick-Offイベントから、８項目ずっと実施日があって、最後のＤｅｍｏ Ｄａｙまで含めた全部のパッケージとして、品川ビジネスクラブのほうに７９７万円を丸ごとという形か尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"はい、そのとおりです。","id":"exchange-021"},{"speaker":"くにば委員","kind":"質問","question":"分かりました。ではこの約８００万円の経費の内訳というのは、把握なさっているという認識でよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"先ほどのプログラムの部分で、全体の企画と審査、申請の受付部分につきまして約２５０万円、Kick-Offイベントから研修、Ｄｅｍｏ Ｄａｙまで含めたものが大体４７０万円程度、そのほかで広報関係の経費が７５万円、トータルで８００万円弱という形になっております。","id":"exchange-022"},{"speaker":"くにば委員","kind":"意見","question":"内訳ありがとうあります。主に後半のほうの４７０万円という部分で、何の経費でそれぐらいかかるのか不明で、もう少し詳しくお聞かせいただけますかとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"それから４つ目のメンタリングにつきましては９０万円程度、こちらは全部で３回に分かれておりますので、そのぐらいかかるということです。残りの部分につきまして大体３００万円程度というふうに、すみません、把握できないところです。","id":"exchange-023"},{"speaker":"くにば委員","kind":"質問","question":"分かりました。９０万円ぐらいとおっしゃるのは、もう少し具体的に、金額がとても気になっているので説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"メンタリングは個別相談になりまして、実施日の記載のとおり３日間に分かれて２０社に対してやるということですので、１社が大体５万円弱ぐらいという形で考えて、それで大体９０万円、１日３０万円という形で見込んでおります。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"ではコンサルタント費用的な形で、１社当たり幾らという形のおおむねの見方ということで、分かりました。オープンイノベーションプログラムの開催回数１７０回ということで、今回品川区とのタイアップでやるのは初めてになるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"品川区でやらせていただくのは、Ｃｒｅｗｗは今回初めてです。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問","question":"スケジュールのほうは最終が来年３月１７日までで、今回２０社ということで決まっておりますけれども、現在その検討をなさっているのでしょうか。最後にそれだけお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"Ｃｒｅｗｗ株式会社は１７０事業会社とオープンイノベーションプログラムを実施、別の地域、では既に実績を上げているところです。そういう部分でこちらのほうも選ばせていただいたところがありますので、ぜひとも成功させたいと思っているところです。","id":"exchange-026"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"１つだけ、もしお許しいただけるなら、しながわ活力応援給付金について確認したいことがあるのですけれど、よろしいでしょうか。課長がいらっしゃるので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"たしか１０万円の給付金のときに使った口座で同じでいいですかというチェック欄があったと思うのですけれども、つまり何が言いたいかというと。１０万円の給付金の情報をそのまま使ってしまっても、条例的には問題ないのか、それだけ確認させていただけますか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"国の１０万円の特別定額給付金と同じ口座を希望される方は、委員がおっしゃったとおり、その上で申請書をいただいているという形になっております。これは、条例を含めて問題ないということを確認しています。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"今のしながわ活力応援給付金なのですけれども、発送がもう８月上旬ぐらいからされていて、その後の初めての委員会なので、報告としてこの委員会であってもよかったのかなと思うのですけれども、そこは特に今回、報告事項に挙がらなかったというのは、何か事情があるのか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"８月５日に申請書を発送させていただいて、今、鋭意、順次進めているところです。始まったばかりのこのタイミングですので、改めてご報告しますので、よろしくお願いします。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"我々も要望とか質問とかを受けていますので、ぜひ早目のご報告をいただきたいと思うのと、こういった先進的な取り組みをしていただければとお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2876#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":18442,"voices":75}},{"id":"r02-20200819-7","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"厚生委員会","time":"午後 １時００分～午後 ４時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(3)から先に行います。 それでは、(3)品川区がんの夜間相談窓口事業の開始","agenda":"冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(3)から先に行います。 それでは、(3)品川区がんの夜間相談窓口事業の開始","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"場を重視する相談の場ですから、その点はいかがなのでしょうか。かなりボランティアで支えられているような内容だったので、その点をお伺いしたいと思います。","respondent":"高山健康課長","answer":"それから３点目の、医療関係従事者というような方、できれば多くの方にご利用いただきたいという考えでおります。６カ月、６回分ということで、３３万円余の金額を計上しております。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"そのプラスアルファというのは、場の提供というか、雰囲気みたいなもの、プラス夜間もあるということなのですか。そういう理解でよろしいのか尋ねました。","respondent":"高山健康課長","answer":"ご本人の能動的な意思で選択していただければと考えておりますので、いずれかの機関に絞って相談せねばならないといった趣旨のものではございません。しつらえといいましょうか、ありようというのが随分と違うことが、分かっていただけるものかと考えております。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"昼間、普通に開けている状況というのは、再開されているのでしょうかというところが１つ。最後の質問なのですが、さっきご説明の中にもあったのですが、金曜日の夜間の時間帯は、品川区民しか受け入れないということでよろしいのか尋ねました。","respondent":"高山健康課長","answer":"２点目のアクセスに関しては、今からでも間に合いますので、対応してまいりたいと考えています。それから３点目の、先ほど説明の中でも少し触れさせていただきましたが、税を投入して区の事業として実施するので。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"意見","question":"２点目のアクセスのところだけ。以上ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"}]},{"id":"topic-02","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"回すのが大変になっているのではないかと伺われたのですけれども、今、どういう資格の方が何人いらっしゃるような体制でやられているのでしょうか。お伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"新型コロナウイルス感染症に対応しているのは、会計年度任用職員が４名、派遣の看護師が電話相談センターも含めまして１７名で対応しております。新型コロナウイルス感染症に関連して対応しているのは、それから東京都からの応援の職員が現在６名対応しておりまして…","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、８００人弱というのが、大体、ほかの品川区内の検査をする大型の病院でやられていると考えていいのでしょうか。大型の３院、３つの病院でやられていると、この表を見るときに考えていいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"検査体制についてご質問いただきました。随分と検査をしていただける医療機関が増えましたので、そこを全部合わせて、かなり検査可能な数が日々増えているという状況になります。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"これは、全体が６００人弱というようなグラフになっているのですけれども、この６００人弱のそれぞれの内訳の数字は公表はされていないのでしょうか。それから気になるのが、死亡者というのはグラフで見ると全然分からないのですけれども、一人もいないという理解でよろしいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"最近では８月１４日にお一人亡くなっています。合わせて５名の方が品川区の対応の方です。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから第２点として、いろいろ調査・指導をなされたということは伺っているのですけれども。最後に、ほかに同様の地域が品川区内であるのか、ないのかということもお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"特定した２５名以外の一連のお客様等特定できない方については、我々が把握した中で、おおむね２５名程度ではないかと考えております。区内その他の地域でのこういったクラスターの状況がどうかということについては、現時点ではそういったお話は確認しておりません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"そこから先の話ですが、ではどうすればいいのかということは、品川区で考えられるのですか。３点お伺いします。","respondent":"鷹箸保健予防課長","answer":"唾液のＰＣＲ検査を実施していただくということで、詳しい場所その他はお教えできませんけれども、結構な数の医療機関にご協力いただけております。これがもし今後変更になるとすると、１類から５類まであります類型のどこかに入れて、これをやめるわけにはいきません。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"そうすると、２つ目の質問のＣＯＣＯＡの内容ですけれど、これは今、ＣＯＣＯＡから接触通知が飛んできました。そうしたら、保健所とすれば、まずはほとんどというか全て、ＰＣＲ検査につなげているという認識でいいんか尋ねました。","respondent":"鷹箸保健予防課長","answer":"それを否定する根拠はまるでないので、お回ししています。その数もかなりの数です。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"それは、ＣＯＣＯＡからの相談ということで何か取っていますか。それだけ説明を求めました。","respondent":"鷹箸保健予防課長","answer":"そこまで、今、即答できるほどには取っていないです。ＨＥＲ－ＳＹＳが動くようになった８月３日以降なのですけれども、陽性の方は出るので、検査はちゃんと回さないといけないと思っています。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"保健所に連絡した場合、ＰＣＲ検査に回しているというお話を伺ったのですけれども、あくつ委員もそういうことがあったから質問されたと思うのです。ＰＣＲ検査をするように勧めるということを伺ったので、もう一回、それでやはりＰＣＲ検査のほうにということになれば検査できるのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"来たと言えば誰でも、自費だったら例えば３万円とか５万円かかる検査が無料で受けられるということは、今現在はそういった対応はしていないはずです。そこは戻りまして、きちんと対応するように今後はしていきたいと思います。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ちょっとあれなので、ここでお話しはできないですけれど、承知しました。ご相談があったら、今のように対応してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"一番初めは１日１５件というところから始まったのが、厚生労働省の体制があるのかどうなのか、その点を１点お聞かせほしいと求めました。その点についてまずお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"現在、土曜日については、対応していただいている医療機関がありますので、そこをご紹介しております。行政検査の対応が可能でございまして、この方は行政検査が必要と考えられた場合には、そちらで行政検査の実施が可能という体制になっております。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"そうすると、実際にはかなりの数がこれを超えて、ＰＣＲ検査が行われているだろうと考えられるのか。その点についてお願いしますとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"１日何件検査をしたということを報告するシステムが、総数を把握するすべが私どもはありませんし、東京都もまだ把握しておりません。ですが陰性の方が含まれていませんので、これは見かけの陽性率の可能性がありますということを、このグラフでご説明している形になります。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"このグラフの最新のところでの７１２名というところで分かったら教えていただきたいのですけれど、入院者の実数を教えていただけないでしょうか。それともう一つ、プレスリリースをするときの基準というのは、どういう基準でされているのかについてもお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"潜伏期間の２倍までで発症がなければ終わりという考えがあるのですけれど、この病気の場合、終わりましたという報告は非常に難しいかと思います。必要な対応は、濃厚接触者を全部特定して検査をしてという形で実施しておりますが…","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"品川区としても、やることができないかと思っているのですが、いかがでしょうか。それとも国のほうとして、それは認められるということになるのか、その仕組みについてもお聞かせいただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"潜伏期間中は家にいるようにという方針もありますので、定期的な検査というのがそのまま安心につながるとは単純には考えられないと考えています。品川区として、例えば他の自治体のように定期的な検査を実施するという方針、そういった考えは、少なくとも現時点ではありません。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"感染を押さえ込むということにもつながっていくと思いますし、ぜひ定期的な検査というものを実施の方向でご検討いただきたいと、改めて要望します。人数はこの日の時点でぜひ出していただきたいということで、いかがでしょうかということです。","respondent":"鷹箸保健予防課長","answer":"それは４月の毎日新聞の記事だと思うのですけれども、２３区全部に調査をして、４月が最大１７４時間だったという報道だと思います。派遣の職員を増やし、また今回８月から、その中で何とかやりくりをしていきたいというところで考えるしかないかと今は考えているところでありま…","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひ保健師の増員、それから保健所の体制強化ということで取り組んでいただきたいということで、要望させてほしいと求めました。１７名まで広がったということですけれども、例えば７月全体でとか、８月今まででということで分かったら教えてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"濃厚接触者の方を５０名把握して、そのうち区内在住の濃厚接触者は２０名で、この方たちに対しては、我々から検査のご案内をしております。受けなかったという方をこれまで聞いておりませんので、そこで陽性だった方は発生届が出るという形で対応しているところになります。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２０名ではない。その辺の、何名検査をした中で１４名の感染者が出たのか、そこのところをお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"その中で検査をした１７名だとか、そういうことではありませんので、同じクラスターではないかというのを後から把握している形になります。そこからの濃厚接触者が全部で５０名のところ、区内在住濃厚接触者は２０名と、後追いで分かる形だと思います。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そういう点では、大井町地域を地域的に、その点についてはいかがでしょうか。その点についても確認させてください。","respondent":"鷹箸保健予防課長","answer":"５、６人でいっぱいになってしまうようなお店も多いと聞いておりますし、換気も非常に難しいと。例えば食中毒であれば、そういった休業要請ということもあるかもしれませんが、それについては我々とは特段関係なくやっていることだと思います。","id":"exchange-021"},{"speaker":"鈴木（博）委員長","kind":"質問・要望","question":"では、最後に委員長から一言要望させていただきたいのですが、乳幼児健診の集団健診が非常に難しいと思います。これは私からの要望です。","respondent":"鷹箸保健予防課長","answer":"平成２５年４月１日から定期予防接種として開始されたところですが、開始間もない２カ月後の平成２５年６月１４日から現在に至るまで、開始当初。必要だと思う場合に、受けるのはいかがでしょうかということでご案内することに、方針を若干変更いたしましたので、ご報告します。","id":"exchange-022"}]},{"id":"topic-03","title":"ＨＰＶワクチンの区による情報提供","agenda":"ＨＰＶワクチンの区による情報提供","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"その中で、私が読んでも参考になるのですけれども、これもやはり配布しているということなのでしょうか。それをお伺いいたします。","respondent":"鷹箸保健予防課長","answer":"パンフレットのサイズにつきましては、現在、Ａ４判で考えていたところですが、間に合えば、大きさについては担当と協議したいと思います。接種を検討する、青色のパンフレットを対象児のところに送ることで考えておりまして、現時点では考えておりません。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"水色のパンフレットを送るということですけれど、それと併せて、どの医療機関でこれを受けられるのかというのも送られるのでしょうか。その点について説明を求めました。","respondent":"鷹箸保健予防課長","answer":"こちらのパンフレットを送ることに方針は変更しましたが、平成２５年６月１４日の積極的な接種勧奨を差し控えるという方針は変わっておりませんので。私どもからはとてもできませんので、必要な情報を確実に、すぐにお送りすることになっております。","id":"exchange-024"}]},{"id":"topic-04","title":"令和２年度障害児者の相談支援体制整備促進事業等に係る事業者の選定","agenda":"令和２年度障害児者の相談支援体制整備促進事業等に係る事業者の選定","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"それで６事業者が選定されなかったということなのですが、この６事業者というのはどこで、理由はどういったことなのでしょうか。それをお伺いしたい。","respondent":"松山障害者福祉課長","answer":"選定されなかった６つの事業者については、事業者の利益の損害を恐れることから、公表しておりません。それぞれ相談支援員の資格がある人を配置し、１名ないし２名の相談支援員を配置するということになっておりますので、バックアップ体制として。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"その辺のことをお伺いしたいと思います。議事録も読ませていただいたのですけれども、今後もこういう形で増やしていく予定はあるのかということも併せてお伺いしたいと思います。","respondent":"松山障害者福祉課長","answer":"民間相談支援事業者・在宅介護支援センター併設型の事業者ともに、配置される相談員は１名ないし２名の予定です。ただし、今後の各事業所の状況ですとか、障害者や障害児のサービス利用者の伸び等も踏まえまして、今後については検討していきたいと考えています。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"３０５号室、最後の.Ｃｏｎｎｅｃｔ株式会社というところが１階となっていますけれど、いわゆる民間のマンションの一室ということでよろしいですか。それはもう事業者が持たれるということなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"開設予定地ですけれども、品川区だけではなく、相談支援事業所は、民間のマンションの一室を借りて行うことが多いのが実情です。そして、開設後は継続して安定した運営をしていただくのが一番いいかと考えています。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう形で、今回も高齢者と同じ地域を担当するということで行っていくのかということを、１点お願いしたいと思います。その点について、まずお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"２点目の、今のところ、全ての在宅介護支援センターという形では想定しておりません。先ほど説明させていただきましたように、昨年度開設した相談支援事業所がある地区の２地区、その中で大崎地区と大井西地区が選定されたです。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"在宅介護支援センターが、在宅介護支援センターで計画をお願いしたいと思っても、この担当地域以外の方は利用できないということになるのでしょうか。一覧表の中から選ぶことができる仕組みということの確認と、在宅介護支援センターのところでの地域指定というところの。","respondent":"松山障害者福祉課長","answer":"あるいは８０５０問題は、やはり解決しなければならない課題だと認識しておりますので、共通目的になっております。そのため、今後、担当地域をどうしていくのかという整理も必要になってくるかと認識しております。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回また新たに６カ所ということで、昨年度増えた６カ所の実績について、どんな状況になっているのか教えていただけたらと思うのです。去年新たにできた６カ所で、それから今度新たに６カ所増えることによって、そこのところを教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"皆さん、行政サービスを受けたり手帳を取ったりというところで安心感もありますので、なかなか児童の移行については課題として認識しております。ただし、障害者の大人の方の場合については、円滑に移行していると認識しています。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"大人でも７０人ということですと、１カ所あたり２０人にもならないという感じかと思うのですけれど、それでも出されていたのでしょうか。そこの実態も併せて教えていただきたいのと、合わせて児童のほうが６カ所ですか、この事業者にどういうふうにしたら移行できるのかというような。","respondent":"松山障害者福祉課長","answer":"事業所として場所を設置して事務所を構え、東京都に届出をし、本当に開設促進の事業の補助金があってできたものと認識はしております。ただし、今後、安定した形で、継続してきちんと計画相談が受けられる形になれば、区としては補助金を出す意味があったと考えています。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからもう一つ伺いたいのが、これはどういうふうに周知されたのか、その点についてもお聞かせほしいと求めました。それから、もう既に連絡会というのは持たれているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"今回の選定から漏れてしまった６事業者に対しましても、補助なく自力でやりたいというお声も聞いておりますので、期待したいと考えています。あるいは相談支援部会という名前で集まっていただいて、あるいは今回…","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"その点について、最後、説明を求めました。","respondent":"松山障害者福祉課長","answer":"今回の相談支援事業所だけではなく、ほかのサービスに対しましても、幅広く展開していければと考えております。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3574#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":37240,"voices":95}},{"id":"r02-20200819-8","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"建設委員会","time":"午後 １時００分～午後 ５時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件整理しています。","topics":[{"id":"topic-01","title":"令和２年請願第８号、「（仮称）豊町１丁目計画 新築工事」に関する請願","agenda":"令和２年請願第８号、「（仮称）豊町１丁目計画 新築工事」に関する請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"その解決方法を求めて、事業者との話し合いを行政にもとりもってしてほしいというものになっております。１回で説明会が終わってしまったということで、説明が尽くされたと区のほうでは考えているのか、まず区のお考えを伺いたいと思います。","respondent":"森住宅課長","answer":"１８、１９日に個別説明がなされ、それに加えて６月１０日に追加の説明会がされたというふうに聞いております。説明は基本的には終わっているというふうに考えておりまして、話し合いを継続していくという旨の回答をなされているというふうに聞いております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは請願者の方々が求めている緊急時の対応というのも困難ということなのか、そこの確認をさせてほしいと求めました。これも困難ということであれば、緊急時の対応は区としてはどのように考えているのか、伺いたいと思います。","respondent":"森住宅課長","answer":"緊急時、常時に限らず、敷地の中を不特定多数の方が通るということを今の時点で可とすることはできないというお話をされております。そういった部分でのセットバック等々で緊急車両の出入りができるように、というようなまちづくりを今後とも進めていくという形だと考えておりま…","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"新築工事が終わった後はどうするのだという話にもなりますので、そうした緊急時の対応というのは、やはり必要になってくると思います。区としてもそこに協力をしていくということが必要なのではないかと思いますけれども、いかがか尋ねました。","respondent":"森住宅課長","answer":"区といたしましては、事業者のほうから回答を一定されたというふうに考えておりますけれども、それに対して区として事業者に要望を伝えていく。これまでもやってまいりましたけれども…","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"話し合いをしっかりとしていただいて、合意が得られるように力を尽くしていただきたいというふうに思います。９月着工ということになっており、今回で結論を出すということにしていかなければ着工してしまうので、結果を出していくべきだというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"請願者の方に前もってお伺いしておけばよかったなということをすごく思ったのですけれども、今まで近隣の方たちが通られていた道路は、もともとは道路ではなかったのかどうかというところをまず確認させてください。","respondent":"森住宅課長","answer":"先ほど、３棟、戸建て住宅があったというふうにご説明いたしましたけれども。基本的にそこについて、西側の住んでおられる方々もそこを通って東側に出ていたという事実です。","id":"exchange-005"},{"speaker":"田中委員","kind":"確認","question":"民地だけれども通路となっていた部分も、計画地となっているところは権利が発生してしまっているということですね。そこの部分について確認させてください。","respondent":"森住宅課長","answer":"空間があって東側に出られるというところの中で、周りの方々もそこを利用していたというふうな慣行、実態としてはそういった形だったというふうに聞いています。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"どうにか施主の方との話し合いの場、近隣の方たちとの話し合いの場を求めているといったものなので、そこに関しては理解をします。品川区内でのまちづくりとかでも、住民の方たちがどうしてなのだという、この話し合いの場を求める請願者の気持ちはとてもよく分かります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"先ほどの説明の中で確認したいのが、管理組合に伝えるということをおっしゃったのは、何を伝えるのか尋ねました。","respondent":"森住宅課長","answer":"この共同住宅につきましては、分譲を予定されているですので、住まわれた方々が、通常であれば管理組合を作ってというふうに考えています。例えば非常時について、今…","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"だけど、それがなくて、建物が建ってしまったら、そこを「はい、どうぞ」と言っても通れないわけです。そこはどういうふうなイメージを持っているのか尋ねました。","respondent":"森住宅課長","answer":"外構の工事は追加で発生するかもしれませんけれども、そういったいわゆる建物周りの空地を使ってということは、物理的には可能なのかなというふうには考えているところです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"話し合いを設けてほしいということなのだろうなと思うのですが、５月１９日に請願者の方がいらっしゃって、事業者に伝えたわけですね。これは何が難しいと言っているのか、お分かりか尋ねました。","respondent":"森住宅課長","answer":"事業者として６月１０日に回答された内容としましては、緊急、非常時を問わず。それに対して、例えば分譲が終わった後に管理組合のほうにも伝えていくというお話をされたというふうに聞いています。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、せめてどういうふうに言うのか、管理者の方々に要望を伝えられるような状況、そういう場を作れるのかどうか。そこの瀬戸際のところで何かできることはないか尋ねました。","respondent":"森住宅課長","answer":"それに対して請願者の方も区に来られまして、その旨を伝え、説明会を再度開いていただいた。ある程度、方向性としては出ているのかなというふうに思いまして、これについて再度説明会をというふうに区のほうから要望したところで。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"は事業者の判断が「それでも駄目」と言うのか、よく分かりませんが、ただ誠意は伝えていただきたいというふうに思っております。これは要望として終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"５月１９日、区民の皆様の要望を受け、区としては事業者にそれを伝える、これが１つあって、それに対するお答えがあった。だけど、この民民のこういう話の中でできるのかということの判断はどう捉えているかという事実関係だけ説明を求めました。","respondent":"森住宅課長","answer":"区として指導できる内容といたしましては、条例に基づきまして標識の設置、説明会を行うというところを義務付けしているまでです。の説明会を区としては義務付けているという中身です。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日、結論を出してほしいと求めました。これについては不採択」と、今までもずっとこういうふうにしてきましたし、今回もそれでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこの中で新しく来た方たちと旧来から土地に住んでいる方たちの軋轢が起こらないように対処をしてほしいと求めました。民民の問題になりますので、採択することは不可能ではなかろうかと思いますので、不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"新旧という言い方が正しいかどうか分かりませんけれども、品川区としても防災対策の非常に重要な地域であるというところも認識しております。何か危急のときに、今後の対応については新旧皆さんの意見をしっかり踏まえて、しかるべきところにお話を通していただきたいということが意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"のだて委員","kind":"意見","question":"本日、結論を出すということで、この請願は、話し合いをしていきたい、それに協力してほしいということですので、住民に説明を尽くすことがやはり必要だというふうに思いますし、自治体としてもそれに協力していくべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"田中委員","kind":"意見","question":"ここをどうしても通してほしいというこの請願者の方たちの思いはなかなか難しいのかなというところがあるのですが、ただ、応援したいと思います。まだ納得できていない部分があるのかなと思うので、区としてもその仲介に入っていただき…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"「いやいや、いつも使っている道だから」みたいなことを言われると、それはやはり違うのではないですかという話。そういうご配慮をお願いしたいということは、区のほうからもお願いしていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"採択ということで主張いたしましたが、住民の皆さんの要望を多く賛同させていくということで、趣旨採択ということにしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]},{"id":"topic-02","title":"羽田新飛行ルートの運用状況等","agenda":"羽田新飛行ルートの運用状況等","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"国から示された資料について、区としてはどのように受け止めていらっしゃるのか、それを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"当初、国が説明会等で示してきた推計値と同等あるいは超えたことも小型機のほうですが、おおむね推計の値が示されているです。この報告制度が２０１７年度から実施されて、毎年、この数を減らしていただきたいというところが区としての考え方です。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"この推計平均値を上回った測定局もありますので、なぜ上回ったのかということも国土交通省から説明を聞いておられましたら、伺いたいと思います。「別途１～２週間程度の短期的な測定を検討する」ということが書かれておりますが、今どういった調整がされているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区内３か所のうち、八潮ポンプ所につきまして数字が超えてありますが、基本的にこの件に関する説明は、国のほうからはございません。ただ国の説明の中では、原因等を究明して、状況によってはその対策も検討していかなければいけないです。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"落下物として確認されたのは０件だということですが、実際に部品欠落件数は、昨年度よりも２倍弱に増えているということになります。このチェックや点検を続けていくことで、落下物はゼロになるというふうに区のほうではお考えなのか、国の説明などもあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今の６ページの真ん中のあたりに、その辺は落下物防止対策基準への追加対策に入れ込んだというところもあります。国の説明では、こうした取組を総合的に継続し、重点的に行っていくことで、落下物ゼロを目指していきたいということで聞いてあります。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"その中には１kg以上というものが３個含まれているというところもありますので、これが実際に落ちてくれば大きな被害になると思います。改めて落下物をなくせるのかというところでご答弁を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"事業主体の国に責任をもって取り組んでいただく。その中ではゼロを目指して取り組んでいくということを掲げてありますので、さらなる加速した取組をこれからも継続して区としては求めていくです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりその被害が区民に及ぶということになりますので、区としてもそこはしっかりと受け止めていただきたいというふうに思います。それは今現在どうなっているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"開始されたときはまだ暫定の騒音計の設置でございましたが、ただ、測定は継続して行ってきております。以前の建設委員会でも説明させていただいたのですが、一月分あるいは二月分ごと、定期的に公表を行っていきたいというような状況です。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"そういうことも確認したいのですけれども。なぜかというと、その方たちのためにも、今できる手段で騒音測定をして公表することはできないのかということをまず確認させてください。","respondent":"鈴木都市計画課長","answer":"そうしたところを行いながら、今、鋭意努力しながら一刻も早く。今は導入のところでちょっと足踏みしておりますが、一刻も早い公表を行っていきたいと思います。","id":"exchange-026"},{"speaker":"田中委員","kind":"提案","question":"次に、今回、この国土交通省の資料を提出していただいたのですけれども、なぜこの資料が提出されたのかということを伺いたいと思います。なぜかというと、私たちに何を求めていたのかということが見えてこなくて、その部分をまずお知らせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"この１回目の検討会の中で、統一した考え方がオーソライズされたものが示されたということであれば、当然ながらお示しするものです。まだ１回目の６月３０日のものについては、こちらでご説明する内容ではないというふうなことで、私のほうで判断したところです。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"検討会について、前回の委員会の中では、１回目の検討会の様子を見て、その後の要望とかを出していくという話だったと思うのです。そういったことなのかもしれないのですけれども、１回目の検討会の中身がそうだったとしても、報告はあるべきだと思うのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"私たちが求めているのは、羽田新ルートの問題について区が今後どう対応していくのかといったことだったりするので、なぜなのかなと思うのです。ですので、そういった改善を求めたいのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"固定化回避に向けた検討会につきましては、この１回目の検討会を行うということを国の局長、国会の場で説明しています。この検討会の推移について、動向についてはきっちり注視していきたいということは、前回の委員会でもご説明させていただいたと思います。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"例えば１か月に１回開催されるとか、何か月に１回開催されるとか、そういった開催についてもぜひ求めていただきたい。受け止める先、「ここに相談できます」と窓口が分かるようにお知らせできるように要望いたしますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"やはり今後の進め方、検討をしている中で、明確にはお伝えできないです。そのほうが当然理想的だと思うのですが、これはどちらかというと、何年も前から準備されていて今回の検討会に至ったわけではないという認識ですので。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区は一番影響を受けている区で、自治体としてもっと求めていく姿勢は見せてよいと思うので、どんどん要望をしていってほしいと思います。羽田の問題もとても注目をされているというか、心配をされているので、区民の方たちのためにも情報が受けられるようにお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"どういう測定の仕方をやっているのでしょうか。本来はどういうふうな意味合いがあったのでしょうかということが１つ。","respondent":"鈴木都市計画課長","answer":"この下のところに矢印、ピンク色と青色で付いていますが、これは説明会で国が示された推計平均値を示しています。当然ながら便数が少ないと、このＬｄｅｎも低くなるということで注釈が付いているところです。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"実際に品川区ではどういう影響があったのでしょうかというのは、やっぱりかみ砕いて話をしないと分からないのではないですか。分析が少し甘くないですか、現実とずれてはいませんかとちょっと気になるのですけれども、その辺はいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"羽田のこれからということで説明会、運用開始前にいろいろな資料を作って国が出してきた中には、例えば「８０ｄＢというのは。ただ、倍になったというのは、報告制度が充実してしっかり行われるようになってきたということは一端としてあるということでご説明したわけです。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"それが３倍になったときに、どういう影響があるのかというのは、数字的にも比較できるようにはしていただきたいというふうに思います。注視をしていただきたい、やっぱり追及をしていただきたいというふうに思っておりますので、これは意見として言わせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"今後の委員会での報告についてですけれども、先ほど求めた区の担当で測定している数値や検討会の報告とともに、区への問合せの件数を。前回、たしか３か月分だったかを教えていただいたと思うのですけれども、問合せ件数をお知らせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"区への問合せ件数ですが、４月が２６件、５月が２７件、６月が２４件、７月が３３件、８月が、８月６日現在になりますが４件です。この問合せ件数につきましても、今後、適時適切に当委員会でご報告します。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"前回たしかその件数の中で、騒音に対してとか、国の対応に対してとか、内訳も示していただいたと思うので、そのようにお願いします。要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"}]},{"id":"topic-03","title":"令和２年８月都営住宅入居者募集","agenda":"令和２年８月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"１軒、区内の都営住宅の軒数、戸数が減っているというのが現状だと思うのです。そこの区の考えと、ぜひ減らさないように、増やしていっていただきたいということで伺いたいと思います。","respondent":"森住宅課長","answer":"都営住宅につきましては、確かに倍率が高いものも都市部を中心に見られるという状況です。区内に３,４０９戸という形になっておりますけれども、その施設について、移管の判断をしていきたいというふうに考えているところです。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろな総合的なことを勘案して判断していくということだったのですか。減らさないことはもちろん、増やしていっていただきたいというふうに思いますので、もう一度お考えを伺います。","respondent":"森住宅課長","answer":"なかなか現実的ではないというふうに考えておりますので、どちらにしても民間住宅への円滑な入居ということが必要になってくると考えています。その中では、昨年度末に設立いたしました居住支援協議会も含めて、民間の力を生かしながら。","id":"exchange-038"}]},{"id":"topic-04","title":"大井町駅周辺地域まちづくり方針（素案）の策定","agenda":"大井町駅周辺地域まちづくり方針（素案）の策定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"どういった方針というか、ねらいなのかというふうに思いまして、そこのところを伺いたいと思います。行政のところで、この「柔軟な」というのはどういったものになるのか、ちょっとイメージが沸かなかったので伺いたいと思います。","respondent":"多並都市開発課長","answer":"したがいまして、やはり今回の７ページに示させていただいたところも含めて整備をしていくということで、そういう整理で書いているものです。確かに条例、その中で実現性についていろいろ検討しなければいけないことがあったら…","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"誰のことを言っていらっしゃるのか、そこを伺いたいと思います。どこで作られたのかというか、誰が作ったのか、そこのところを伺いたいと思います。","respondent":"多並都市開発課長","answer":"令和２年２月からそういう形で検討されているというのも、今まで２回ほど開催されているということを聞いております。その中で示させていただいている内容を踏襲しながら、そういう体系立った計画の中で区として進めている、そういう計画であります。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"ちなみに、Ｃ地区とＥ地区のところで、勉強会が何回ぐらいやられてきたのかということもお伺いしたいと思うのですけれども。この点はいかがか尋ねました。","respondent":"多並都市開発課長","answer":"その中でそういう検討をしていきたいということであれば、もちろんいろいろなご意見があることで、区としてもやはり気になるところです。まだそこまでの、いろいろな考えがあって検討されている段階なのではないかというのが区としても考えているところで、把握しているところで…","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"開発が幾つか行われてきた中で、地域の賑わいにはどうつながっているのか、そういったデータなどがありましたら伺いたいと思います。賑わいにどれだけ貢献していくのかというところは、区としてはどのように分析されているのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"検討してからいろいろ、先ほどもお話ししましたいろいろな方の思いを１つにまとめ上げながら建築まで、そういう事業スパンのものです。今、検討しているところでありますので、具体的にはそういう意味を込めて書かせていただいたところです。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、その中で報告書も４回求めても黒塗りという状況があるので、住民が参加できるようにしていってほしいと求めました。住民目線のまちづくりが重要だと考えていますので、より反映をしていくという視点で、どのように考えていらっしゃるのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"先ほどご説明しましたことと重複しますけれども、あとは地域の方によくお聞きしながら進めていくということが重要だと思います。そういう意味では、ステップごとに、そういう形でいろいろ広くご説明しながら意見を踏まえて進めていきたいと思っているところです。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に１点だけ。そういう方針が示されて、意見が出されても、その意見をぜひ住民目線で反映していくという視点でそれぞれやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"２日間の日程の中で時間を割って開催するのかとか、その場に行かなくても、ネットで見られたりするのかという点。質疑があるのかというところと、議事録の公開があるのかというところをまずお知らせください。","respondent":"多並都市開発課長","answer":"説明会を開かせていただいた後に、あと、議事録についても公開しています。いろいろ説明してほしいと個別のお話があった際は、そのような形で、個別にご説明できるような形で今までも対応をとっているところであります。","id":"exchange-045"},{"speaker":"田中委員","kind":"確認","question":"その質疑の内容によっては、今出されている素案の中身が変わっていく可能性も十分にあり得るということでよろしいでしょうか。確認させてください。","respondent":"多並都市開発課長","answer":"リモートで中継でというのは想定していなかったので、技術的にどうなのかといろいろあると思いますけれども、今は想定していないところです。当日、素案に反映させるためにいろいろご意見をいただきたいところですので…","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"そのときに見られたら一番いいのですけれども、そういうことができるのかというところを確認させてほしいと求めました。そして、もしかしたら先ほど説明があったかもしれないのですけれども、パブリックコメントは実施されるのか尋ねました。","respondent":"多並都市開発課長","answer":"今回はパブリックコメントの実施はいたしません。地域の方々にご説明して、地域の方々からのご意見をいただいて反映していく、そういう形をとらせていただきたいと思います。","id":"exchange-047"},{"speaker":"田中委員","kind":"意見","question":"今、では、やはり説明会に来て質疑をしないと区民の意見は言うところがないということになりますか。そこのところをお知らせくださいとの意見を述べました。","respondent":"多並都市開発課長","answer":"いろいろお話があれば、ご説明するとお話しさせていただきましたけれども、もちろん全部記録させていただいて意見としてカウントします。地域の方にご説明という形で、そのノウハウをもちながら、今回についても行っていきたいと考えております。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望します。今のＪＲとの協議の状況や進捗状況などを報告いただきたいと思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"今回の流れとしましては、今ある土地を再編した結果が今回の１１ページに示させていただいている協議の結果、ここが今のところの到達点。もしくは区のほうで公表できるものがあれば、それは適宜公表させていただきながら進めていこうと、そう考えているものであります。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"協議をしてここまで来たというのは分かるのです。協議の状況を、進捗などを報告いただければと思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"もうかなり具体的な話になってきていますので、結構頻繁に協議させていただいて、昨日もＪＲと協議させていただいているところであります。今ちょうど、本年度は一番まとめ上げていく年度でもありますので、頻繁に調整させていただいているというところが今の実態であります。","id":"exchange-050"},{"speaker":"田中委員","kind":"確認","question":"では、その協議、昨日も行われたということなのですけれども、その協議の場、広町のこれからについて話し合っている場なので、そういったものもきちんと議事録とかが残されているというものなのですよね、ということを確認させてください。","respondent":"多並都市開発課長","answer":"は、深い内容で協議しなければいけなくて後に残さなければいけないときには書いたりと、そういう実務的にいろいろやっている観点があります。「これがあって、これがない」とかではなくて、必要な部分はもちろん区のほうで保存しますけれども、そういうものもあるということです。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"情報公開を今しているところなので、そういったものがきちんとこれから公開されていくようにしていただきたいと、ぜひきちんとお願いします。要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"西本委員","kind":"確認","question":"これは広町地区のまちづくりという形で、そこを変えましたということだと認識しているのですが、ほかの地域の変更点はあるのでしょうか。そこは変えずに、今回はあくまでも広町アパートの解体、この辺だけのものだという理解でよろしいか尋ねました。","respondent":"多並都市開発課長","answer":"これはほかの地区と１個違うのは、地元の方がまちづくりの検討をされているという意味で、ここをゾーンとして設定させていただいた。それが変更点です。","id":"exchange-053"},{"speaker":"西本委員","kind":"確認","question":"ここはあくまでも区のスタンスとしては、住民たちの発案というか、話し合いの中で方向性を決めていくという感覚でよろしいですか。もちろん大枠はあると思うのですが、具体的なものについての進め方は、その話し合いが見守っているということの確認をしたいのですが。","respondent":"多並都市開発課長","answer":"内容が変わっているわけではありませんから、やはりまたここは一歩進んだ形で方針の改定などをやっていかなければいけないかなと思うところで、現時点ではそういう考え方をするところであります。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問・要望","question":"もう少し広い意味での官民連携という形に変えていかなければならないのではないかということを、１点、意見として言わせてほしいと求めました。１年ごとなのか、１０年ごとのスパンなのか、説明をお願いします。","respondent":"多並都市開発課長","answer":"ここがスパンを書かなかったのが１つの意味でもあるのですけれども、考え方としては、あえて年は示してはいないのです。おおむね１０年ぐらいが資料の短期と中期の間ぐらいかとは思っているところなのですけれども、そのような意味合いとご理解いただければと思います。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"そうではない状況になってしまうと、やはりそこはうまく調整していただきたいと要望したいと思います。それから、スケジュールについては、１０年、２０年という、まちづくりですから、そんなに簡単にはいかないです。","respondent":"多並都市開発課長","answer":"まちづくりを進めていく中で、先ほどありましたＮＰＯだったり、いろいろな動きの中でのものがあるということも我々は承知しているところであります。それを広く皆さんが１つに向かえるように、そこはしっかりやっていきたいと思っているところであります。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"この大井町駅周辺のまちづくりに関しての「ご意見をここにお寄せください」みたいなものとかがホームページとかにあったらいいと思うのです。そういったことをぜひ考えていただきたいと思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"先ほども説明会の後、資料は周知するというお話をしましたけれども、その中にも「お問合せがあればご連絡ください」という形で、もちろん書かせていただきたいと思っています。","id":"exchange-057"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をさせてください。そこだけ確認します。","respondent":"多並都市開発課長","answer":"実施段階ではもちろん総合的に、今ご意見があったようなことを含めて幅広く検討しなければいけないとは思っているところであります。都市計画上の整理もありますけれども、実施段階ではいろいろと幅広く検討できるかなと思います。","id":"exchange-058"},{"speaker":"石田（秀）委員","kind":"確認","question":"では、現庁舎の部分はどういうものを持ってくるのだと。現庁舎のここの部分が都市計画で位置付けされているから、その柔軟性が非常に奪われるということはないよね、という確認だけ。","respondent":"多並都市開発課長","answer":"区としてどのような形で整理していくかということの検討をさせていただいているところであります。庁舎のほうの動きと連携を図りながら、どのような形で組み合わさるのかということを幅広く検討はしたいと思っているところであります。","id":"exchange-059"}]},{"id":"topic-05","title":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","agenda":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"大井ふ頭でヒアリが何度か確認されているので、そうならないように願うとともに、そうしていかなければならないと思うのです。そういった中で、生息調査というのは、どういったことをやられているのか、伺いたいと思います。","respondent":"提坂環境課長","answer":"東品川清掃作業所、この６か所で実施しておりまして、これは専門業者による目視と粘着トラップの設置による調査ということで行っております。東京都港湾局のほうでもコンテナ等で実施を行っているところです。","id":"exchange-060"}]},{"id":"topic-06","title":"新型コロナウイルス感染症の影響に対応するための沿道飲食店等の路上利用に伴う道路占用許可基準の緩和","agenda":"新型コロナウイルス感染症の影響に対応するための沿道飲食店等の路上利用に伴う道路占用許可基準の緩和","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"個店１つ１つで申請していくのではないというところの確認をさせてほしいと求めました。これは新たに作ったということなのか、それとも今まであったものを改定して利用したということになるのか、そこのところを伺いたいと思います。","respondent":"稲田土木管理課長","answer":"そういうところは個店の方が数軒、何人か集まって申請主体となれば、条件等を考えながら相談に乗っていきたいというふうに考えております。それから、これは新たにテラス営業ができるということを作ったものです。","id":"exchange-061"},{"speaker":"田中委員","kind":"確認","question":"個店の場合は、数軒まとまってということだったのですけれども、１つのお店だけでの申請はできないということなのかという部分を確認させてください。それを拝見したのですけれども、この基準を探してしまったので、ぜひ参考資料として提供してほしかったということを思いますが、伺います。","respondent":"稲田土木管理課長","answer":"区といたしましても「１店舗だけでいいよ」というようなことはなかなかできないものですから、ある程度の団体というところで考えております。国のほうにも問合せまして、やはり、あくまで地域全体の合意形成の中で３密回避をやってもらえればというところで考えております。","id":"exchange-062"},{"speaker":"田中委員","kind":"意見","question":"その商店街に隣接した１軒のお店のことは分かったのですけれども、例えば商店街とかではなくて、路地にちょっとあるような１軒のお店とかは、今回の許可基準の緩和の部分には対象にならないということでよいのか、お知らせくださいとの意見を述べました。","respondent":"稲田土木管理課長","answer":"その１軒がどれぐらいの範囲か分からないのですけれども、周辺でそういう仲間といいますか、「みんな一緒にやりましょうよ」というふうになってくれれば、こちらも非常に嬉しいですが、そういう中におきましては、基本は団体にです。","id":"exchange-063"},{"speaker":"田中委員","kind":"意見","question":"了解しました。大体どこの地域を想定した上で制定したのかと思うのですけれども、どこら辺の地域を想定していたのかなどをお知らせいただければとの意見を述べました。","respondent":"稲田土木管理課長","answer":"区のほうでは、商店街で歩道がなくて店を出せれば非常にいいのではないかというようなことは考えました。お買物専用時間帯、そういうところでやるというのであればいいのではないかという計画です。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問","question":"そこでは可能なわけだから、そこの商店街の方々に「どうでしょうか」と声をかけることは当然やれたと思うのです。そこを団体ではないから駄目だというのは、この趣旨にそぐわないのではないかと思うのですが、その積極的な考え方はいかがか尋ねました。","respondent":"稲田土木管理課長","answer":"商業・ものづくり課とは最初から一緒に連携して取り組んでおりまして、そういうところでの実施はやっていこうかというところで考えていたところです。３密回避のためであって…","id":"exchange-065"},{"speaker":"西本委員","kind":"意見","question":"やはり飲食店の方々は本当に大変だと思いますので、少しでもチャンスがあるのだったら緩和していただいて。地域の活性化にもつながっていくし、外であれば少しは感染の対策にもなるかと思いますので、ぜひ前向きに考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問","question":"国なり都の道路の使い方に対する政策の上で、この１１月３０日までの制度が、今後どのような形で変わっていくのか。道路法の改正とか、いろいろと法律の改正もあると思うのですけれども、どのように変わっていくのか、お分かりになったら説明を求めました。","respondent":"稲田土木管理課長","answer":"この件に関しまして、確かに１１月３０日まででいいのかというような話を、まず１１月３０日というところでやっていこうです。都の状況がまだ１１月３０日までという方針しか出ておりませんので、今後、状況を把握しながらやっていきたいと思います。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"国の中で２０２０年に道路法の改正があって、政策の変換というか、切り出したわけなのです。この１１月３０日を節目にして、それ以降というのは、そちらのほうの制度が利用されていくというような考え方でいいのか尋ねました。","respondent":"稲田土木管理課長","answer":"ウォーカビリティとか、そういう考え方もあります。考え方も変わっていくという可能性はあるとは思いますが、その辺はまだはっきりしていませんので、今は何とも言えないところです。","id":"exchange-068"},{"speaker":"大沢委員","kind":"意見","question":"可能性があるから法改正が行われたというふうに私は理解しているのですけれども。利用や資源を考えてやるので、あらかたその考え方というか、そういう理解の仕方では間違っていないかどうかとの意見を述べました。","respondent":"稲田土木管理課長","answer":"まちを発展させていくという中において、そのような歩く形でのまちづくり方針等がいろいろ出ているところです。今の段階ではなかなか急激な変化は見込めないのかなとは思いますが、今、今後はそういう考えも可能性はあるのではないかというふうに思っております。","id":"exchange-069"}]},{"id":"topic-07","title":"（仮称）旗の台六丁目公園整備に向けたワークショップの実施","agenda":"（仮称）旗の台六丁目公園整備に向けたワークショップの実施","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"そこに行けなくなってしまったといった、よく利用する子たちが求めるものがなくなってしまう状況も起きてしまっています。そして皆さんから利用される公園になってほしいと思うので、ぜひそういった声かけについてお願いしたいのですけれども、いかがか尋ねました。","respondent":"高梨公園課長","answer":"今回の用地がちょうど町会の狭間にあるものですから、その周囲の声かけ範囲について検討をいたしました。周知は、幼稚園に通われている園児の保護者の方々の目にもとまるような形でご案内をさせていただければと考えているところです。","id":"exchange-070"},{"speaker":"田中委員","kind":"質問・要望","question":"保育園ですとか、遊べないままになってしまっている状況とかも実際にあるので、周辺の保育園にもお声かけをぜひよろしくお願いいたします。やはりおむつ替えができるトイレも必ずあるようにといった要望をしたいと思いますが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"今、相当離れてしまうのですけれども、ここをお散歩の場として考えられることがあるかどうかということも含めて検討してまいりたいと考えます。１つは、ご意向をしっかり確認しながら検討していきたいというようなことですが、トイレはやはり設置してもらいたくないといった。","id":"exchange-071"}]},{"id":"topic-08","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今、必要数に対してどれだけ整備できていらっしゃるのか、実際の具体的な数を含めて伺いたいと思います。そこのお考えを伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"それ以外のところにも新たに協議を開始しているところも既にございまして、これからますます拡大させていこうというふうに考えてあります。まず区民避難所には対応できるようなものは、今、整備中です。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところを多く避難所として開設していくということでも考えていくべきではないかと思っているのですが、そこのお考えを伺いたいと思います。分散避難ということでいきますと、そこのお考えを伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"区の施設も当然活用を考えているところですが、そういった再検討も含めた形で、区の施設については動きを進めているところです。私どももその考え方のもとに、資機材のところで考えているところでございまして、いろいろ研究してまいりたいと考えています。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、お考えがあれば伺いたいと思います。そこの強化が必要だと私も思っているわけですが、どういった形でこの強化をしていこうと今お考えになっているのか、そこを伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"そちらのほうから始めていきたいと考えています。在宅避難者支援はどういう形でですが、これまでも言われておりました在宅避難者の支援、研究を進めているところです。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"そのアドバイスは、避難所によって大分変わってくるのだろうと思うのですが、そこはどういうふうにされているのかということが１点。「学校を開けるのは誰がするのですか」「その方いないよね」とかという話になってしまったりとか、今回はスペースの問題と、それから。","respondent":"平原防災体制整備担当課長","answer":"そういったところを今現在検討しているところでございまして、当然、そういったところにはこのようなお話を進めさせていただいているところです。感染リスクが高い方々の対応につきましては、今後、進めていく必要があるのではないかというふうに考えてあります。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問・要望","question":"１回、２回で分かるような状況ではないと思うので、どうなりましたかという確認作業はやはり入れていかなければいけないと思うのです。１回やったからいいということは思っていないと思いますが、何回か、機会を捉えて強調していただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それくらいは備えてくださいね」と口では言うのはいいのだけれども、では、それを備えるためにはどうしたらいいかとかあるではないですか。「車でここでペットと一緒にいてください」とか、そういう場所も用意するとか、何か考えられることはいろいろあるではないか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"そういったところもしつこいくらいに呼びかけて、それが本当に実践されるような形で、今後とも引き続き行っていきたいと思います。誰が見ても分かりやすい形になるように、私どもも工夫してまいりたいと考えていますので、よろしくお願いいたします。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4298#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":76146,"voices":224}},{"id":"r02-20200819-9","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"文教委員会","time":"午後 １時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件整理しています。","topics":[{"id":"topic-01","title":"令和３年度品川区立学校使用教科用図書の採択","agenda":"令和３年度品川区立学校使用教科用図書の採択","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"コロナ感染防止の観点から、通常とは違うリモート会議で開催されたと伺っているのですが、具体的にはどのように行われたのかというのを伺います。以上３点伺います。","respondent":"有馬庶務課長","answer":"密を避ける対応を取ろうということで、今回初めて別室で、会議の様子を映しながらという対応を取らせていただきました。なお、会議が始まるときに、本日の傍聴は何名ですということで教育委員会には知らせているという対応をしております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"大田区では会社名を挙げて審議が行われていると伺っているのですが、なぜ会社名を伏せるのかという理由を伺いたいと思います。その辺も確認させてください。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"教科書展示の中でどんな意見が出たかということ等は、教育委員会の中で簡単にご説明をさせていただいているところです。数については、すみません、今すぐにはお答えできません。 １点目の教科書名、出版社名を伏せる理由ですけれども、実際に委員に配っている教科書は、別に伏せてあるわけではありません。ただ、傍聴人はなかなかその教科書が見えづらいというところがあったのかなというところは…","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"審議の効率というのは分かるのですけれども、そこについては改善をしていただきたいと思うのですが、いかがでしょうか。その辺の認識を伺いたいと思います。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"私から２点目のオンラインのほうの回答をいたしますが、３回目以降では、少しでも聞き取りやすくする努力はしたつもりです。やり方についてはまた、そういった意見もあるということで、検討はしていきたいとは思っているところです。 先ほどのイニシャル等の表現につきましては、委員ご指摘のとおり、傍聴人にも分かりやすくということは、内容につきましても心がけているところですので、今後、次回は小学校、３年後になりますけれども、研究してまいりたいと思います。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"「マイクなしでも聞こえると認識しています」みたいなお話なのですが、聞く側の立場に立って、それを判断すべきなのではないかと思います。こちらの勝手な判断なのですから、マイクを使うとか、さらなる改善を求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"}]},{"id":"topic-02","title":"新型コロナウイルス感染症下における区立学校の運営","agenda":"新型コロナウイルス感染症下における区立学校の運営","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"例えば８月の途中から２学期が始まるということで、制服が暑過ぎるのではないかとか、その点はいかがでしょうか。結果的に、そうした場合に、学習の保障というのはどうなっていくのかというのを教えていただきたいです。","respondent":"矢部教育総合支援センター長","answer":"そういう意味では、制服のことについても個別の対応というのは、学校も柔軟にしていく必要があると考えています。ホームページでも、これまでの４月・５月の臨時休業と同じように、そのような形で丁寧に対応してまいりたいと考えています。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"まだ整備はというお話だったと思いますが、現状の見通しとしては、それは早まるようなことというのはないのでしょうか。状況を教えてほしいと求めました。","respondent":"篠田学務課長、工藤指導課長","answer":"こちらのほうが区として対応できるという形に変わってきましたので、Ｚｏｏｍなど、リモートで対応できるような形で体制としては整えているという状況です。 今の説明と併せまして、その場合は保護者の端末とかを活用させていただいているところですが、学校によっては終業式をＺｏｏｍで校内で行っています。… １人１台の前倒しの話もございまして、ＧＩＧＡスクールの関係で、１人１台という形で取り組んでいるところです。…","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"入札がいつ頃になるかというのを教えてください。そちらのほうは要望にしておきますけれども、入札の見通しを説明を求めました。","respondent":"篠田学務課長","answer":"様々な機械の仕様を固めたりとか、様々な点で入札にかけるまでの準備が、どうしても時間がかかってしまいます。公募型の形での入札ということを想定していますので、９月の頭から中旬にかけて入札が実施されるだろうという形で考えているところです。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"それともう一つ、最後に要望させてください。今度は乾燥ですとか、それとコロナを共にどう防いでいくかということは、ぜひまたそういったことも情報収集をして取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"筒井委員","kind":"確認","question":"この区立学校版感染症予防ガイドラインは、確認として、いつ作成されて、いつからこれにのっとって対応されているのかということと、先ほどお話に出た、陽性者が出たということですけれども、感染経路というのはもう全て把握はされているのか尋ねました。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"当初、４月にというところだったのですが、５月の末ぐらいからいよいよ学校が始まるというところでお示ししたところです。そこから随時、バージョンがアップしていったということなので、そこの間につきましては… 今のところ、先ほどもご報告させていただいたとおり、児童・生徒で３名、それから給食調理員が１名、陽性が出たと。いずれも家庭内での感染という形で、学校等…","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"今、バージョン５が最新版ということでよろしいのかということと、これは品川区のホームページとかで掲載はされているのでしょうか。つまり、区民にどの程度広く公表されているのかをお聞きしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"見直し、見直しというところで安定しなかったところもありますので、時期を見てお知らせしていきたいと検討はしております。お子さんにお手伝いしてもらうとかという通知も出ているので、それも踏まえて、またバージョン６を考えております。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。では、バージョン５が最新ということか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"現状はそうです。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"今後秋冬になって、今後体育の授業においてマスクの着用をさせるかどうかということについて、どのようにお考えになっているのかということ。様々あると思うのですけれども、部活動についての感染の拡大を防止するということについて、現状はどのような取組みを行っているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"換気はもとより、そういった工夫によって進めているというところまでは聞いておりますが、実施している学校自体は少ないと認識しております。（３）のアあたりは音楽についての指導もありますけれども、今は暑いので、学校は工夫をして進めていくという考えでおります。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"換気がきちんと十分かどうかという、そこの二酸化炭素の濃度とかを測るとか、ある程度科学的に換気をするということは行われているのか尋ねました。","respondent":"篠田学務課長","answer":"教室内のそういった換気の調査等は、定期的に学校の薬剤師が入って換気の調査をしています。コロナが発生したことによって、常に換気をしているということになりますから、それよりも少なくともいい状況にはなっているだろうと認識しています。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"冒頭の１ページのところに、それともないのか、伺いたいというのが１つ目です。やっていないところもあると伺うのですけれども、小学校１年生からやっているところというのはあるのか、その辺を伺います。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"従来から配置している人員を活用する、また学校支援地域本部を使って、いわゆる地域ボランティアを活用するところもお話ししています。そういった地域人材の活用も含めまして、さらに検討を深めて… 大きく変更はございませんが、当初２ｍ離れてという示しもあったのですが、本区の学校の実態に合わせた数字に変えているところはあります。１学期は実施できませんでしたので、この２学期以降は当初の予定どおり、やる予定です。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"区独自のところは１９ページだということでしたが、ここのどこが独自で、４０分にしてもいいですよというところなのでしょうか。最低限、７時間授業というのは見直すべきだと思いますけれども、これに関しては、お考えはいかがか尋ねました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"このまま２波、３波とかで、できるように捉えております。午前５時間をやっているところも、かなり説明を加えているところも多いということを聞いておりますので、強く教育委員会からも伝えているところです。 センター長より説明のあったところですけれども、教育要領上に定めている狙い・目標を達成することが、まず第一です。時程のほうは説明があったところですけれども、３密回避、学校教育は進めていきたいと考えているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"検査を希望するという方はいたのかどうか、その辺をお伺いしたいというのが一つです。町村会の主要３団体も提言しているし、分散登校期間の経験もしたわけですから、改めて見解を伺いたいと思います。","respondent":"篠田学務課長","answer":"品川区では対応してきていますし、一定の距離を保つとか、そういった形で対応していけるものと考えているところです。知事会等の考え方もありますので、現状の法や都の規定等に沿った形での対応を根本に考えつつという形で、今後の推移を見守っていくという状況です。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"それと、少人数学級のほうは、私が伺ったのは、教師も子どもも一時期、分散登校の経験をしたわけです。区としてはああいう学級規模を少なくして、あの時期の経験をどのように評価しているのでしょうかというのを伺ったので、もう一度説明を求めました。","respondent":"篠田学務課長、齋藤教育次長、工藤指導課長","answer":"あるいは実際に感染したりという方がいらっしゃると、そのお子さんが濃厚接触になりますから、そういう方は受けることになるということです。… そういった方が３７人いて、その中には、家族が陽性になったので念のため受けたら、お子さんは陰性だったという事例もある。それが３７人だです。 少人数にすることで学びが効果的になるというところは、私どもも当然認識しています。当然あろうかと思いますが…","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"今回の２校では、受けさせてほしいという不安の声はなかったという話ですが、ＰＣＲ検査を行政の判断で受けさせないわけです。ですから、最後にこれはいかがでしょうか、伺います。","respondent":"齋藤教育次長","answer":"ＰＣＲ検査は、医療資源も様々あります。総合的にご判断されるべきものと考えておりまして、教育委員会としてお答えすべきものではないと考えております。","id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問・要望","question":"全体と学年でそれぞれいろいろな行事がどうしても中止にならざるを得ない中で、今のまま、教育委員会としてバックアップしていただきたい。その辺を先生たちがしっかりと見ていただいて、通常以上によりそういった対応をお願いしたいと思いますが、その３点をお願いします。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"私からは、１点目のサーモグラフィーの配備に関するご質問に対してお答えいたします。できるだけ早期の対応をしたいと思っていまして、６月の下旬から７月の頭にかけて、必要な機械が配備されている状況です。 私からは２点目と３点目についてです。どちらもとても大事なことだと考えておりますので、常に役員・校長にも連絡をし、明日も校長会がありますので、私から改めて伝えたいと思います。","id":"exchange-019"},{"speaker":"たけうち委員","kind":"意見","question":"昨日も校長先生が大勢いらして、関係者が来てお話があったようですが、ぜひその辺をしっかりとお願いして、終わりたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"まず６ページにある「校内環境の適切な管理」というところの一番下のキのところに、それと同じ内容ということでよろしいでしょうか。異なる点とかがあれば、まず教えていただきたいのが１点です。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"１点目の残留塩素濃度に関するご質問です。水道水に関しましては、今のところ、水道の残留塩素の濃度で問題になっているといった報告は受けていないものです。 調理実習は本当に僅かな時間ですので、１学期の実施を予定していたところは、２学期・３学期に後回しにしているということが考えられます。少し様子を見つつ進めているですので、２学期は極力…","id":"exchange-021"},{"speaker":"せお委員","kind":"質問","question":"そちらでも注意しつつも、１年を通して小まめに水分摂取することというのは、検討されていないのかということをお聞きしたいです。すみません、長くなりました。","respondent":"矢部教育総合支援センター長","answer":"医療的なところもあると思いますので、慎重にこちらでも検討しまして、必要なところは学校に案内していきたいと思います。冬でも脱水症状が起きることはあって、それは十分こちらでも理解していますので、上手に水分補給ができるようには伝えてまいりたいと思います。","id":"exchange-022"},{"speaker":"せお委員","kind":"質問・要望","question":"途中で出てくる、お子さんが学校に出すという健康観察票なのですけれども、これは紙ベースですか。説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"配慮しているところもあるかもしれませんので、また実態を踏まえた後、考慮していきたいと考えております。","id":"exchange-023"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"１点だけ確認させてください。個人面談とか、３月以降のオンライン端末を学校で使う授業以外の方法というのを、どのようにご検討されているのかを説明を求めました。","respondent":"工藤指導課長","answer":"学校に今あるＩＣＴ機器の活用については、教育上効果があると見込まれる場合には、それを教育委員会として認めますという説明をしています。これも配備が進むにつれては、様々な活用が考えられるところですので、それについてはまた検討していきたいと考えています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"２２ページのところなのですけれども、共産党は中止するよう求めていたのですけれども、表の上では全国学力テストは中止となっています。なぜ品川区は実施をしたのかという理由を伺いたいと思います。","respondent":"工藤指導課長","answer":"私どもとしては実施をするというところで、実施状況につきましては、全校実施は終わってあります。集計結果は９月末から１０月にかけて学校に戻りますので、各学校で活用していくという予定です。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"それを早めたりとかはできないのでしょうか。その辺のお考えを聞かせてください。","respondent":"工藤指導課長","answer":"それは様々、コロナ禍に対して業者側のというのもあろうかと思います。最短でいただける日程でというところで、今お話をしている中でというところではあります。","id":"exchange-026"}]},{"id":"topic-03","title":"児童センターの休館","agenda":"児童センターの休館","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"このうちの幾つかはネウボラ相談をやっていたかと思うのですけれども、今、ネウボラ相談は対面でしたか、それとも電話でしたか。曜日が当たっているところもあるのですけれども、この日はどうなのか、説明を求めました。","respondent":"崎村子ども家庭支援センター長","answer":"ネウボラ相談については、現在は面談での相談を再開しております。ほかの休業日と振り替えて対応するようになるかと思いますが、そこは現場の児童センターと調整をさせていただきながら対応したいと考えています。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"児童センターのＬＥＤ化なのですけれども、順次２５の全館、進めていくという計画なのでしょうか。その辺について、もし計画があるのであれば、中身と進捗などについて伺います。","respondent":"廣田子ども育成課長","answer":"おおむね令和４年までに終了予定としておりまして、その他は改築工事とともに実施ということで、全館行うという予定となっています。","id":"exchange-028"},{"speaker":"安藤委員","kind":"意見","question":"参考までに事業の目的と、あと財源なのですけれども、国や都からの補助金事業なのかどうかを聞かせてくださいとの意見を述べました。","respondent":"廣田子ども育成課長","answer":"環境の対策であるとか、もろもろ区の施設全体、令和４年末まで目標ということで決められたものです。財源については、補助金までは、今、手元にないので、申し訳ございません。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"ＬＥＤなのですけれども、最近、ブルーライトが低減されているようなタイプのものも出てきているようなのです。なので、そういったことも勘案しながら、順次入れていただければと思うのですけれども、そういうのは仕様とかに入っているのか尋ねました。","respondent":"廣田子ども育成課長","answer":"ＬＥＤ化については、施設整備課でまとめて執行委任をしている関係で、細かい仕様については手元になくて、申し訳ございません。","id":"exchange-030"}]},{"id":"topic-04","title":"区立児童相談所整備スケジュールの変更","agenda":"区立児童相談所整備スケジュールの変更","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"幾つか質問したいのですけれども、今回１回目を９月にやるということですけれども、何回か説明会を行う考えはあるという理解でよろしいのでしょうか。これも伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"１つ目のご質問、説明会の開催ですけれども、説明を聞きたくても聞きに来られないという方もいらっしゃるのではないかと思います。地域の皆様とのお話の中で、複数回開催することも今後は検討してまいる必要があるかと考えております。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"主に高さの２倍、最大６０ｍの範囲の居住者と権利者と、伺いたいと思います。私は必要だと思いますけれども、そちらについてはどのようにお考えなのでしょうか、伺います。","respondent":"加島児童相談所移管担当課長","answer":"ただいまの計画説明会は、中高層建築物の建築に係る紛争の予防と調整に関する条例に基づいて行いますので、案内を各戸へポスティングしてまいります。この計画説明会の開催についても改めてご案内を行いまして、ご理解いただいているところです。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"条例に定められているところは当然やるのでしょうけれども、今のご答弁ですと、ちょっと不十分な気がいたします。公園の中でかなりの面積を使うわけですから、案内をしてほしいと求めましたが、最後にもう一度伺います。","respondent":"加島児童相談所移管担当課長","answer":"それから、公園利用者への掲示という点ですけれども、失礼いたしました。こちらの建築計画について、公園内に掲示をしてまいる予定です。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望にしますけれども、計画説明会のお知らせをぜひ公園内に貼り出すべきだと思いますので、こちらは要望します。少年野球の関係者の方にも、説明会の後で「やっていたのか」とならないように、所管とも連携を取って、ぜひ周知をしていただきたいと要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"大きく２点伺いたいのですけれども、まず説明会についてです。２分の１程度に縮小させてというのは、イメージとしては、何人ぐらいの方々においでいただくイメージを持っていらっしゃるのか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"こちらの７０名に対して、周辺住宅およそ２００戸程度にご案内をいたしますので、３分の１程度での計算ということになります。そのため、入り切れない方がいらっしゃいましたら、複数回開催することも検討しています。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問・要望","question":"そもそもこの児童相談所をつくるという計画について、品川区としては近隣の方々に知らせたくないのか、知らせたいのか。もっと広範に地域の方々に知っていただいて、理解を進めていただきたいという思いがあるのか、伺います。","respondent":"加島児童相談所移管担当課長","answer":"そのため、一昨年度から、近隣周辺住民の方に向けて２回、事業に関する説明会も行ってまいりました。そして今回、条例で定めるものということで、計画説明会の開催に至っているところです。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"今回、オンラインで内容をご説明して見ていただけるという可能性はありますでしょうか。ご検討いただければ、そんなに難しいことではないです。","respondent":"加島児童相談所移管担当課長","answer":"委員からのオンラインでの説明会開催という点についてなのですけれども、現在、セキュリティー面等、検討を行っていないので、お答えができる状況にはないのですけれども、今後に向けて情報推進課等と検討してみたいと考えております。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"自治体でやって、ただ移管しましたというよりも、自治体でやるメリットを活かしていく必要があると考えています。令和５年度の開設というものは、これから３年間でクリアされていこうとしているのか、その見通しを教えていただけますか。","respondent":"加島児童相談所移管担当課長","answer":"平成３０年度になりますけれども、区立児童相談所の設置に当たって、課題の抽出を区立児童相談所設置基本方針にまとめさせていただきました。１人でも多く業務経験を積ませたいと考えておりますのと、品川区の体制の基盤を固めてまいりたいと考えているところです。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"今のところ、そのご答弁で受け止めておきます。ただ、年限にこだわらず、最終的に事故のないような万全の体制をつくった上での移管としてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"現時点で周辺の住民やその他の区民の方から、児童相談所をここにつくることはやめるべきだなどという懸念の声というか、反対の声というのはあるのか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"事業に関する説明会を２回ほど開催した中で、子供の森公園の遊び場が減ってしまうのではないかというご不安の声でございました。そういったお声に対して説明会、そこの部分を含めて公園を拡張してまいりますので、そういったことで事業のご理解を求めてきているところです。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"オンラインの説明会実施のお話も出ましたけれども、そのように幅広く、多くの方が説明を聞けるような状態にしたほうがいいと考えております。区民の方がしっかりと説明が聞けるような状況にしていっていただきたいと考えておりますけれども、冒頭述べましたとおり、取組みをお知らせください。","respondent":"加島児童相談所移管担当課長","answer":"南青山で起こりました港区児童相談所の建設に関しての住民のお声は、私どもにとっても人ごとではないと考えております。まずはこういった説明会の場を公にはご用意させていただきましたが、児童相談所設置の趣旨、ご理解を求めてまいりたいと考えているところです。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"まず、ガバメントクラウドファンディングで行うという理由は何なのでしょうかというのを１点伺いたいのと、その辺もどうなのかというのを伺います。１回目の２５８世帯が確定したときというのは、その辺の申請希望を新たに募る方策というのが必要なのではないかと思うのですが、いかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"この食の支援をどの程度というのが、こちらに報告はしておりませんが、今の状況のアンケートを実施しています。アンケート実施の募集期間がまだ締切りではないので、子どもの食の支援事業として、実施しています。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただ、あえて財源を寄附に求めたのは、何か意味が、意図があってやっているのですか。そこはどういう理由があるのかというのをもう一度お願いします。","respondent":"三ッ橋子育て応援課長","answer":"単費という考え方は、この事業に対して寄附を集めていって、この事業を推進するために実施していくというのが根本的にあります。ふるさと納税による今回の寄附ですけれども、単費ではないもの、本当に単費ではできないことを実施していこうと考えています。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"少し詳しく教えていただきたいのですけれども、既に２回行われていて、下のアンケートの対象世帯の数字と見ていいのでしょうか。つまり、第１回では２５８世帯に、そして第２回では３１０世帯に食品が提供できたという読み方でよろしいのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"委員の言われるとおり、第１回目は２５８世帯、第２回目は３１０世帯です。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"１世帯当たり食品代が、ほぼ１世帯３,０００円で、それに対して諸経費が２,０００円ぐらい。その戸当たりの経費が５,０００円近くかかっているということで、１世帯当たり５,０００円経費がかかるというのは、何でこのようにかかるのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"今回、第２回目というのはコロナの本当に最中でして、配送料というものが非常に難しい部分がございまして、そこで経費がかさんでしまったことが大きいです。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、これはまた下がっていくということなのでしょうか。配送屋さんは今、コロナだからということで特別に単価が上がっているのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"保管料というものも入ってまいりますので、様々な諸経費がありまして、今回コロナの状況で上がってしまったという状況です。今回のガバメントクラウドファンディングが成功して、しあわせ食卓事業によって配送できる段階で、いろいろと調整はしていきたいと考えています。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問","question":"安藤委員のご質問にもあったように、これは受け取っている側からすれば、毎回あるかどうか分からない。財源の話は置いておいて、とにかく見通しを持てる方向に移行する考えはあるのか、説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"今回、寄附の財源はと考えましても、アンケートの中でも、細々でもいいから継続してほしいというご意見もございました。できる限り定期的に実施したいのですけれども、まず１回は考えているのですけれども、その辺りは本当に工夫していきたいと思います。","id":"exchange-047"},{"speaker":"あべ委員","kind":"意見","question":"そうすると、例えば今回の第２回は前回並みにしておいて、少なくとも次回はいつありますよという考え方もなかったのかなと思う。その辺はいかがでしょうとの意見を述べました。","respondent":"三ッ橋子育て応援課長","answer":"令和２年度は９月１０日から実施する予定を組みまして、そのお金の中で終わらせようという考えの下で、今回は実施いたしました。しかしながら、細々と継続していく考え方などもいろいろと踏まえながら、今後は対応していきたいと考えています。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問・要望","question":"アンケートも４回実施されているということで、集計はまだ１回分も出ていないのですかね。年度の考え方もおっしゃっていましたけれども、継続的な見通しが持てる、頼れる制度にしていただきますよう、これは要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"たけうち委員","kind":"確認","question":"確認なのですけれども、品川区の例の３万円・５万円の応援金も、実は寄附ができますよと。確認です。","respondent":"三ッ橋子育て応援課長","answer":"委員おっしゃるように、これは単独で、子どもの食の支援事業に対して寄附を募ってまいります。","id":"exchange-050"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この５００万円がどれだけ集まるかということがあるから、それはそれで、またしっかりと取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"確認をさせていただきたいのですが、どういう流れがあったのかを確認させていただきたいのと、非常になるほどと思っていたのです。それを一番にやっていただきたいと思っているのですけれども、今年度の事業に関しても同じ気持ちで取り組まれるのかを確認させてください。","respondent":"三ッ橋子育て応援課長","answer":"今回の実施期間ですが、昨年同様９月１０日から、本来は３か月なのですけれども、今回も、１２月３１日まで。支援制度を今後は困っている方、今はコロナの状況ですのでなかなか対応は難しいのですけれども、それは一歩進んでいきたいと考えています。","id":"exchange-052"},{"speaker":"芹澤副委員長","kind":"意見","question":"今年の配送の際にも、ぜひそういった様々な支援につなげるというのを一義的に考えていただいて、取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"}]},{"id":"topic-05","title":"障害年金を受給しているひとり親家庭の「児童扶養手当」受給見直し","agenda":"障害年金を受給しているひとり親家庭の「児童扶養手当」受給見直し","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"ただ、該当者は申請していただかないと、これが適用にならないということで、その部分が非常に大きなハードルだと感じております。今回の年金の子の加算部分の額と児童扶養手当の相差ということで、新たに支給が発生するご家庭が何世帯ぐらいあるか、把握されていますか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"委員のご指摘の部分というのは、把握する方法がなかなか難しい状況でございまして、今現在のところは把握しておりません。","id":"exchange-054"},{"speaker":"あべ委員","kind":"質問","question":"ご案内しやすいかと思うのですけれども、そうしたことというのは、区と年金事務所で何らかのコミュニケーションを取られるのでしょうか。元がこれは厚生労働省の話なので、年金事務所が協力してくれないのはおかしな話だと思っているのですけれどもいかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"例えば国保医療年金課の年金のところに対して伝えていく、またそこから伝えてもらうなど、区としてはその程度になってしまうかもしれません。もちろん、障害者福祉課とも連携を取りながら対応してまいりたいと思います。","id":"exchange-055"},{"speaker":"あべ委員","kind":"質問・要望","question":"この件でも伺ってみたのですけれども、その情報が入らないということで、ちょっと難しいかなと思っているのです。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"逆に言うと、案内が送付される人というのはどういう方なのかというのが分かりづらいので、お伺いします。それがきちんと届くように、横断的に全力を挙げていただきたいということを、私からも要望します。","respondent":"三ッ橋子育て応援課長","answer":"ご案内する方につきましては、こちらに記載しております３名です。そのほかは、窓口に来た方に対してもお知らせしてまいります。","id":"exchange-057"}]},{"id":"topic-06","title":"ぷりすくーる西五反田","agenda":"ぷりすくーる西五反田","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そもそも論で申し訳ないのですが、なぜ幼保連携型認定こども園化を目指しているのでしょうか。伺います。","respondent":"吉田保育施設調整担当課長","answer":"ぷりすくーるにつきましては、現在０歳児から２歳児までにつきましては保育園、３歳児から５歳児につきましては認可外保育施設となっております。並列型か区分型かの今後の方針ですが、どういう方針でやっていこうというところは、特に明確になっているところではございません。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"別に今からどうこうという話ではないのですが、３歳から５歳のところの教育機能といいますか、その点はいかがなのでしょうか。なぜ福栄会で進めてきたのかというのを改めて伺わせてください。","respondent":"吉田保育施設調整担当課長","answer":"ＮＰＯの法人化への支援はできなかったかどうかというところなのですけれども、法人化の支援ができないかと考えてやってきたところではありますが。この事業を継続してやっていけるために事業を移行できるという、お互いに利点がありましたので、このような形態となった次第です。","id":"exchange-059"},{"speaker":"たけうち委員","kind":"質問","question":"ＮＰＯ法人子育て品川が社会福祉法人の認可取得が困難というのはなぜかという中で、社福になるための要件として、今のままでは駄目なのだと。そもそもそこが最初の段階から、恐らく子育て品川は無理だったのか、その辺はどうだったのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"それを進めていくのにいろいろと調査していくに当たり、社会福祉事業というのは結局、社会福祉法人になるのが困難だというところが分かった次第です。それによって、ＮＰＯ法人子育て品川の社会福祉法人化が困難となったというのが分かったです。","id":"exchange-060"},{"speaker":"たけうち委員","kind":"質問","question":"そこは、もし分かる範囲であれでしたら、受け止めとしてはどんな感じなのでしょうか。何かもうちょっとバックアップできなかったのかなと。","respondent":"柏原子ども未来部長","answer":"課長の説明したとおりではあるのですけれども、先ほど課長から説明しましたように、途中で国の法制度が変わりまして。それを継続するために、区でも何ができるかと考えていたのですが、これは断念せざるを得ないというところもありました。","id":"exchange-061"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これから９月下旬に保護者とか、そういう不安がないように、ぜひしっかりとご説明ほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"それはタイムリミットはいつだったのでしょうか。今の形態のままだと、いつがタイムリミットで存続できなくなるという状況にあったのでしょうか、説明を求めました。","respondent":"柏原子ども未来部長","answer":"先ほど課長からも説明がありましたが、当初の目的でやろうとしていた形としては、存続が難しい。そういう意味でご説明さしあげたところです。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"それと、次の法人として社会福祉法人福栄会が挙がっているのですけれども、これは一体、誰が決めたということになるのでしょうか。ＮＰＯ、自分はやめるから次はこの事業者にということで、指定管理を受けている側が次の事業者を決めるということがあるのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"平成３１年の第４期の指定管理を決める段階では、平成３０年度の中で決めてきたわけですけれども、まだはっきりとしていないところでございました。の話につきましては、例えば職員の給料に関してはどうしますかとか、そういう話はＮＰＯと福栄会の間で進めてきたところです。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"区が福栄会を紹介したということですが、福栄会以外の社会福祉法人も紹介したのですか。それとも、福栄会だけを紹介したのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"選定に当たってはいろいろな条件を考えたところはあるのですけれども、規模的にも、あと財政的にも有利なところとして、福栄会というところを区としては紹介した次第です。","id":"exchange-065"},{"speaker":"あべ委員","kind":"質問","question":"福栄会は、さっきも質問の中でありましたけれども、特に幼保一体施設の運営は、たしか１か所もしていないと思います。１か所だけを紹介されれば、なぜ、説明をしてください。","respondent":"吉田保育施設調整担当課長","answer":"福栄会しか紹介しなかったところということになりますけれども、先ほども申し上げたところの繰り返しになってしまうのですが、社会福祉法人の規模感のところと、あとは、ＮＰＯの職員をそのまま次に引き継いでもらえるようなところで紹介した次第です。","id":"exchange-066"},{"speaker":"あべ委員","kind":"質問","question":"なぜ福栄会のみを紹介したのでしょうか。ご存じのとおり、福栄会というのは区のＯＢの方も多く行かれている社会福祉法人ですけれども、そのことは何か関係があったのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"は、そのノウハウが得られるという利点もあったというところで、ＮＰＯと福栄会の間でお互いの価値の共有ができたものと考えております。規模的なものと、社会福祉法人としての安定性を鑑みまして、紹介したところです。","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問","question":"もう１点、前に指定管理を受けていた事業者が、事実上決めることができるのですか。うちができなくなったから、途中からこちらの事業者にしますということでオーケーなのでしょうか、説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"それにつきまして、今度は区でも新たに指定管理者を選定する行為を行います。指定管理者制度活用に係る基本方針の中で、事業の継続性が必要なものについては、選ぶのは区です。","id":"exchange-068"},{"speaker":"あべ委員","kind":"質問・要望","question":"だから、どこでも選んでいただければ構わないのですけれども、そのための選定の手続きというのは、やはり順序に疑問があるなと感じます。ぜひもう少し透明性、説明ができる順番で行ってほしいと求めましたが、何かありますか。","respondent":"柏原子ども未来部長","answer":"今、課長が説明したとおり、まず事業者としてＮＰＯが辞退をさせてくださいと。事業の継続性が必要だというところで、今の段階では継続されるだろうというところがありますので、今区では考えています。","id":"exchange-069"},{"speaker":"せお委員","kind":"確認","question":"１点、確認といいますか、まだ決まっていないようなお話だったのですか。事業内容は、９月下旬に説明が実施されるので、そこまでには決まるということでよろしいか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"事業の内容というか、保育と幼児教育部門はこのまま継続いたします。それから、事業者が替わる可能性があるということについて、今回保護者向けに説明会を行うというのが、３番の今後の予定のところになっております。","id":"exchange-070"},{"speaker":"せお委員","kind":"質問","question":"ということは、今までＮＰＯ法人子育て品川がやってきた内容を、そのまま引き継ぐということで決定というか、変わりないということでよろしいか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"運営方法を、新しい事業者で引き継いだ際もすんなり引き継げるよう、今進めているところです。","id":"exchange-071"},{"speaker":"せお委員","kind":"質問・要望","question":"先ほど９月下旬は運営者が替わるというお話だけのような感じでしたが、その辺までに教育理念とか保育の内容とか、そういったところを示していただけるとうれしいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"}]},{"id":"topic-07","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"そういうこともあるとは思うのですが、あってはならないことだと思いますけれども、理由について、なぜそのようになってしまったのかというのをご説明ほしいと求めました。","respondent":"三ッ橋子育て応援課長","answer":"したがいまして、今回、品川区外のお子さんが亡くなっているかどうか、その確認が少し明確ではなかったです。大変申し訳ありませんでした。","id":"exchange-073"},{"speaker":"あべ委員","kind":"確認","question":"今のご説明のパターンが１６世帯２４人、全てお子さんが区外にいらして、その時期に亡くなられていたということなのでしょうか。確認で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"あべ委員","kind":"質問","question":"細かくて申し訳ないです。今の表現、全委員会一律では行わないというのは、縮小して行うみたいな、何か含みがある表現なのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":53760,"voices":192}},{"id":"r02-20200819-5","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"総務委員会","time":"午後 １時００分～午後 ４時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件整理しています。","topics":[{"id":"topic-01","title":"員会事務局、総務部に関わる報告を先に受けることといたします。企画部につきましては、理事者の入替え後とさせていただきますので、ご了承願います。 それでは…","agenda":"員会事務局、総務部に関わる報告を先に受けることといたします。企画部につきましては、理事者の入替え後とさせていただきますので、ご了承願います。 それでは…","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけなのですけれども、工事現場での熱中症対策です。今後と、発注者の責任としてそこはしっかりとやってほしいと求めましたので、現状と今後の対応についてご説明ほしいと求めました。","respondent":"小林施設整備課長","answer":"現場のほうに冷風が出る扇風機の設置とか、そういったものを逐次現場のほうに、施工者のほうで用意して進めているところです。もちろん現場で働いている方もそうですし、お互いその辺を注意しながら対策を進めている、今後も進めてまいりたいと思ってあります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"元請け、下請け、また、２次下請け、様々現場ではあるかと思います。対策したいけれども、ぜひ隅々までこういった対策が徹底できるように、区としても見てほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"これから世界的にもやはり求められる時期だと思うので、それに対する設備の設置等は、何か特に対応を考えられているのでしょうか。どうしても小さなお子さんのことを思うと、区民にとっても我々にとっても心配な面があるので、その辺について説明を求めました。","respondent":"東野経理課長、小林施設整備課長","answer":"前段の入札に参加した業者が増えたのかというところについてお答えしたいと思います。ＪＶ工事につきましても同じでございまして、こちらも制限をかけておりますけれども、４企業体が応募をされたという形になります。 これに特化した何か設備、何か特殊なものをつけるところは、まだまだ技術革新の最中かと考えています。換気の実施というのは国からも言われておりますので、扇風機も設けておりますので…","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"いろいろそこで保育士、介護士の皆さんが大分ご苦労されたので、何か対応できるような対策を私は前向きに考えてほしいと求めました。もちろん設備的なこともありますので、その辺を考えながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"確認","question":"その確認をしたかったのです。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"}]},{"id":"topic-02","title":"八潮西保育園大規模改修機械設備工事請負契約","agenda":"八潮西保育園大規模改修機械設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひ先ほど申し上げたとおり、感染症対策についても今後考えてほしいと求めました。は現行での安全な保育園を目指して造られると思いますので、しっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"}]},{"id":"topic-03","title":"八潮学園屋内運動場空調機設置機械設備工事請負契約","agenda":"八潮学園屋内運動場空調機設置機械設備工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただきたいのですけれども、要するに、金額が大きいから委員会の報告になったということなのですよね。全体としてはクーラーの導入が進められているという方向は聞いているのだけれども、そこだけ説明していただけますか。","respondent":"東野経理課長","answer":"学校の屋内運動場、いわゆる体育館の空調設備につきましては、順次進められているところです。ガスヒートポンプというタイプを、アリーナおよびもう一つの体育館に設置するということで、本委員会に報告させていただいたものです。","id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今回の空調設備の設置は、３年計画ぐらいでしたでしょうか。どれぐらいの期間なのか、スケジュールも教えてほしいと求めました。","respondent":"東野経理課長","answer":"今回、令和２年度につきましては、第一体育館、アリーナへの設置ということで、２年計画で進めているものです。アリーナ、第一体育館は、どちらかは使える形を取って工事をすると伺ってあります。","id":"exchange-008"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"分かりました。では、居ながらにしての工事ということですので、音ですとか、差し障りのないようにご配慮いただきながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"鈴木（真）委員長","kind":"確認","question":"では、私のほうから１点だけ確認です。先ほど感染症対策というお話がありましたけれども、工事においての感染症対応の金額というのは、予定価格に含めているのか尋ねました。","respondent":"小林施設整備課長","answer":"工事が始まった後にしっかり設計変更なり対応することが、この後、その協議に応じて設計変更なり契約変更することが発生する場合があるです。現段階では、まだ含まれていないところです。","id":"exchange-010"}]},{"id":"topic-04","title":"会計事故の調査結果","agenda":"会計事故の調査結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ伺いたいのですけれども、やはり１４億円という金額の大きさから、ホームページでの報告ですね。そうした広報といいますか、対応が必要ではないのかと思うのですけれども、この辺についてご対応をお伺いしたいと思います。","respondent":"立川総務課長","answer":"この総務委員会が終わりましたら、区のホームページに会計事故に関しまして報告をしたいと考えているところです。","id":"exchange-011"},{"speaker":"松澤委員","kind":"確認","question":"翌２８日に、送信されていませんと言われたものですから、送信されていなかったのだと思って送信してしまったということだと思います。行政側と指定金融機関の中で、解決といいますか、そういう話はしっかり持たれたのか尋ねました。","respondent":"立川総務課長","answer":"今、委員ご指摘のところなのですけれども、指定金融機関側の主張といたしましては、事務フローのとおりだということでございまして、当日の確認すべきデータは届いていないことというのは事実であって、間違いではないという、そういった考え方に基づく発言と理解しています。","id":"exchange-012"},{"speaker":"松澤委員","kind":"確認","question":"それは確認すればいいのにと素人ながら考えてしまうのですけれども、そういうことは起こり得る、今後もあり得ますよね。１４億円でしたか、そこでしっかりとお話をし合った中で、またこの委員会にこういうことを話しましたという報告はあるのか尋ねました。","respondent":"立川総務課長","answer":"今回の報告といたしましては、会計事故調査検討委員会の報告ですので、後日、みずほ銀行側との協議がまとまった時点で、所管のほうからしかるべき報告等をしてもらおうと考えているところです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"確認","question":"そこのスキルが足りなかったというふうに伺ったのですけれども、前の日のも確認してほしいというようなことが主張できなかったのかと思うのです。その辺の具体的な再発防止は、きちんと書面にして契約みたいに取り交わすのか、その辺の確認をさせてください。","respondent":"立川総務課長","answer":"今後、みずほ銀行側と書面で確認を交わすということが必要だと考えていますので、所管のほうにもそういったことで伝えたいと思います。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから、１人の人がやったことに対して、もう一人が何かの形で点検するということが行われると読んでよろしいのでしょうか。そうあるべきかと思ったので伺いますが、いかがか尋ねました。","respondent":"立川総務課長","answer":"そういったダブルチェックを具体的にできるような対応というのを所管のほうでは考えておりまして、既に一部実施していますので、委員のご指摘も踏まえて対応してまいりたいと思います。","id":"exchange-015"},{"speaker":"吉田委員","kind":"意見","question":"みずほ銀行の担当者が前の日のはチェックしないまま言っているのだということを、品川区はその時点で知らなかったということですよね。知らないのが普通なのかもしれないのですけれどもとの意見を述べました。","respondent":"立川総務課長","answer":"今までこういった事故というか、こういった指摘というのは、みずほ銀行側からも導入３年でなかったと。どちらも浅かったということで、こういった事故が起こってしまったというような認識です。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"その人の機転でどうにかなったようなことが、どちらかが知っていれば、もう片方のミスも多少カバーできるということもあると思うのです。協定なのか契約なのかは分かりませんけれども、そのようにすべきだと思うのですけれども、その辺はいかがか尋ねました。","respondent":"立川総務課長","answer":"今後、指定金融機関との協議を進める上で、文書としてきっちり残していきたいというふうに考えております。","id":"exchange-017"},{"speaker":"湯澤委員","kind":"質問","question":"１点お聞きしたいのですけれども、見直しというのは、どなたがどういった形で見直すのか。４月２８日に、まずないとは思うのですけれども、どういった形で再発防止をするような対策を取るのかというのを教えてほしいと求めました。","respondent":"立川総務課長","answer":"共通マニュアルの内容ですが、今まで２つの係で対応が違っていましたデータ送信の手順というのをまず統一いたしました。アラート表示時の対応等をマニュアルに明記して、職員に周知徹底するという内容になっております。","id":"exchange-018"},{"speaker":"湯澤委員","kind":"質問","question":"そうすると、４番にあります再発防止策というのは、既に行っているということでよろしいのか尋ねました。","respondent":"立川総務課長","answer":"周知徹底されないということが起こらないように、みずほ銀行側と協議いたしまして、しっかり文書として双方で確認できるようにしていきたいと考えているところであります。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今回、ちょうど４月２９日が祝日であったということもあって、早めの手続がされていたのでしょうか。そういう区民とか業者の方からのご指摘だけで分かったのか、銀行側からは何か一報があったのか、そこら辺を教えてほしいと求めました。","respondent":"中山会計管理者","answer":"たまたまその日、担当が休みだったので、２７日に処理をしたです。会計管理室側でも銀行側でも、そういった事故が発覚する前に、そこから実際どういう当日の処理がされたのかというところを確認していったところです。","id":"exchange-020"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"そうすると、その間、銀行側は何も調べる手だてがないということだったのでしょうか。同じような金額が１つのところに行くとなると、そこら辺の確認が銀行側も取れなかったというのはどうかと思うのですけれども、どうなのか尋ねました。","respondent":"中山会計管理者","answer":"１回目の正当な振込の後、２回目の送金をしてしまって、銀行は銀行で前もって別段預金を用意しております。先に先方に送金だけされてしまって、実際には振込の金額が足りなくなってしまったというのが、今回の事故の概要になります。","id":"exchange-021"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"これだけ大きな金額を動かす職員の方も責任を非常に感じていらっしゃることと思うのですけれども、再発防止策にまた努めてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]},{"id":"topic-05","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"そこで働いている方、感染力を持つ無症状者への検査についてぜひ実施していただきたいのですけれどもいかがですかというのが１つ目の質問です。テレビで大きく取り上げられただけに、やはり不安を覚える方もいるので、いかがか尋ねました。","respondent":"立川総務課長","answer":"１点目の症状がない者への検査の件ですが、こちらは国や東京都の動向等を注視いたしまして、区として対応を決めていきたいと考えております。もう一点、本日、厚生委員会のほうでも新型コロナウイルス感染症に係る保健所・保健センターの対応についてという報告がなされておりま…","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここでの報告かどうかは別にして、対策本部でそういう事象の情報共有がきちんとされているのかどうか、そこは確認させてほしいと求めました。１週間ではなく日々の更新にしていただきたいと思っているのですが、その点についても伺いたいです。","respondent":"立川総務課長","answer":"区の独自の方針はないのかという、国や都の方針や動向を常に注視しながら、区として対応していくべきものと考えているところです。区のホームページの更新を週に１回ですが、こちらは保健所所管等で出している資料ですので、こういったご意見がありましたことを伝えたいと思いま…","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に２点だけ伺いたいのですけれども、３分の１の利用者でという案内がされておりまして、それはそれで必要な対応だと思います。ぜひそこをご検討いただきたいと思うのですけれども、いかがですかということです。","respondent":"立川総務課長","answer":"今後、こういった人数と料金の関係で動きが出るようなことがございましたら、少しでも検討していきたいと考えております。障害者のある方への対応ですが、こちらは所管のほうにそういったご意見があったということを伝えてまいりたいと思います。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問・要望","question":"情報共有で１点だけ要望といいますか、介護職員の方から私に相談がありました。課長にお聞きしますと、濃厚接触者をきちんと確認してからという対応をしっかりしているのですけれども、早急に言ってあげてほしいという要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"ずっと生活者ネットワークとしては要望をしていることなのですけれども、どこでどういう発生があったかということは公開してほしいということが。その辺ももしこの委員会として答えられる範囲、区としての姿勢というのがあれば、伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区としてもそういうことを行っているわけですから、それで足りないということであれば、区独自の判断ということはあってしかるべきかと思います。それから、ＰＣＲ検査が一番その方たちが求めていることではないかと思いますので、意見として申し上げておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点、濃厚接触者ですという通知が来たときに、それはどのように対応してくれるのですかという声があります。それはどのようにしてくれるのですかということに対して、国に求めることも当然だと思うのですけれども、いかがか尋ねました。","respondent":"立川総務課長","answer":"そうも言っていられませんので、区の感染状況について分かりやすく、情報発信がどうできるかというのは所管と協議してまいります。１５分以上マスクを外して会話を１メートル以内で継続したとか、今後所管と協議いたしまして、情報発信をしていきたいと考えているところです。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"それも本当に数秒で確認できますので、そういうこともそろそろ考えたほうがいいのではないかと。どうしても差別的な扱いを受けるということが、これだけ国民の皆さんの恐怖心をあおったのですから、それを拭うのは難しいかと思うのです。","respondent":"立川総務課長","answer":"庁舎におきましては、どういった形がふさわしいかというのは検討していきたいと考えております。そういったことも聞いておりますので、どういったことができるのかというのは、所管のほうとも情報共有しながら進めていきたいと考えております。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"何しろ不安だらけの世の中なので、何とか少しでも払拭できるように、いろいろ考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]},{"id":"topic-06","title":"品川区新型コロナウイルス対策支援寄附金の募集","agenda":"品川区新型コロナウイルス対策支援寄附金の募集","exchanges":[{"speaker":"松澤委員","kind":"確認","question":"寄附金なのですけれども、区のホームページを確認しました。１６.６％で６５人、百六十何万円の寄附があるのですけれども、これは行政として今のこの数字の上がり方をどのように捉えているのか。","respondent":"伊東税務課長","answer":"ほかに、広報のほうも異例に何回も載せていただく予定でおりますので、そういう形での周知でも広めていこうかと考えているところです。７月１３日からスタートしておりますので、８月１日を経て、目標達成に向けていこうかと思っているところです。","id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"寄附金がしっかり１,０００万円に到達することを願うとともに、こういう困っていることがありますとかを、聞いたことは何かあるのか尋ねました。","respondent":"伊東税務課長","answer":"具体的、まさに物的支援だとしたら何を買ってどこに送るかというところまでは考えていなく、効果的な支援といいますか。目標達成１,０００万円ということで、その集まり具合というのを見ながら考えていかなくてはいけないかと考えています。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうですね。ここにこうやって使ってほしいとか、こうあるべきだということを、そういうのもしっかりしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"吉田委員","kind":"提案","question":"でも、一方で、だからこういう制度を作りましたという先ほどの課長のご提案の内容があったほうがいいのかと私自身は思います。それはどう感じるかは個人のいろいろな感じ方もありますけれども、もし何かご見解があれば伺いたいと思いますが、いかがか尋ねました。","respondent":"伊東税務課長","answer":"そういう考えといいますか、その後いろいろと検討を重ねて、今回こういう形での募集を開始したです。言葉で書くかどうかというところはいろいろありましたけれども、そういう思いでスタートしたところです。","id":"exchange-035"},{"speaker":"吉田委員","kind":"意見","question":"例えば、こういう寄附先とかいうレベルで１,０００万円という金額だと、何かちょっとなと。これは意見で結構ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"本当に現場が求めているものをその場面その場面で聞き取っていただきたいと思っておりまして、何か月間、オンラインだともっと分からなかったのです。いずれも要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-07","title":"指定管理者選定における外部委員導入の試行","agenda":"指定管理者選定における外部委員導入の試行","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"このタイミングをどう考えているのか伺いたいのと、２名が外部委員だと、結局８名が区の関係者ですから。３つ目の質問で、この外部委員というのは誰がどう決めるのか、ご説明ほしいと求めました。","respondent":"佐藤企画調整課長","answer":"１点目の、これまでも客観性・公平性・透明性の確保に努めてまいりまして、利用者満足度調査や労働環境チェック等をしてまいったところです。基本的に選定は各所管のほうで行いますけれども、様々、公平性・透明性を担保できるようにアドバイス等をしていきたいと考えております。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう少しご説明いただきたいのですけれども、客観性・透明性をより担保できるようにしているという中で、本区の２名というのは少ないのではないかと。結局、外部委員を指名するのも区ですから、やはり区民から見れば、これで客観性・透明性と言われてもとならざるを得ないと思うのです。","respondent":"佐藤企画調整課長","answer":"１点目、財務状況のチェックのところなのですけれども、私の説明が悪くて申し訳ございませんでした。２名というやり方ははっきりしておるのですけれども、今後２名が妥当なのか、今後考えていきたいと思っています。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"選定理由や経過や評価の基準がＡ４の資料の裏表ぐらいしかなくて、点数はそもそも発表されていないし、非常に不透明だと考えています。選考過程の公表、それをぜひこれを通じて検討していただきたいと思うのですが、最後にいかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"この間、具体的に平成３０年ぐらいから指定管理者制度の客観性・透明性を高めるという検討はしております。今検討をしており、私どもも透明性を高めたいという意識はありますので、その辺を踏まえて進めていきたいと考えています。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"本格的に実施していくものはどのようにスケジュールとして見込んでおられるのか、伺いたいと思います。外部委員に求めているのが経費のというふうに聞こえたのですが、それから、そういうところを見ていくための外部委員ということなのか尋ねました。","respondent":"佐藤企画調整課長","answer":"ご質問を２点頂きまして、平成３０年の後半からずっと検討していまして、今年度中には本格実施に向けて進めていきたいと今考えているところです。法令遵守の３本柱で今考えているのですけれども、そこだけでさすがに止めるということもありませんし…","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"例えば、先ほどの外部委員の人数のこととか、その間にそれこそスピード感を持って考えていくと思っていいのでしょうか。私たちとしても、外部委員２名というのは少ないのではないかと思って伺うのですが、その辺についてはいかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"本格実施に向けては、先ほどご答弁したとおり、今年度中にまとめて、来年度から進めていきたいと考えております。その辺も見極めて、より透明性・客観性・公平性を確保できるような仕方を、他区の事例も見ながら考えていきたいと考えております。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"説明に出てこなかったような気がしたのですが、それは前提として考えてよろしいのでしょうか。ごめんなさい、それだけご答弁ほしいと求めました。","respondent":"佐藤企画調整課長","answer":"労働環境チェックに関しましては、ご案内のとおり、平成２６年から４年目の事業者に対して試行という形でやっておりますが、ほぼ毎年やっていますので、そういった形で進めていきたいというふうに考えております。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点確認させていただきたいのですけれども、間違っていたら言ってください。今回の外部委員を入れるということと、やはり介護施設や障害者施設は事業の継続性の観点から、この考え方を何か変更するのか尋ねました。","respondent":"佐藤企画調整課長","answer":"公募をかけるということは、何年延長するかはまだ検討しているところなのですけれども、そういう形にはしなければならないと考えています。外部委員も入れますし、労働環境チェックもやりますし、公募をしないというところに関しても検討していくというところです。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、意見ですけれども、やはり介護施設や障害者施設、保育施設も、事業の継続性はとても大事だと思います。地域との関係というものが積み上げられていますので、そこはぜひ引き続き重視をしていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"}]},{"id":"topic-08","title":"令和２年度都区財政調整交付金当初算定結果","agenda":"令和２年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"逆に地方消費税交付金が２８％増ということですけれども、そんなことはあるのか、伺います。算定されていないもの、調整中なものは何か、そこを伺いたいと思います。","respondent":"品川財政課長","answer":"その段階で出された令和２年度の見込額とほぼ変わらない数字となっておりますので。２つ目の財調算定については、これから、これから東京都と交渉していくという流れになってくるということになります。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"２３区として、具体的に都に求めている新型コロナウイルス感染症対策というものは何なのか。そこをご説明いただけますか。","respondent":"品川財政課長","answer":"これからまた２３区でまとめて、やはりこの間、そういう費用が対象になってくるかと思います。当然、こういう財調の対象になるような部分ではないかと思いますので、その辺についてはまた今後の交渉の中で出てくるものだと考えております。","id":"exchange-047"}]},{"id":"topic-09","title":"マイナポイントによる消費活性化策","agenda":"マイナポイントによる消費活性化策","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１０分の１０なのかということだけなので、そこだけお答えいただきたいのですけれども、必要な体制整備にこそ財源を私は使うべきだと思っています。質問は１０分の１０かどうかだけご説明ほしいと求めました。","respondent":"山本情報推進課長","answer":"申込支援等に関して、そういった部分は１０分の１０、補助の対象になっております。","id":"exchange-048"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１０万円の給付金等も含めた中で、マイナポイントの申請支援もやられていて、私も第二庁舎の３階のところで申請をいたしました。推進されている中で、あとは、申込支援がどれだけ活用されているのかという現状をお聞かせほしいと求めました。","respondent":"山本情報推進課長","answer":"この後、発行まで今、最大３か月ほどお待ちいただいているところがあり、交付率のほうに反映されてくるのかと思っているところです。それから、申込支援のところですけれども、地域センターを含めまして、７月の１か月で約７００名の方に…","id":"exchange-049"}]},{"id":"topic-10","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"質問なのですけれども、求める情報が探しづらい、どういうテーマやどういう項目に検索が多いのかという分析は既にされているのか。リニューアルするための大事な情報量だと思うのですけれども、どういうページでどういう項目の検索数が多いのか、ご説明いただけますか尋ねました。","respondent":"大澤広報広聴課長","answer":"どこのページに何回アクセスされているかというのは毎月出していて、今ですと、新型コロナウイルス感染症とか給付金のページが多く見られています。リニューアル後は一番上に、見られているページの上位５項目か６項目を出して…","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、自治体の場合はどうなのでしょうか。そういう利用者の目線に立ったリニューアルを丁寧に進めていただきたいと要望して終わりたいと思います。","respondent":"大澤広報広聴課長","answer":"区民の方がやはり何かでお困りになったときに、区のホームページを開くということが一番だと思っていますので、困ったときに解決方法を探せるということを一番に考えて、リニューアルに臨みたいと考えております。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"それをどうして載っていないのですかというのを広報広聴課に伺ったときに、所管がその情報を上げてこないと、それは一方でどうなのだろうかと。各課職員のというだけでは駄目なのではないかと思うのですけれども、もしその辺について何かお考えがあれば伺いたいと思いますが、いかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"１点目の見やすさでありますけれども、１つ作って、今後も続けてまいりたいと考えています。そういう面では調整機能をもちろん持っておりますので、今後もその辺は統一感が出るように努力してまいりたいと考えています。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから全部の意見を聞いたら、例えば、区としてはそういうパブリックコメントというのはたくさん上げてほしいと思っているに違いないと思うので。そういう意見を募集する前に説明会とかをもっと開いてくれというのが要望ですけれども、そういう場だと思いますので、要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"須貝委員","kind":"質問・要望","question":"多くの区民の要望に応えたいということがこのようにつながってきたので、これは際限なくきっと続くのかと思うので、見やすいというのはどうなのか。今までの皆さんの要望の結果がこのホームページのトップページに表れていると思いますので、それでいいのではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"湯澤委員","kind":"意見","question":"１０代とかそのぐらいの世代になると、親に電話するとき、親の携帯の電話番号を知らないと。これは意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問","question":"何点か、少し気になったことを質問させてください。その対策をすれば、もし仮にこの前みたいな大災害が起こったときに、絶対にそういう障害が起こらないということなのか尋ねました。","respondent":"大澤広報広聴課長","answer":"１,０００件分か２,０００件分を、２割ぐらいの方を誘導できれば、かなり軽くなります。絶対に障害が起こらないかと言われると、２２万世帯からアクセスが一気にあると分からないのですけれども、まず大丈夫だと考えています。","id":"exchange-056"},{"speaker":"松澤委員","kind":"質問・要望","question":"課長がこれを見てほしい、これを聞いてほしい、もっと見やすくなるのかと個人的には思ったりしています。情報ツールの今一番求められているところかと思っていますので、もっとシンプルに行政がこれを見てほしいというのをまとめていただく、素人ながら。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問","question":"すみません、１個だけ質問。先ほどパブリックコメントというお話が出てきたのですけれども、それをチャットボットでやり取りする予定というのは今のところありますか。","respondent":"大澤広報広聴課長","answer":"チャットボットは。","id":"exchange-058"},{"speaker":"松澤委員","kind":"意見","question":"ぱっと気になったときに携帯で打てるかと。画面にパブリックコメントという欄があってもいいのかと思いましたとの意見を述べました。","respondent":"大澤広報広聴課長","answer":"チャットボットは、今のところ、ここに書いてあるものはＬＩＮＥでもできるようにはする予定があります。そのほかにも、チャットボットを使うものは今検討していて、具体的にパブリックコメントを今どうしようというところの検討はしていないです。","id":"exchange-059"},{"speaker":"新妻副委員長","kind":"質問","question":"ありがとうございました。ホームページとかの専門の方がいらっしゃるのかということと、あと、関わっている人数についてもお伺いしたいと思います。","respondent":"大澤広報広聴課長","answer":"それについての取りまとめや検収を担っているのは、広報広聴課の報道の担当職員４名が携わっています。業務の中で専門知識は身につけていますが、それに特化した職員というのはいませんので、それは専門業者と相談しながら進めております。","id":"exchange-060"},{"speaker":"新妻副委員長","kind":"質問","question":"ということは、デザイン的なところというのは、外部の業者がやっていらっしゃるということでよろしいか尋ねました。","respondent":"大澤広報広聴課長","answer":"デザインそのものは、業者と職員とで相談しながら進めているという形になってあります。","id":"exchange-061"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"例えば、私が情報を求めてホームページを見るときに、感染者がどれくらいいるのかということがすぐに見られるということを期待するわけなのです。広く知りたいという要望もあるかと思うのですけれども、情報提供としてはどうなのだろうというところを感じますが、いかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"緊急情報については、おっしゃるとおりで、分かりやすい情報になるように努めてまいりたいと思います。なかなか全部そろって一斉にできていなくて、時間差で入れている状態なので、一定そろったところで大きく周知を図りたいと考えています。","id":"exchange-062"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"それですぐにＬＩＮＥだというのが分かるわけです。なので、そういう見せ方もぜひ工夫してほしいと求めましたが、いかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"ＬＩＮＥの周知につきましては、より分かりやすく、簡易に登録できるように工夫してまいりたいと思います。","id":"exchange-063"},{"speaker":"新妻副委員長","kind":"確認","question":"広報広聴課の皆様は既に２３区全ての自治体のホームページは確認をしていただいているかと思います。ご答弁ほしいと求めました。","respondent":"大澤広報広聴課長","answer":"広報広聴課で他区のホームページは研究しておりますので、いいところをまねして、いいものにしたいと思います。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2176#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":61562,"voices":192}},{"id":"r02-20200820-14","meetingId":"r02-cm08","date":"2020年8月20日","dateIso":"2020-08-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今のご説明を伺っていると、しかし課題ということで、この労務管理の中に挙げられている。それをちょっと伺ってみたいと思います。","respondent":"黒田人事課長","answer":"特にＩＴ系の事業所ですと、人事からの通知も超過勤務命令はしないということで、出勤と退勤はきちんと連絡するようにということを通知しています。区の職員の場合３８時間４５分と定められておりますので、そういった中では…","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"まずはそういうことのないような労務管理ないしは勤務条件というのは、これから課題として考えていかれる場合にもよくよく考えていただきたいということは非常に思いましたので、よろしくお願いしたいと思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"ですから、積極的にこれもあれもというようなＩＴ業界と同じような感覚では、私は進んでいってほしくないと思います。どうしても個人的に１人でやることですから、出る機会がそれだけ減るわけですから、体力的にも身体的な問題にも影響が出てくるのかなと。","respondent":"黒田人事課長","answer":"こちらの対策本部の中でも、仕事が縮小できる職場については繁忙な職場へ応援するということを方針として打ち出して取り組んでまいりましたが。そういった意味では職員に限らず、民間事業所が動いていないとなかなか対応しにくいといった側面もあろうかと思ってあります。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは実際に業務改善したわけですから、区民に寄り添った業務をきめ細かく今後も推進していっていただきたいと私は思います。意見で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"２か月あまりテレワークを実施したということですが、実施した実際の状況というのはどのような声があったのかということを伺いたいのと、今はそこまで実施はしていないということでよいかということをお聞きしたいと思います。","respondent":"黒田人事課長","answer":"こちらは先ほど資料のご説明の中で申し上げたとおり向く職務と向かない職務がある中では、これは難しいなというのが正直な感想です。現在行っていないのかですが、現在は原則的に在宅勤務は行っていないというような状況です。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどから説明されているので、今後変えていかなくてはいけないという認識でいらっしゃるのか、そこのところを確認させてほしいと求めました。これは率直に１つお聞きしたいのが、勤務条件というのはどういうものなのか、そこのところをお聞きしたいと思います。","respondent":"黒田人事課長","answer":"自宅で勤務することだけがテレワークではありませんので、施設長会等々があれば、そういった様々な時間を有効に使うといった面での検討が必要かなと。ここを外から容易にアクセスするために変えるということは難しいのではないかと考えていますので…","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"ちょっとその辺がイメージできなかったので伺いたいのと、もう一点、これもどういったものが想定されているのか。これからの検討ということではありますが、今、想定されているところを伺いたいと思います。","respondent":"黒田人事課長","answer":"よく考えて取り組んでいく必要があると考えていますので、検討する中でやめることができるものがあるのではないかということは考えているところです。逆にそこが進めばわざわざ行く必要がないといったところで、対人業務が縮減できるといった面もあるのではないかと考えています。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"印鑑とかをなくすということで改廃の例が説明されました。その一方で、特に在宅勤務というところでは難しい部分がいろいろなところであると思うので、丁寧に検討をしていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"質問なのですけれども、２の（２）のところで、このテーマの提案区が品川区になっているのです。これは、品川区としてはなぜ提案区になったのかとの意見を述べました。","respondent":"黒田人事課長","answer":"少し改善できないかといったところの業務成果を使おうということで取り組んでまいりましたので、直接的な関係はあるというものではございません。一定程度成果を出したものについては現在も利用しておりますので、ＰＴとしての活動はしておりませんけれども、継続しています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そうすると、誰が、どういう部署のどういう方が何人くらい入られて検討してきたのかということについてもお聞かせほしいと求めました。これからもこの課題が挙げられて、品川区としてはどのようなメンバーで、どこでどのように検討されていくのかについても説明を求めました。","respondent":"黒田人事課長","answer":"区として今後本格的に取り組むということであれば、そういった形で様々な機会を通じてご報告申し上げるということになるのではないかと考えています。今はどういったことができるかといったことを検討しているところで、企画部と総務部が中心で…","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、どういう可能性があるかというような段階ということで捉えていいのでしょうか。それから、現時点でテレワークになじむものは非常に少ないというお話でしたけれども、その点についてもお聞かせいただけたらと思います。","respondent":"黒田人事課長","answer":"チームを作って検討するということではないのかですけれども、可能性を検討しておりますので、検討を進めていくべきではないかと思ってあります。ただ、出来る限り時間を効率的に使って…","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に働き方というところも、やはり一番初めに申し上げましたように、残業をなくして人間らしい働き方ができる、区民サービスをさらに向上させていく、こういうところを目的としながら、働き方改革を進めていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"実施期間中平均約３割と出てきて、よく３割も削減して、やや驚きもあります。ちょっとこの実態を伺いたいのですけれども、平均すれば３割の方が庁舎に来ていないと、お伺いしたいと思います。","respondent":"黒田人事課長","answer":"逆に民間事業所が動いていない関係で、どうしても工事が進められないとか、先送りしているというところは３割よりも多い割合で在宅勤務ができたと。職員が３人いまして、新たに実施しなければならない事業も発生している中では…","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"そうでもない部分が細かく見ていけばあるのだなということで、今、ご答弁を伺って感想として思いました。電子窓口みたいなことで進められる手続きというようなことも今後は出ていくのだろうと思いますが、その辺についてのご見解をお伺いしたいと思います。","respondent":"黒田人事課長","answer":"先ほどのモデルで言いますと業務効率化などのところで検討して効率化を進めて、テレワークを検討する機会として様々検討していって、ご指摘いただいたようないろいろな面でサービスが展開できればいいのではないかと考えています。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう技術の進展とともに社会的ないろいろな通信技術のインフラが進むとともに、ＩＣＴでできる効率化から進めていただきたいと考えていますので、今後。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"８割だ、どこかの課などは８５％来ていませんとかいう話もあったりしたけれども、共同のテーブルでもいいと思う。さっき企画部とやっていると言ったけれども、そういうところまで踏み込んで検討しているのかどうかだけ教えてほしいと思う。","respondent":"黒田人事課長","answer":"今、職員個々の机がないというような、そういったところも今後様々な観点から検討が必要であろうと考えております。この場合は、こういった様々申し上げました課題について検討していく中で、そういった観点から今後も検討を進めていきたいと考えています。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺のところをやはりよく考えていただきたいと思うのだけれども、そこら辺まで突っ込んでやってくださいというのは要望だけにします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ですから、やはり書面というのは一方的なやり取りですから、早く構築をしていただきたいという要望です。係長とやって決裁権のない係長に負担をかけるのは申し訳ないので、ぜひそういうものを早急に進めていただきたいと思うのですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"在宅勤務でありますと勤務ですので、今回ちょっと様々な中でうまくいかなかったというところも準備不足であったと考えています。これはウェブ会議のような仕組みはありませんでしたが、こちらのほうは、そういったことも含めて引き続き検討してまいりたいと思ってあります。","id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"そういう意味でも、ただ課題ですから、さっき言った秘匿性であるとか脆弱性であるとか、そういったものは必ずクリアできると思っています。２０２７年でしたっけ、時間もそれほどないので着々と、ぜひ品川区は先進区として進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほど来理事者の方、そして委員からも業務の効率化という仕事の効率性を求めるという一環の中で、このテレワークというものがあるわけです。先ほど来のこの資料を頂いた部分の３つの課題がありましたが、それについて今後の見通し、方針はどのようにお考えになっているのか説明を求めました。","respondent":"黒田人事課長","answer":"そういった組織風土も今後いかに継続して育てていくかというところもありますので、プロジェクトチームとして継続するかというところはちょっと今後検討が必要ではありますが、今後引き続き伸ばしていきたいと考えています。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"職員が今後引き継いでいくというところには、人材育成というところがあるわけであります。社会・経済・政治の動静を踏まえながら、そこのところ、若手の方に焦点を合わせて意識改革をすべく何か取組みをされているのか説明を求めました。","respondent":"黒田人事課長","answer":"新規採用から職層ごとに新規採用１年目、２年目ということで、例えば心構えというのは座学で研修をしています。今年度はちょっとコロナの関係もありまして実施できていないのですが、今後も人材育成のプランの中で検討してまいりたいと考えています。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/988746?Template=document&Id=6094#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":27879,"voices":44}},{"id":"r02-20200821-18","meetingId":"r02-cm08","date":"2020年8月21日","dateIso":"2020-08-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時１６分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問","question":"先ほど、口頭で５事業のご説明があったのですけれども、どうして説明資料として出されなかったのか。どういったものがあったのかといったことも伺いたかったと思ったので、その辺に関してお知らせください。","respondent":"古巻文化観光課長","answer":"この場ではなかなか内容のご説明がためらわれるところがあるのですけれども、それから、幾つかあるというような形です。採択されたものについてはしっかり進めていっているところですので、開催ができれば期待ができるのかなというふうに考えているところです。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"２種類とかはよく分からなかったのですけれども、次回から、そういった資料提供も充実させてほしいと求めました。要望でおしまいにします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"渡部副委員長","kind":"確認","question":"僕も確認をしていたのですが、この辺の事業の説明ですとか採択の決定は、どこかでこれは報告があったのでしょうか。それだけ確認したいのですけれども。","respondent":"古巻文化観光課長","answer":"事業は今年度予算なのですけれども、４月からの開始ということがありましたので、ある程度、予算のめどがついた段階で申請を開始しています。実際に、今年の６月にかかろうかというぐらいのところであったものですから、内容についての報告についてはしていないというのが現状で…","id":"exchange-003"},{"speaker":"渡部副委員長","kind":"質問","question":"どういうもので、どういうふうに決定されたかぐらいの資料は、お願いできますでしょうか。委員長、それでいいですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"令和２年度の文化プログラムについて、この開催か中止か判断する際の基準の中心点についてもう少し教えていただきたいというのが１点です。どういうものが発生していて、そういったものというのはどういう考え方になっているのか、これを２点目にお伺いしたいと思います。","respondent":"古巻文化観光課長","answer":"なるべく開催をしていこうという動きで、今、進めているところです。収入がなくなってしまったものもあるというようなところで、主催者がそれぞれ協議しながら、適切にやっているというようなところです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"その上で、具体的に２点、要望とともに伺いたいのです。これについて、区として可能な限り補償をすべきだと思うのですけれども、いかがか尋ねました。","respondent":"古巻文化観光課長","answer":"様々な国や都の補償制度もあるかと思いますし、そういったものも組み合わせて、総合的に判断するべきものというふうに考えております。特に、一定の補償と言いましょうか…","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"区としてできることというのは積極的にやっていただきたいと言いますか、ぜひ、お願いしたいと思います。何かございましたらご答弁ください。","respondent":"古巻文化観光課長","answer":"先ほど申し上げたとおりで、今、特につけ加えることはございません。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"第１回が令和２年７月２９日、それ以降、第２回以降の情報はホームページなどで掲載をされているのですか。その周知状況を説明を求めました。","respondent":"古巻文化観光課長","answer":"基本的に、採択された団体には周知しておりますけれども、特に一般に広くというような形での周知を行っていないところです。２回目は、３回目以降については、まだ決まっていないというような状況です。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"２０１９年１２月５日とかにやられているものと同じような形で今後やっていくのでしょうかということと、これは、一般の方というのは見ることというのはできないのか尋ねました。","respondent":"古巻文化観光課長","answer":"そういった意味では、公表する場合については、オンラインの接続のための情報を公表すれば視聴できなくはないというような状況です。特段、何か特殊なソフトが要るわけではなく、そちらが使える環境であればアクセスは可能だというふうに認識をしております。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"１つには、どのようなことが予定されていたのかというのを１点お伺いしたいのと、しながわ文化プログラムのロゴマークが入っていなかったのです。しながわ文化プログラムの位置づけがあるので、そこはどうなのかなというふうに思ったのですけれども、その２点をお伺いしたいと思います。","respondent":"古巻文化観光課長","answer":"今年度予定されていた舞台系の事業ですが、９月２７日に予定されておりましたドリームステージが中止になっております。ティーンズコンサートという形で１０月１１日に予定されていたものですが、これは、そういった観点からの中止というふうに認識をしています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"文化プログラムの推進の１つとして、何かあるのか、区のお考えがあればお聞かせほしいと求めました。思いだけお伝えをします。","respondent":"古巻文化観光課長","answer":"具体的に区としての方針が出ているわけではないのですけれども、スクエア荏原でありますとか、効果的なものであるというふうな認識をしております。このあたりは、しっかりと考えて…","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"そういうアーティストや子どもたちの、どう安心・安全が保たれた上で、品川区が何ができるのかということをご検討いただきながら。来年の東京２０２０大会も、どういうふうな形になるのかということも未決定のままではありますけれども、ぜひ取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"いろいろな心の充足感というものを提供していただいている、非常に貴重な存在だなと、改めて私も思う１人なのですね。作品の放映とか、その辺について、重ねて考え方を説明を求めました。","respondent":"古巻文化観光課長","answer":"区として定まった方針というものがあるわけではないのですけれども、そのあたりの可能性も検討していくことは必要なのかなというふうに考えています。ステージのＹｏｕＴｕｂｅライブ配信も予定しているので、さらに効果を見極めまして…","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"品川アーティスト展２０２０については、私も今チラシを見て、ライブ配信があることを確認しました。そういう部分では、ぜひ、そういう工夫をより一層考えていただいて、まさに醸成をしていただきたいなと思いますので、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"}]},{"id":"topic-02","title":"東京２０２０大会の新競技日程","agenda":"東京２０２０大会の新競技日程","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"伺いたいのは、この立候補ファイルの記述ですね。そして、この猛暑、酷暑時期での開催日程がまた今発表されましたけれども、区としてはどういうふうに考えているのか、ここは伺いたいなと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"立候補ファイルの記載についての区の見解ですが、その当時の立候補ファイルがどのように記載されているかということは、私どもは意見する立場ではございませんでしたので、今、意見として区として言うことはできかねます。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区だってアスリートファーストということを言っているわけですから。質問を変えますけれども、開催について、そのお考えだけ聞かせていただきたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"品川区としては、この時期に行われるということを大前提の上に、アスリートファーストをしっかり体現できるような準備をしていくです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"意見","question":"目指していくというのであれば、やはり必要な考えを表明すべきだし、それをしっかりと発信していくべきだというふうに私は思います。非常に残念ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"西村委員","kind":"質問","question":"改めて伺わせてください。どうなるかなというふうにイメージしていたのですが、スケジュールがどういうふうになるか、もし決まっているところがあれば教えていただけますか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"梅雨が長引いた場合にはというご質問ですが、特段、それで日程が変更になるとか、そういったことは聞いたことはございません。そのままの日程で行うようになります。","id":"exchange-018"},{"speaker":"西村委員","kind":"質問","question":"では、屋外でも、雨の中のスポーツであったり、そういうことになるということでよろしいか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"いろいろな場合が考えられると思うのですけれども、恐らく、いろいろな競技で基準があると思うのです。一時中断、そういった競技の中のルールがあると思いますので、それに従っての判断になるのかなというふうに認識しております。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"ただいま、日程の公表のお知らせをいただきました。東京都等を通じて、この大会開催に向けてどういう検討が行われていて、何か教えていただけることがあればお知らせほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今現在は、東京都からは、主に聖火リレー等のことについての検討等をしているというふうに聞いております。聖火リレーのときも一定程度の会議室を諸室としてお貸しするなどという予定がございましたので、今、しています。","id":"exchange-020"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"意見","question":"ＬＩＮＥスタンプについてなのですけれども、予算がどうなっているのか、お知らせくださいとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これは、今、決定金額については持ち合わせはないのですが、全体の機運醸成・啓発の予算から出しております。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"ＬＩＮＥスタンプのイラストが変わったのですか。そういった場合というのは、新しいデザイナーが入ってということになるのかと思うのですけれども、その辺についてお知らせほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"おっしゃるとおり、今までのキャラクターの絵をもとに、それを崩した、少し緩い感じにデザイナーに描き直していただいて、言葉等を追加して作ったものです。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"去年のＬＩＮＥスタンプの金額よりも上下が多少あるということですか。今、分かる範囲でいいです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"昨年度なのですが、最初に作ったときは、これはほぼ職員で作ったので、ほぼ費用がかかっていないです。今年度に関しましては、絵柄を少し変えたりしているので、デザイナーさんに入っていただいているので、金額はかかっています。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"ちなみに、このＬＩＮＥスタンプなのですけれども、現状、第１弾はどのくらいダウンロードされているのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"第１弾のほうは販売数が１００個です。","id":"exchange-024"},{"speaker":"つる委員","kind":"提案","question":"これは何年か前に当委員会で提案させていただいて、当委員会に所属されている方で知らない人がいるというのは、逆にびっくりなのですね。そこのところだけ考え方を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"なかなか行政では、１００個程度の購買などの場合には、とてもではないですけれども予算的には見合わないと思われます。ということで、今までどおりの１２０円をお支払いいただいて買っていただくということでご理解いただきたいと思います。","id":"exchange-025"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"それで、もう広く、いいのではないですか。これはもう聞き流していただきたいのですけれども、せっかくこういうキャラクターがあるわけですから、何かゲームとか作ってほしいなと。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"例えば何かに参加してくれた人にプレゼントするというのをやりたいのですけれども、今、ハードルが高くてなかなかできないでいるところです。ゲームを作るもともとのテクニックと言いますか、それがどこにあるのか、探しながら考えていきたいと思います。","id":"exchange-026"},{"speaker":"新妻委員","kind":"意見","question":"前回の委員会でご報告いただきました、１年前どうしようか会議が７月２３日に放映されたと思いますので、その視聴状況ですとか、その後のアーカイブの状況ですとか、反響をぜひご報告いただけたらと思いますとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"来てくださる方が５００人いたというよりも多い方に広まるという、そういうメリットもあるのだなというふうに感じたところです。は、“機運醸成だけではなくて競技の普及・啓発も行っているのはいいと思いました”というようなありがたいお言葉もいただいております。","id":"exchange-027"},{"speaker":"新妻委員","kind":"質問","question":"その後も１,７５５回の再生ということでは、テレビ、やはりこのネットでの拡散というのが広がっているなということも感じました。今後また、何か機会があればと思いますが、継続してやっていくことというのはいかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"なかなか難しいところもあるかもしれないですし、先ほど申し上げたような、ネットでやるメリットというのもまた感じているところです。今までそういうこともあったのですが、そういう心配もないというメリットもあるね、などということを職員と話しているところです。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312568?Template=document&Id=6580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":23793,"voices":85}},{"id":"r02-20200824-10","meetingId":"r02-cm08","date":"2020年8月24日","dateIso":"2020-08-24","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"の１、「令和３度予算（議会費）について」","agenda":"の１、「令和３度予算（議会費）について」","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"それぞれ適正に運用されていると思いますが、さらなるチェック体制ですとか、使途について検討するための第三者機関設置を求めます。メール等でやっていただいておりますけれども、ＬＩＮＥも入れていただきたいということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"大倉委員","kind":"提案","question":"今、こういうご時世なので、ペーパータオルを設置してはいかがでしょうかということで提案させていただきました。４、外部から検索もできるということだったので、これはこれで結構ですということでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"こんの委員","kind":"質問・要望","question":"２点目が、既存の会議体でいくのか、はたまたこれについても新たな仕組みづくりとして会議体をつくるのかというところで要望したいと思います。３点目、アクリル板などを設置、フェイスシールドなどの備えというところも必要ではないでしょうかというところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"４番目は、特に最終本会議における討論作成に間に合うように関係予算を増額していただきたいということです。５番目は、本会議と同じく、委員会もインターネット中継ができるように必要な整備をお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"３番目は、換気扇を設置して強制換気ができるようにするべきではないかと思いますので、設置をお願いしたい。これは部屋の広さに応じて換気扇数の確保はお願いしたいということですが、万が一、提案させていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"提案","question":"自民の提案の件で、議運の視察経費というのが今回提案されていますが、政務活動費というものがそれぞれ出されているのですから。もし場所があるならば、そういうような場所がつくれるようならば、それもいいのではないかというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言ということなので、海外調査について、今もご意見がありましたが、議長がまとめられる際には、ぜひ各会派共通、また共通できるものとして整理していただきたいということだけ意見を添えさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"我々が議会費の予算要望をしている背景には、我々は、今まで行ってきた海外調査の成果をしっかり見てほしいと求めました。防災備蓄についても、必要最小限のものはやはり議会で用意をする必要があるのではないかということで要望しております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"}]},{"id":"topic-02","title":"東京都後期高齢者医療広域連合議会の報告について","agenda":"東京都後期高齢者医療広域連合議会の報告について","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"支給対象は、被保険者２４万人のうちの約１％、約２,４００人を想定しているということです。内容としましては、これもそのまま全会一致で賛成しましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"提案","question":"その上で、やはり保険料の引き下げ、私は足を踏み入れるべきだと考えています。ぜひ今後、広域連合議会が開かれるかと思いますけれども、そういった趣旨のご発言や提案をしていただけたらと要望しておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"意見","question":"保険料につきましては、品川区議会としての問題もありますので、その辺を踏まえた上での対応になると思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"石田（秀）委員長","kind":"質問","question":"よろしいでしょうか。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"須貝委員","kind":"提案","question":"各委員会でフェイスシールド着用の許可がもらえるのかどうかを検討していただきたいということと、２点目は、区議会議員の方が感染した。議運で審議されるのか、議長のほうでお決めいただくのか、その辺を一応提案させてほしいと求めました。","respondent":"渡辺議長","answer":"もちろん今までも検討はしているのですが、フェイスシールドだけの場合の効用ですとか、まだ情報を全て把握できていないので、少しお時間をください。２つ目、議員の感染時、これもかねてから検討しております。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5374#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":9512,"voices":37}},{"id":"r02-20200916-10","meetingId":"r02-cm09","date":"2020年9月16日","dateIso":"2020-09-16","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢副委員長","kind":"質問・要望","question":"本日の予定は、お手元に配付しています予定表のとおりです。なお、石田秀男委員長は、本日、欠席とのご連絡をいただいております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"初めに、(1)「理事者から発言を求められている件について」を行います。本件につきまして、副区長から説明願います。","respondent":"桑村副区長","answer":"本定例会に提案予定をしております第５６号議案、新型コロナウイルス感染防止と経済・社会活動の支援を図るものです。説明は以上です。","id":"exchange-002"},{"speaker":"大沢副委員長","kind":"確認","question":"本件につきまして、特にご確認などはよろしいでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"大沢副委員長","kind":"確認","question":"ただいま副区長から説明がありました中途議決につきましては、後ほど、議事日程の確認の中で局長からも案内がありますが、私からも簡単に説明します。翌２４日には総務委員会での総合審査を実施し、少々時間を空けて議会運営委員会での採決方法確認、中途議決と進めていく予定であります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"提案","question":"区議会議員にとっては質問をする、しかも本会議での質問は大事な権利でありますので、それを保障する仕組みを作る必要があるのではないかと思います。文書質問という形がとれないか、皆さんのご意見も伺いたいし…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"大沢副委員長","kind":"質問","question":"資料はお手元におそろいですか。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"大沢副委員長","kind":"質問","question":"ただいま配付した資料Ｎｏ.３－２は、９月１８日の運営案について、質問者の順序などを修正したものです。資料Ｎｏ.８－２は、この後の議題で局長より説明があります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"大沢副委員長","kind":"確認","question":"最後に、こちらは９月３日に全会派から理事候補者が参加する理事候補者会の中で確認された内容ですので、特段ご意見はよろしいですね。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"大沢副委員長","kind":"質問","question":"(1)の「日程について」から(3)の「質問者の氏名報告について」までの３件を一括して局長より説明願います。","respondent":"米田区議会事務局長","answer":"なお、本会議２日目、１１月２７日金曜日の午前ですが、小学生の傍聴を例年どおり予定しています。予定表裏面にありますように、午後５時までに、質問者の氏名を事務局へ報告いただければと思います。","id":"exchange-009"},{"speaker":"大沢副委員長","kind":"質問","question":"ないようですので、第４回定例会の一般質問者の氏名につきましては、１０月６日火曜日までに、事務局へお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"大沢副委員長","kind":"意見","question":"本件については、８月２４日の議会運営委員会において取りまとめを議長一任とさせていただいたものであります。議長よりお願いいたしますとの意見を述べました。","respondent":"渡辺議長、米田区議会事務局長","answer":"具体的な説明は、考え方として、過去の予算要望の経緯などを参考にしながら検討させていただきました。では、局長、お願いします。 対応していく予定のものといたしましては、これまでも予算計上しておりまして、引き続き予算要望をしてまいりたいと考えております。こちらも経理課に在庫の範囲の中で対応してもらう予定ですので…","id":"exchange-011"},{"speaker":"中塚委員","kind":"提案","question":"発言、よろしいですか。これは議長に聞くことになるのか、委員会の視察で議運を追加したいということですけれども、基本的にこの提案については賛同していますとの意見を述べました。","respondent":"渡辺議長","answer":"議運での視察として想定される内容ですが、やはり昨今、議会改革が活発化しております。これは一番ふさわしい、検討する委員会が議運であろうという想定で、特に議会改革の項目が多いであろうというところです。","id":"exchange-012"},{"speaker":"大沢副委員長","kind":"意見","question":"ただいま議長より説明をいただきました。ないようですので、との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"大沢副委員長","kind":"意見","question":"局長より一括して説明願いますとの意見を述べました。","respondent":"米田区議会事務局長","answer":"再放送が２日後の１０月２５日日曜日ということで、表に記載の順番で放送を予定しておりますので、ご確認いただければと思います。続きまして、(4)の「その他」ですが、こちらも予定表に記載しておりますが、放送設備の点検の連絡が入っております。","id":"exchange-014"},{"speaker":"大沢副委員長","kind":"意見","question":"なければ、との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5376#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":12223,"voices":38}},{"id":"r02-20200918-4","meetingId":"r02-c-settlement","date":"2020年9月18日","dateIso":"2020-09-18","committee":"決算特別委員会","time":"午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡部副委員長","kind":"意見","question":"同じく副委員長に推挙いただきました、自民・無所属・子ども未来の渡部茂です。くれぐれも委員の皆様には円滑な運営にご協力賜りますよう、よろしくお願いを申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/964460?Template=document&Id=1482#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":2017,"voices":17}},{"id":"r02-20200923-6","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"区民委員会","time":"午前１０時００分～午後 ２時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件整理しています。","topics":[{"id":"topic-01","title":"第５７号議案、品川区印鑑条例の一部を改正する条例","agenda":"第５７号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"同行しないと駄目ということはいかがなものかという思いが少しあるのですけれども、その辺についていかがですかということが１点です。この委員会でまずどうなるかもまだ分かりませんし、本会議でどうなっていくか分からないですけれども、いつぐらいから実施されるのか説明を求めました。","respondent":"木村戸籍住民課長","answer":"１点目の、基本的にはその場合はできないというか、来ていただかないとできないというような形になります。こちらに関しては、その日についてはいろいろ微妙なところがあると思うのですが、議決され次第すぐにというような形になってまいります。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"この品川区の成年後見センターが出しているパンフレットというか、冊子ですけれども、そうすると成年後見というところでいうと、保佐人型や補助人型、そこもこの成年後見の制度の中には入ってくるということなのか尋ねました。","respondent":"木村戸籍住民課長","answer":"今回の対象というところは、いわゆる成年後見というところが入ってくる、いわゆる保佐や補助、そのような方々はこの中には入ってこないという形です。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"どういった分野、多分すごい広くだと思うのですけれども、そこを伺いたいと思います。","respondent":"木村戸籍住民課長","answer":"実施をするところが個別に審査をしてやるというような形の、委員おっしゃるとおり、かなり広範囲にわたる形で法律その他の改正が行われているところです。","id":"exchange-003"}]},{"id":"topic-02","title":"令和２年陳情第４０号、品川区でのたばこ対策","agenda":"令和２年陳情第４０号、品川区でのたばこ対策","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"３番目の、小池都知事が都議会での答弁で、地域の実情に応じた区市町村の取り組みを積極的に支援すると言ったのは、これはまず言ったのか確認です。ここは区が排除されたのかということの確認、費用を全額支給することも表明しましたと書いてありますけれども、それも確認です。","respondent":"黛生活安全担当課長","answer":"知事の発言ですが、このような趣旨の発言をされたというように認識をしています。陳情の中の市町村となっていて、区は排除されたのかですが、区のほうは排除されていないというふうに私どものほうでは認識をしております。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１回確認なのですが、費用を全額支給することを知事が表明したと書いてありますよね、この文章。本当に小池知事がそのような趣旨のことを答弁したのかしないのかという確認をさせてほしいと求めました。","respondent":"黛生活安全担当課長","answer":"申し訳ございません。私のほうで認識をしていないところですが、このような制度が現在整っており、既に運用されているという事実はあります。","id":"exchange-005"},{"speaker":"藤原委員","kind":"確認","question":"知事がこのような発言をしたということは明確に確認はしていないけれども、全額支給はしますよというように考えてよろしいということですね。改めて。","respondent":"黛生活安全担当課長","answer":"一定の条件を満たしたものについてという条件がつきますが、委員ご指摘のとおりです。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"この受動喫煙防止条例が施行されてというところから、この間喫煙率というものは分かるでしょうか。ちょっと課が違うのか尋ねました。","respondent":"黛生活安全担当課長","answer":"共存していくという意味においては大変重要だというふうに認識していますことから、可能であれば増やしていきたいというような認識はありますが。引き続きこの点について、区としてもなるべく前に進むように努力のほう進めていきたいと、このように考えているところです。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"全てをなくすということはできないと思うのですけれども、区としては禁煙を勧めていく、今喫煙されている方に。そのようなところと整合性というのですか、増やしていくというところでいいのかなと私は感じるのですけれども、その辺の考えを伺いたいと思います。","respondent":"黛生活安全担当課長","answer":"確かに区として健康プランなどの中で禁煙を勧めていくというような方向性にいるということは認識していますが、本件については、それから匂い。こうした施設を作るということがためになるのかなというふうに考えておりますので、引き続き…","id":"exchange-008"},{"speaker":"小芝委員","kind":"確認","question":"ちょっと幾つか確認と質問をしたいのですけれども、確認をしたわけではないですが、肌感覚ではそういった店はかなり少ない状況であると思うのです。その辺、区のほうで、大体どの程度の喫煙ができる飲食店、喫茶店があるのかということは、把握はされておるのか尋ねました。","respondent":"黛生活安全担当課長","answer":"今委員からご質問のありました屋内の喫煙所につきましては、これ担当が健康課のほうになりまして、私どものほうで把握していないという実情です。","id":"exchange-009"},{"speaker":"小芝委員","kind":"質問・要望","question":"ポイ捨て禁止というものを、されているとは思うのですが、もっと広めてほしいと求めました。どのようにお考えか尋ねました。","respondent":"黛生活安全担当課長","answer":"当担当としても認識をしていますが、これは肌感覚なのですけれども、というように認識をしています。広報啓発活動をしていったり、生活安全サポート隊のほうが積極的に注意喚起するというような活動を展開していきたいと考えております。","id":"exchange-010"},{"speaker":"小芝委員","kind":"質問","question":"逆に何でしょうか、受動喫煙の弊害ではないですが、何とか過ごしやすい環境を整えていってもらいたいと思います。これは意見として言わせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問・要望","question":"少しお伺いしたいのが、早期開放で喫煙所が９か所中６か所、やはり閉鎖されたことで増えているなどというような認識はあるのでしょうか。それと、やはり対応をしっかりしていかなければいけないと思っているのですけれども、その辺についても改めてお伺いできればと思います。","respondent":"黛生活安全担当課長","answer":"これも皆様方が徐々に区の取り組みに理解をしていただいて、ルールとマナーを守っていただいているからだなというふうに認識をしています。２点目の今後の対応ですが、この共存を図っていくという意味においては、喫煙所というものは重要だというふうに認識をしております。","id":"exchange-012"},{"speaker":"大倉委員","kind":"確認","question":"今もお話ありましたが、していったほうがしっかり分煙が進んでいくのかなと思いますので、ぜひよろしくお願いします。助成制度、ちょっと１点確認なのですけれども、その助成を使って喫煙所の設置をしていくことができるということの認識でいいでしょうかということで。","respondent":"黛生活安全担当課長","answer":"かかりました費用につきましては、一定の範囲内においてそれが都から補助が出るという仕組みについては既に運用されておりまして、現在各区においてそれも活用されているです。","id":"exchange-013"},{"speaker":"つる副委員長","kind":"確認","question":"各委員が質問していただいたところの確認のようなところもあるのですが、各会派からの質問に対する答弁という認識でいます。そこをまず最初に教えてもらえますか。","respondent":"黛生活安全担当課長","answer":"民間の方が喫煙所を設置、いわゆる自分の店舗などに喫煙所を設置するときの、この助成金の活用につきましては担当外、健康課のほうで所轄しておりますことから、私のほうで、申し訳ありませんが、ちょっと把握してございません。","id":"exchange-014"},{"speaker":"つる副委員長","kind":"確認","question":"その確認と、当然公園というものは公の園ですから、様々あるわけです。これは公園課にも確認したのですけれども、指定喫煙所という意味における公園という考え方は、今の現段階での区の認識を説明を求めました。","respondent":"黛生活安全担当課長","answer":"現在都において実施をされている、民間が喫煙所を設置するときに助成金を出すというものについては、利用される方は利用できるはずです。２点目の公園の関係のご質問ですが、これについてはこの場で私のほうから何か申し上げるということはできないところです。","id":"exchange-015"},{"speaker":"つる副委員長","kind":"確認","question":"店舗用としての１０分の９もあるけれども、その残りの１０分の１の部分については、公園課がやるというようになるのでしょうか。指定喫煙所の指定というのは、どこがやるのか尋ねました。","respondent":"黛生活安全担当課長","answer":"先ほどもご説明しましたが、さらに設置する際、設置費用の一部を区のほうでも持つというような制度のほうを運用しているところがあります。名称として指定喫煙所という名前であるというようにお考えをいただいて、管理の在り方につきましては…","id":"exchange-016"},{"speaker":"つる副委員長","kind":"確認","question":"例えば先ほど石田ちひろ委員が質問されたところで、例えば今伺ったところも含めて、当然外にも流れるわけです。その確認と、考えとして何かあれば、それを教えてほしいと求めました。","respondent":"黛生活安全担当課長","answer":"これにつきましては、これからもそのように対応していきたいというふうに考えているところです。そうした意味においては、対応というものは慎重にしていく必要があるのだろうというふうに認識をしています。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問","question":"本日結論を出すということで、態度については趣旨採択でお願いします。先ほどもちょっと質疑で伺いましたが、これから進めていくということでありますので、趣旨採択でお願いできればと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"提案","question":"提案等も含めてさせていただいてきたところであるわけですが、それを推進してほしい、例えば公園とか。ちょっと今後また１つ、１つそういった課題はあるのかなという部分はありますが、この望まない受動喫煙防止対策を区に対して推進してほしいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"意見","question":"本日結論を出すで、私たちは不採択でお願いします。そのようなことではなく、たばこを吸わない社会を進めていくべきだと思いますので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"望まない受動喫煙防止を推進するためということが大前提になって、それ以下、推進するための理由が述べられていると私は判断しております。なので、趣旨を採択するということでお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"くにば委員","kind":"質問・要望","question":"ただ、非喫煙者の方々に屋外で煙がどうしても流れてきてしまうなどという部分もありまして、今後の課題等も含まれてくるかなとは思います。最後のこの３番の部分ですけれども、きちんと調査研究を進めていただきたいということで、全体的に趣旨採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"松本委員","kind":"意見","question":"中でもこの３番の民間事業者の点に関しては、有人で、きちんと人が管理しながらやっていくというような民間の取組もあると思っています。段階的に減らしていくという中でも、我々としてもやはり取り組んでいくべきというふうに考えていますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]},{"id":"topic-03","title":"の第５６号議案、令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"の第５６号議案、令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"順にお伺いします。これでまず上限５万円というように見積もった内容の予算、あとは最終的にこれ５万円掛ける１００で５００万円、まずはそこをお知らせください。","respondent":"川島地域活動課長","answer":"品川区内に２０１町会・自治会がございまして、この補助を使っていただけるだろうということで、ざっくりと予算を組ませていただいております。６月、７月に町会長会議を再開した際に、制度化させていただいたものです。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問・要望","question":"こちらのほう求めないのであれば流用のおそれがあるというか、大枠での指示だけですと、そちらの収支報告書等の提出について伺います。町会・自治会のほうももう一度活動を再開してほしいという思いや願いはあると思うのですけれども、飲食を提供するというか、まずは以上お伺いします。","respondent":"川島地域活動課長","answer":"領収書を当然添付していただいて、流用などができないような形で、その辺の縛りをかけるという予定です。除菌シートなどなどということで、申請のときに私どものほうで相談に乗って、その辺の適正な申請につなげるような形で考えております。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問","question":"この消耗品の買っておいてほしい部分、では１０分の１０予算をつけます、これで使ってくださいというふうに考えるのかということがあると思うのです。ほかにどのようなことを想定していて、これだけの予算を使うぐらいのマスクや消毒液などが必要であると考えているのか、そちらについてお伺いします。","respondent":"川島地域活動課長","answer":"なかなか考えが難しいところではありますが、しっかりやっていかなければと考えていますので、その辺はしっかりさせていただきたいと思います。それからここで全部、今委員がおっしゃったような疑念につきましても…","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"待合スペース３密解消対策について、そちらについてほかに取り組まれている自治体があるかどうかをひとつご答弁いただきたいです。今回ＱＲコードを手前の段階で入力してもらってという形のアイデアが出たのかもしれないのですけれども、その辺の経緯についても伺いたいです。","respondent":"木村戸籍住民課長","answer":"今回、そのマイナンバーカードに登録されている情報だけ届書に写し出されてくるという形を既に運用を区役所のほうで開始しておりまして。今委員のおっしゃられた、検討を今しておるところでございまして、速やかに導入を図っていきたいというふうに考えておるところです。","id":"exchange-027"},{"speaker":"くにば委員","kind":"提案","question":"その利用率の想定について伺いたいのと、新しくご提案してきたところが開発をしてしまうのか、メニューの追加について伺いたいのと。こちらはしていないのであれば、ぜひとも、結局同じ意味合いの取組ですから…","respondent":"木村戸籍住民課長","answer":"先ほどご説明したマイナンバーカードを提示すると届書が出てくるという形が今の仕組みなのですが、毎日１件程度あります。実際に今後ＬＩＮＥをというところで考えますと、そこまで爆発的にそれをご利用されて来る方というのは、まずいないかなという認識でおります。","id":"exchange-028"},{"speaker":"くにば委員","kind":"確認","question":"最後におっしゃっていた戸籍等のものに関しては、品川区のホームページにダウンロードできる形の書式のものが、ファイルがあるということでしょうか。ホームページのほうから取得できるファイルがなかったように思うのですけれども、そちら私の確認不足かもしれないので、もう一度ご答弁お願いします。","respondent":"木村戸籍住民課長","answer":"実際に婚姻届などの様式ですけれども、そちらの戸籍の、いわゆる汎用の様式のようなところは、今ホームページで公開しております。ただ、ちょっと分かりにくいですので、また改善してまいりたいと思いますが、今ダウンロードできるようになっております。","id":"exchange-029"},{"speaker":"くにば委員","kind":"提案","question":"これでもう一つ私のほうから、提案を含めて申し上げるのですけれども、戸籍住民課窓口リアルタイム混雑状況確認のページというものがありますよね。すぐにスマホ用のページが見られるような仕様になっているので、そこはやったほうがいいのではないかということが１つ提案ですとの意見を述べました。","respondent":"木村戸籍住民課長","answer":"転出届を出しに行くというときに、何を持っていったらいいのだろうなどという場合に、ホームページからまずご覧いただくことが普通かなと思いました。今おっしゃられたＬＩＮＥ側に飛ぶ、そのような形の取組が有効ではないのかなというふうに、今のところ考えています。","id":"exchange-030"},{"speaker":"くにば委員","kind":"意見","question":"すみません。品川区公式アカウントのＬＩＮＥの総合メニューの中にこれも１つ付け加えるということで、それは難しいことなのかどうか、お分かりになる範囲でとの意見を述べました。","respondent":"木村戸籍住民課長","answer":"基本的にはそちらのやり方も取れると思いますので、ぜひそのような形でやっていきたいと思います。","id":"exchange-031"},{"speaker":"くにば委員","kind":"質問","question":"こちらの事業内容２番目のマイナンバーカード受付予約ツール導入、こちらに関しても、これは基本的にインターネットから予約できるようにするということで、これはホームページのみという認識でよろしいのか尋ねました。","respondent":"木村戸籍住民課長","answer":"区民にはネット環境をお持ちでない方などもいらっしゃいますので、電話での受付もするというような形で考えております。","id":"exchange-032"},{"speaker":"くにば委員","kind":"質問","question":"こちらに関して、まさにこれは同様の取組をＬＩＮＥでできることをご存じなのかどうか。そもそも話合いの土台に上がっていたのかどうか、ご認識なさっていたのかどうか、可能なのかどうか伺います。","respondent":"木村戸籍住民課長","answer":"実際お話を聞いたのですけれども、逆に運用の実績のあるところとやってみたいというところで、実際にはそのような俎上にはのっておりました。それからメニューの追加はできるということです。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問","question":"第２波というか、第３波というか、この事業を一旦キャンペーンを中止するというような考え方があるのかどうか。見直しをしたりする際の、どういった基準でこちらの事業の一旦休止などの見直しをするというようなお考えがあるのか、そちらについてまず伺います。","respondent":"古巻文化観光課長","answer":"連携いたしまして、しないの判断はしていくのが、当然のことかなというふうに認識はしております。東京都の４段階の中で、ガイドラインを定めた上での実施をしていきたい、そのように考えております。","id":"exchange-034"},{"speaker":"くにば委員","kind":"質問・要望","question":"ただ、休止をすべきというときには、ぜひともきちんと判断していただいて休止をしていただきたいと私のほうは要望として思っているのですけれども。これがこのキャンペーンを利用することによって、どれぐらいの利用者まで月間利用率、利用者数が増加すると見込んでいるのか尋ねました。","respondent":"古巻文化観光課長","answer":"７月、８月ぐらいの利用ということで、なかなか事業者の存続すら危ないというような状況になっているというふうに認識しておりますので。想定は難しいですけれども、１万人になるべく早期に達せられるようにしっかりと努力していきたいと思います。","id":"exchange-035"},{"speaker":"くにば委員","kind":"提案","question":"これはあくまで提案というか、結局１％ぐらいに落ち込んでいて、これ１万人に到達するのはやはりなかなか難しいのではないかなと。その１％という数字を聞いて思ったのですけれども、そこの柔軟な対応というものは可能なのかどうかという部分をお願いいたしますとの意見を述べました。","respondent":"古巻文化観光課長","answer":"そのようなことが重要だと思っていますので、いろいろなことを想定を考えながら、しっかりと進めていきたいと思います。いろいろいただいたご意見を参考にさせていただきながら、進めていきたいと思います。","id":"exchange-036"},{"speaker":"くにば委員","kind":"質問・要望","question":"当然その体温を測定するということは、ほかの事業者のところと同じような形で、当然体温を測っただけではしようがないですから。こちら１４か所の施設で、この１４施設はなかったのかどうか、以上の点を伺います。","respondent":"古巻文化観光課長","answer":"それぞれの、入館される方がご自身で測って、それが警報が鳴った場合に初めて人が対応するというようなオペレーションを今考えております。３点目にご質問のあった、使われる方は…","id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"例えば委託の職員等の手間が省けるということで、全てこの自立スタンドタイプで置き換えるということが可能なのかどうか。この自立スタンドタイプで全て賄えるようになるのかどうか、その今使っているハンディタイプを別の施設に回すことができるかどうか伺います。","respondent":"古巻文化観光課長","answer":"自立スタンドタイプで一定の範囲での対応は可能になると思うので、今ほどの数は必要なくなってくるのかなというふうにも考えられます。そこは十分に活用の仕方を考えますけれども、それより減らせるのか、そこは無駄にならないような形で考えていきたいと思います。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問・要望","question":"もう無論世界中でもスタンダードで使われているものでありまして、当然ながらその効果に関しては実証されていることであります。区が管理している施設においてはぜひともこちらの体温測定器、ハンディタイプも含めて、導入のほう確実に進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"待合スペース３密解消対策についてですけれども、マイナンバーのほうについてお聞きします。でもこれも、現在のこのマイナンバーの普及率と件数が分かれば教えていただきたいのですが、どのぐらい増えているか教えてほしいと求めました。","respondent":"木村戸籍住民課長","answer":"区民の方の２０％がお持ちだと。５年の電子証明書の更新時期にも重なっているところもありまして、第二庁舎の３階で、そちらのほうが常時混雑しているという状況です。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"そこを伺いたいのと、通常運航しているというのは、どれぐらいになっているのか。倒産というか、ちょっともう閉めざるを得ないというところは出ていないのか、そこを伺いたいと思います。","respondent":"古巻文化観光課長","answer":"こちらは区と観光協会が連携いたしまして進めていくもので、あとは全体の総括的な意味では品川区のほうでやっていくという考え方です。せっかくある水辺の観光の大きなコンテンツを絶やさないような形で利用を促していきたいと、そのような形で考えております。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"その屋形船を運営されているところというのは何か所くらいあるのか尋ねました。","respondent":"古巻文化観光課長","answer":"失礼しました。この企画に参加するということでは、区内の業者ですけれども、１０事業者がいると把握しております。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"この１０事業者が、どれだけ回復できるのか、本当に大丈夫？こうした屋形船の協会というんですか、そういうところと協議したりした結果でこういう策につながったというところなのか、それを伺いたいと思います。","respondent":"古巻文化観光課長","answer":"１０事業者の対象の選定ですけれども、魅力アップの事業を考えていまして、事業者にご参加いただく形になっています。いろんな状況については共有をしたり、また意見交換をしたりということで進めてありますので、事業者の方のご要望も十分取り入れて計画しています。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"補助金によくあるスキームというんですか、区が何分の１という、区は乗せなくてもいいけど独自に乗せたということなのかというのを伺いたいんですが。","respondent":"遠藤商業・ものづくり課長","answer":"家賃支援の上乗せ給付の考え方ですけれども、７月ぐらいだったと思いますけれども、上乗せをしたです。意見を聞いたところ、少しでも乗せていただければということでご要望いただいたところで、今回の補正予算に計上させていただいたところです。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"で、区内の事業者であるというところなんですけど、これは、要は全て品川区の対象にというようになってくるんですか。この都の家賃支援給付金の交付決定を受けている者というのはどういうものなのか教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"私ども基本的には東京都と同条件で、ただ１点だけ違うのが、品川区内に事業所があることです。そこの部分だけちょっと変えさせていただいて、一番簡単な方法ということで、東京都のそのまま金額の２分１という形でさせていただいたところです。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"必要としているのに漏れてきちゃう事業者はあるのかどうかという、必要なのに受けられないという、そこをどう見ているのかなということです。７億円が地方創生臨時交付金ということですけれども、それをここに７億円全て充てたという、そういう考え方なんか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"あるいは品川区のほうでは、国よりはちょっと低くなっておりますけれども、区として支援する対象ということでは十分賄われているのかなです。財政部門のほうで検討したところでございまして、私ども全部で約１１億円今回…","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"意見","question":"私もこれは、また申請かと言われたんですけど、こういうのが出るよと周知したときに。それが、どういうふうな、簡易な形にされているのかどうかとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"今回そういう部分も非常に考えまして、その金額の２分の１ということで、一番簡単な方法でやらせていただきました。今までは基本的に郵送なり、もちろんオンラインは少し難しいなというところであれば、私どものほうの窓口で対応するという形で進めしています。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"職員とか、対応する方が出てくるという感じのものになるということなのか、ちょっとどんなものなのかを伺いたいと思います。","respondent":"古巻文化観光課長","answer":"考えている機械につきましては、胸から上ぐらいのところを撮影しまして、体温を測定するということです。ブザー的なこともできるでしょうし、分かるようになって、それで係員のほうが対応するという流れで考えているところです。","id":"exchange-048"},{"speaker":"藤原委員","kind":"質問","question":"体温測定器の部分でお伺いしますけれども、答弁を伺っていたら、きゅりあんにスタンドタイプの体温測定器ってありますよね。それとは別の機械を入れるんか尋ねました。","respondent":"古巻文化観光課長","answer":"文化振興事業団のほうで独自の購入ということで入れているというふうに、あるものについては今、使用しております。それをまたさらに補う形で、大きい施設ですので、足りない部分は区の予算である程度フォローするというような形で考えています。","id":"exchange-049"},{"speaker":"藤原委員","kind":"質問","question":"何が質問かというと、きゅりあんを一般の方が借りるときの事業に対しては、文化振興事業団が購入した測定器を貸し出してないと思うんですね。６階でも、５階でも、区で購入する測定器はお貸しするんか尋ねました。","respondent":"古巻文化観光課長","answer":"きゅりあんは今回２台入れるということで、本来もうちょっと台数多くということも考えたのですけれども、なるべく有効に使えるようなものを考えていきたいと思います。","id":"exchange-050"},{"speaker":"藤原委員","kind":"質問","question":"だけど、新型コロナは把握しないわけじゃないですか。どうか尋ねました。","respondent":"古巻文化観光課長","answer":"もう少し柔軟に利用ができるような形で２台追加しますし、有効な、きちんとした測定ができるような環境を作っていきたいと考えています。","id":"exchange-051"},{"speaker":"藤原委員","kind":"質問","question":"そうしたら、その課で持っているのは臨機応変に貸し出すんですか。貸してくれるんか尋ねました。","respondent":"古巻文化観光課長","answer":"足りなくなれば課で持っていますので、貸し出すことは可能かなというふうに思いましたので、ああいう形の答弁になりました。その点も含めて、どうやった形の運用がいいのか、もしくは必要に応じては貸出しを行うのかということも含めて考えていきたいと思います。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"国民を守るという意味では、ここはやっていくべきだと思うので、ぜひ考えてください。新しく区で２台買う、こんなにしつこく珍しく質問してしまっているのですけれども、。","respondent":"古巻文化観光課長","answer":"そういったところで、きちんと把握できるように体制を整えることはとても重要なことだと思います。すぐに１００％、なるべくしっかり対応していくというような形で、進めたいと思います。","id":"exchange-053"},{"speaker":"藤原委員","kind":"質問・要望","question":"今どうかなというのが街のいろいろな考えの方がいると思うのですけれども、その辺についてどう思いますという、大きい話でいいので伺いたい。それでいいのかということと、そうすると、品川区にある事業者は、国、都、区から、３つから助成を受けられるのかという確認です。","respondent":"川島地域活動課長、古巻文化観光課長、遠藤商業・ものづくり課長","answer":"なかなか実施は難しいというところですけれども、今年度中に何らかの形でできるようになってほしい、そういう環境を整えてほしいと。イベント実施施設… 区が認識している風評被害に関しましては、ただ、あたかも屋形船が感染に弱いといった印象が持たれてしまったことに対して風評被害だったという。… 家賃支援給付金は、国、都、区、それぞれからという形になります。それぞれから受けることができるという形になっております。","id":"exchange-054"},{"speaker":"藤原委員","kind":"質問・要望","question":"委員長が、どう進めていっていいか分からないという思いがすごく出たので、こういう質問をさせていただきました。新型コロナウイルスが怖いから全部事業を今、規制したいという意味で伺ったのではありませんので、そこはぜひ理解してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"松本委員","kind":"質問","question":"今の点で、感染症対策上の家賃補助金の件で質問と、補助金の話が出てきていて、私もすごく思います。端的に例示の中で餅つきを消していただくというのが一番分かりやすいのではないかなと思うのですけれども、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"これから先、どういうふうな感染状況になるか、現状では当然できないというのは分かっております。大変誤解を招きやすいようなところではありますので、その辺はこちらも注意したいと思いますが、現状このままで行かせていただければと思います。","id":"exchange-056"},{"speaker":"松本委員","kind":"意見","question":"やるとしてもどういうふうにやっていくのかというところは、これやり方いろいろと、できるだけ感染のリスクを下げていく方法は考えられると思います。感染リスクを避けるために、できるだけ対策を立てて実施をするとか、そういったところは載せていただければとの意見を述べました。","respondent":"川島地域活動課長","answer":"ご指摘の感染リスクを下げるような取り組みのところというのは、申請のところでしっかり協議の中で指導というか、させていただければと思います。","id":"exchange-057"},{"speaker":"松本委員","kind":"質問","question":"１０万円の給付も、というのは、アメリカなんかは２週間とかでできたわけですね。本当はちゃんとやっていくべきだと我々は思っているところで、そことの交通整理というのがどうなるのかというところをお願いします。","respondent":"木村戸籍住民課長","answer":"特定の例えば３時、３時半の間とかというような形で、そういう形で受け付けをしていこうというふうには考えております。","id":"exchange-058"},{"speaker":"松本委員","kind":"確認","question":"確認になるのですけれども、予約、その時間で予約した人のほうが、飛び込みの方たちよりも、ある意味優先されるというふうに考えてよろしいか尋ねました。","respondent":"木村戸籍住民課長","answer":"そのような形で、それから、基本的にその時間に予約して来ていただいた方を優先するという形です。","id":"exchange-059"},{"speaker":"松本委員","kind":"意見","question":"今の点はわかりました。色々な給付金の話でありましたけども、これは具体的に事務委託というのはどういったところにされているのかお答えほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"７,２００件の処理をかけなくてはいけないということで、今回は事務委託ということで、何人かの方に来ていただくという形で考えているところです。考えておりますのが、ある程度実績のあるところを考えておりまして、そこと契約を結べるように進めているところになっております。","id":"exchange-060"},{"speaker":"松本委員","kind":"質問","question":"これは随意契約という形でやっていくということだと思うのですけれども、これはまだどこかというところは決まっていない、まだ予算をとっていない、ここは特に協議とか具体的な対策をとるということはやられていないということか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらのほうで今、探してあたりをつけているような状況です。このような形で進めて、定例会で予算決定いただければ、速やかに契約するという形で進めているところです。","id":"exchange-061"},{"speaker":"松本委員","kind":"質問・要望","question":"そのあたりはどうしても多分、ぜひそのあたり、費用の精査をほしいと求めました。以上、要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"小芝委員","kind":"質問","question":"町会、若くても６０代ぐらいの方が中核となっておりまして、そういう方々がこのコロナ禍でほとんど外に出ていないと。お聞きしたいのですが、歳末、年始にかけた活動が大体１００町会ぐらいで行われているという認識でよろしいか尋ねました。","respondent":"川島地域活動課長","answer":"品川区の今の町会、自治会数が２０１町会あります。ざっくり町会、自治会の半数程度のものを活動の支援になればというような形で計上させていただいたところです。","id":"exchange-063"},{"speaker":"小芝委員","kind":"質問","question":"こちらのほう、いつから申請ができるような形でお考えか尋ねました。","respondent":"川島地域活動課長","answer":"こちら予算の議決をいただきまして、速やかに要綱のほう作りまして、実際、事前に相談等いただければ、その辺の相談と並行しながら申請の手続等を進めていきたいと考えていますので、なるべく間のないように迅速に対応します。","id":"exchange-064"},{"speaker":"小芝委員","kind":"質問・要望","question":"やはり２か月前、３か月前になってきますので、力を入れてほしいと求めました。確認ですが、役所の職員さんが来て直接フェイストゥーフェイスで読み取り作業するのか、どういう流れなんか尋ねました。","respondent":"木村戸籍住民課長","answer":"今、住民届とか住民票の写しの申請書を紙に書いていただく記載台というものを幾つか置いてあります。基本的に職員が介在するとかお預かりで何とかという形ではなくて、お客さんの中で完結していただくというような形で考えています。","id":"exchange-065"},{"speaker":"小芝委員","kind":"質問・要望","question":"次に、家賃支援給付金について質問いたします。こちら東京都の家賃の支援給付の申請をされたのがおおよそこのぐらいの件数ということでよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"３１.４％が、大体かなりのところ、１００％にほぼ近いのではないかなと考えているところです。商店街連合会などに聞いて、その辺を全部総合的に勘案しまして、今回の大体４割ぐらいという形で７,２００という数字を出させてもらったところです。","id":"exchange-066"},{"speaker":"小芝委員","kind":"意見","question":"内訳の助成額で１件あたり１０万円ということですけれども、これって私、計算間違っていたら申しわけないのですが、家賃が大体８０万超えるようなケースではないかなという気がしているのですけれども、その辺のほう、家賃は１０万ぐらいのところもありますし…","respondent":"遠藤商業・ものづくり課長","answer":"４４０億円の予算を組んで、大体事務費などもかかっているかと思いますので、１件あたり２０万円ぐらいではないかという形です。そういう意味では、必ずしも１件の家賃で８０万円というわけではないと考えているところです。","id":"exchange-067"},{"speaker":"小芝委員","kind":"質問・要望","question":"そういう中でこのキャンペーン、今、コロナ禍の状況ですので大変だと思いますけれども、進めてほしいと求めました。そういうところで１つ質問しますが、乗船料の補助、こちらは品川区在住の方を対象にしているものなのか、それ以外の方も含むのか、お答え願います。","respondent":"古巻文化観光課長","answer":"乗船料の助成対象に関しましては、区内の事業者を使った場合に助成いたしますという形ですので、特に利用者については、特定の何か、区民でなければいけないとか、そういったような制限は考えてございませんで、広く使っていただくように事業を進めていきたいと考えています。","id":"exchange-068"},{"speaker":"小芝委員","kind":"質問・要望","question":"例えば中原街道から西側の品川区の方たちが、恐らくイメージとして、ほかの地域の方よりも少ないのかなという印象があるのです。そういう中で、広く地域の方々にもこのキャンペーンを周知していただきたいと思うのですけれども、お考えをお聞かせいただけばと思います。","respondent":"古巻文化観光課長","answer":"区としても認識をしておりまして、存在自体はよく知っているにしても、乗る機会がなかなかないという方もいらっしゃるといると考えています。そこは区としてもしっかり力を入れていきたい部分ですので、ご指摘いただいたところを踏まえましてやっていきたいと思います。","id":"exchange-069"},{"speaker":"大倉委員","kind":"質問・要望","question":"１点だけ。これは、基本的にはこういう施設については安全に利用していただきたいのですが、そういうのも含めてどういう性能なのか教えていただけばと思います。","respondent":"古巻文化観光課長","answer":"その枠をあまり偏りなく配分するという考え方で、その範囲をあまり超えない範囲での金額のものという選定の仕方になったのだろうと思います。逆に、マスクをしていて体温がきちんと平熱であることが分かるということでは、二重にそういったところのチェックができるというもので…","id":"exchange-070"},{"speaker":"大倉委員","kind":"質問","question":"熱があると、何か警報が鳴って職員さんが来て対応する。体温は平常だけどマスクはつけてないとなると、警報が鳴って職員さんがマスクをつけるように促すようになっているという感じか尋ねました。","respondent":"古巻文化観光課長","answer":"そのような形で、マスクをしていただいて、体温が平熱であるということを確認できると。マスクについては、着用をお願いしているにもかかわらず、してなかった場合はきちんと現場の職員が対応するという形になると思います。","id":"exchange-071"},{"speaker":"大倉委員","kind":"質問","question":"どういうふうに使われるかという検討もされてこの台数になっているかと思うのですけれども、台数の考え方は、どういうふうにこの２台というのを出されたのかを教えていただけますか尋ねました。","respondent":"古巻文化観光課長","answer":"メインは７階と８階になるのでそのようにお話ししましたけれども、文化センターは各入り口で１台ですけれども、この中でしっかり有効性が保てる台数ということで考えた台数ということでご理解いただければと思います。","id":"exchange-072"},{"speaker":"つる副委員長","kind":"質問","question":"先ほど小芝委員から、中原街道より西側の方、私も西側の住民として、その視点も含めて都市型観光プランとして伺います。今、そういう意味において今の部分はどういうお考えができるか、もし現段階で見解があれば説明を求めました。","respondent":"古巻文化観光課長","answer":"検討の詳細まではまだ固まってない部分がありますので、できる、そのあたりをバランスよく事業に反映していくような仕組みを考えていきたい。事業者もさまざまに考えていると思いますので、しっかり話をしながら有効な事業になるように進めていきたいと思います。","id":"exchange-073"},{"speaker":"つる副委員長","kind":"提案","question":"私も事前に確認してないので、確認の部分もあるのですが、自立スタンドタイプのものが設置されているのでしょうか。事前に確認できなかったので、説明を求めました。","respondent":"古巻文化観光課長","answer":"歴史館につきましては、ほかの文化センターと同様、非接触型の人が操作するタイプがあります。","id":"exchange-074"},{"speaker":"つる副委員長","kind":"質問","question":"歴史館については、自立スタンドタイプは、今回このタイミングでは購入しないということですね。展示什器というのは具体的にどういうものを購入予定されているのかということと、こういう物品を購入しましたと、その辺を説明を求めました。","respondent":"古巻文化観光課長","answer":"今回に関しましては展示什器ということで、そんな大きなものではないのですけれども、展示のケースを購入予定です。しっかりその辺は、寄附された方にはどういう形で使わせていただいたのかというお知らせ、また御礼も伝えていきたいと思います。","id":"exchange-075"},{"speaker":"つる副委員長","kind":"質問・要望","question":"教えていただきたいところも含めてなのですが、国のほうは、６カ月分を一括支給という認識で、３００万円。こういう計算でまず合っているか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"７５万円以下ですと、３カ月分は東京都と私どもの考えになっているので、おおむね８割を３つの団体から支給するような形になってあります。","id":"exchange-076"},{"speaker":"つる副委員長","kind":"確認","question":"これも事前に詳細に資料を見て確認して、ここはどうですかと確認できればよかったのですが、ちょっと私も失念したかどうか分からないですけれども。確認です。","respondent":"遠藤商業・ものづくり課長","answer":"参考の一番の下段かと思いますけれども、おっしゃるとおりです。資料に間違いがございまして、大変失礼いたしました。","id":"exchange-077"},{"speaker":"つる副委員長","kind":"質問","question":"ここは違うのではないですかとご指摘できれば、修正された後のもので委員会審議できたのかなと、副委員長としても大変申し訳なく思っているのです。３.１２５万円、６.２５万円、それの２分の１を品川区が給付するということでよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"副委員長のおっしゃるとおりです。","id":"exchange-078"},{"speaker":"つる副委員長","kind":"確認","question":"各委員の質疑の中でここまで確認の質疑がなかったのですが、あえて確認をさせていただきましたが、分かりました。６.２５万円の半分だから３万１,２５０円の３カ月だと、約１０万円弱になるからアベレージで１０万円と、そういう認識でよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"家賃の平均では８５万円ぐらいを想定していますので、約１０万円ぐらいになるだろうというところで、７５万円ですと３ヶ月分で９万３,７５０円になるかと思いますが、もう少し高いという見込みです。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2878#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":62375,"voices":206}},{"id":"r02-20200923-7","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"厚生委員会","time":"午前１０時００分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を107件整理しています。","topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取り上げる順番を変更し、議案審査(2)から先に行います。 それでは、(2)第５６号議案 令和２年度品川区一般会計補正予算（歳出 厚生…","agenda":"冒頭申し上げましたとおり、取り上げる順番を変更し、議案審査(2)から先に行います。 それでは、(2)第５６号議案 令和２年度品川区一般会計補正予算（歳出 厚生…","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"この３,２００万円弱ですか、それから来年の３月までということだと思うのですが、率直にカバーできるのでしょうか。お伺いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"基本的には国が対象としているサービスで、ご本人が同意をしている、このケースは全て対象とします。この２区分上位に同意しますといったケースにつきましては、全てこの補助金の対象とする、そういう予定でおります。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"利用者は当然同意してしまうことになると思うのですが、そうすると、今までより爆発的に増えると思うのです。だから、今までの数字よりどんどん増えていくのではないかと思うのですけれども、それでもカバーできるのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"あくまでも見込みですので、１００％ということは言い切れないかもしれませんが、金額のほうは積算をさせていただいているものです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それで、新聞で見たのですけれども、例えば長野県の飯田市、１０万人ほどの町ですが、そこでは８,１００万円の予算を組んでいるのです。４０万人の品川は３,１００万円で、違和感を感じたのですが、それは大丈夫ということか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"飯田市の制度を私は直接そこまで深く見てはいないのですが、先ほどから言っていますけれども、これまでの受給実績、それから今回の制度を導入することによって増えるであろう部分、そういったことも全て想定に入れて、今回の金額の要求を出させていただいているものです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"その減収補填の負担を、利用料へ転嫁するのはいかがなものかと、筋違いではないかと。そもそも国が補償すべきではないかという要請を行うべきだったと、私は思うのですが、そういうことはやられたのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"ただ、ご利用者の方の同意がある、ないによって２つの値段が生じてしまうということに対していかがなものかというところで考えさせていただきました。それにつきましては、今ちょうど来年に向けて介護報酬が検討されているというふうに聞いておりますので。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"私としては、区のお考えとしては、その減収補填を利用料にかぶせた点に原因があるとはお考えになっていないのですか。その点、いかがでしょう。","respondent":"宮尾高齢者福祉課長","answer":"国も東京都も、この間、新型コロナウイルス感染症対策ということでいろいろな補助制度を設けたりしております。品川区が一保険者としてこの点に関して要請等を行うという具体的な考えは現時点ではございません。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"高齢者福祉施設で２,７００人、高齢者福祉施設での２,７００人に、車の運転手の方は含まれているのでしょうか。それをお伺いいたします。","respondent":"宮尾高齢者福祉課長","answer":"したがいまして、現時点では、そちらにつきましては引き続き検討してまいりたいというふうに思っております。なお、介護医療院とケアホームにつきましては、今回対象にさせていただきたいというふうに考えております。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"高齢者、それから障害者施設での感染例の報告、どのぐらいの感染例があったのか。その点についてお伺いしたいと思います。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長","answer":"そのうち、クラスターということですので５人以上というところかと思いますが、２カ所で５人以上の感染例が報告をされてあります。そういったことを含めまして、今回、ＰＣＲ検査の実施につながる一つのきっかけになったです。 今お尋ねの感染例についてのご報告ですが、障害者施設のほうは１例、１事業所でございました。クラスターの発生はございません。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"その都の補正予算が通れば、またもう一度こういう検査をやるという予定なのでしょうか。やはりこういう施設ですから、定期的にやっていくご予定あるいはご計画はあるのでしょうか、お伺いいたします。","respondent":"宮尾高齢者福祉課長","answer":"定期的に実施をしていくかというお尋ねですが、まず今回一回やってみて、どのぐらい陽性の方が出られるのか。それから実施体制、実施方法はこれでいいのかというようなことを検証して、次に向けて検討していきたいというふうに考えております。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問・要望","question":"要望しておきます。それぞれ７００人、１００人と書いてあるのですが、在宅系サービスとはどういう分け方なのか尋ねました。","respondent":"松山障害者福祉課長","answer":"施設系サービスというのは、施設においてサービスを直接提供するという従事者を示しています。在宅系サービスというのは、ホームヘルプといったように居宅を訪問して、在宅サービスへの支援をするサービスのことを示しております。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"そのときに、１,５００万円から２,０００万円ぐらいかかるのだというふうに伺いました。非常に不十分な予算だと思うのですけれども、その理由、根拠を伺いたいと思います。","respondent":"高山健康課長","answer":"それ以上に、患者の数に応じて、休日診療の歳入といいますか収入としてなっていたというものです。人を多く配置したいといった、完全なる損失補填をするといった種類のものではございませんので、金額面においては妥当だと考えております。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"要するにそれを出せないということは、ボランティアでやれといっているのに等しいような話になるのではないですか。出すのが当たり前ではないか尋ねました。","respondent":"高山健康課長","answer":"通常であれば患者数に応じて診療報酬などが入ってまいりますので、そうした部分において収支が、通常であればプラスになるといったものです。先ほどの説明の繰り返しになりますけれども、追加的に委託料を、といった趣旨のものです。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、私の素朴な理解ですと、この医師会の方々は、休日診療の業務を辞めてしまってもいいと、なくなってもいいというような、私だったら辞めてしまうな、という気もするのですが、そういうことなのか尋ねました。","respondent":"高山健康課長","answer":"そういった意味では、医師会費用としての側面もありますので、地域に貢献するという観点からこの事業については続けていっていただけるものと考えております。","id":"exchange-012"},{"speaker":"おくの委員","kind":"質問・要望","question":"診察治療等に従事した方ですけれども、例えば１回こっきりちらっと診察したようなお医者さん、そういう方も含めるのでしょうか。その点、お伺いいたします。","respondent":"高山健康課長","answer":"１点目の金額面の算出根拠の考え方ですが、まず医療機関の支援に関しましては、１０万円という金額を算出しております。２点目にお尋ねの、人数の考え方ですけれども、まず医療機関支援に関しましては、この間の受入れ入院患者の数から将来の数を推計して出したものです。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"１回こっきり診察したような方も含まれるのか尋ねました。","respondent":"高山健康課長","answer":"例えば、今委員がご指摘になったような方も病院としてはねぎらいたいというようなことであれば、対象となる可能性はあるというふうに考えてあります。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区内の７医療機関でやっていますので、この前の一般質問でも創設というのを要望していましたが、ちょっとこの辺を教えていただきたいということ。以上、４点まとめて伺いたいと思います。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長、高山健康課長","answer":"ここで、ここでというところで対応できるように、工事が不要なタイプを今回選択させていただいているです。なお、実際に今回やらせていただいて… 私からは、障害者福祉課に関わるご質問についてお答えいたします。２点目の、その中にダクト工事も含まれておりますので、可能です。 さらなる補正などが必要かどうかという点につきましては、入院患者数の今後の推移などを見ながら検討させていただきたいと考えております。それから２点目…","id":"exchange-015"},{"speaker":"あくつ委員","kind":"確認","question":"最後と言いながらさっき質問し忘れてしまったのですが、先ほど、前に一般質問したときは３つの病院というようなお話がありました。この支援金と慰労金について、この３病院を想定しているというふうに考えていいのかどうか、これだけ確認をさせてください。","respondent":"宮尾高齢者福祉課長、高山健康課長","answer":"私どものほうで考えているのは、その隣に換気設備を、そこからその設備のフィルターを通して外に出すというようなものを考えております。先ほどもご答弁させていただきましたが、部屋を固定することなく… 委員がお考えになっている３病院に加えて、４つ目の病院というのが今、その可能性もあるということで考えております。一応両支援の仕組みとも同じ医療機関、病院を対象としているということで考えております。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"それぞれ２,５００万円と５００万円使うと書いてあって、なぜこういう表記になってしまったのか、基本的なところを教えてほしいのです。そういう状況だという方に積極的に受けてもらうような支援のほうがいいのかなと僕は思うので、ちょっとその辺伺います。","respondent":"宮尾高齢者福祉課長","answer":"こちらはあくまでもこの内容でいたしますという意味合いで、予定という言葉を入れさせていただきました。委員にご提案いただいたように、どういった仕組みで今後向き合っていくべきか、こういったところもしっかりと考えていきたいと思います。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは国のほうで負担してほしいという要望書が上げられていたりという中で、本当に評価をしたいと思いますし、本当によかったなと考えています。そういった場合、この事業者が全て請求したということを前提にして組まれた予算なのかということの確認をさせてほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"ただ、こういう制度を今回ご提案しますので、これを踏まえた上でご利用者に引き続き丁寧なご説明をしてくださいというように考えているところです。もう２区分上のところで上がってくるものですので…","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"デイサービスが６６０人と、これはデイサービスを使っている方全てが対象と考えられているわけではないと。その中でこういう人、という対象の絞り方みたいなのは何かあるのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"基本的にはデイサービスを使っていて、この制度の俎上に乗るという方は、ほぼイコールというふうに考えております。ご本人の意思を尊重せざるを得ないというふうに考えておりますし、いや、実態は限りなくそのまま反映させていただいているところです。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これも私は事業者の方々から高齢者に接する中で大変不安だという声はずっと伺っていましたので、第一歩として本当に評価をしたいと考えています。その上でちょっとお聞きしたいのが、これはどういう事業所、どんなところで感染が発生しているのか内訳を教えていただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"ただ、基本的には１施設１台、施設の規模を考えまして、それぞれ施設のほうとやり取りをさせていただいて、１施設に１台を設置する予定です。先ほどドライバーの方は検討というように申し上げましたが、繰り返しになりますが、今回ご提案をさせていただいているところです。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"ＰＣＲ検査については、これは第一報ということでよかったと考えていますけど、東京都のほうでも同じような形で提案がされていると思うのです。その慰労金の範囲というのを決めるのはなかなか難しいのかなとは思うのですが、その辺に対してどう考えられているのかを説明を求めました。","respondent":"高山健康課長","answer":"しかしながら、東京都のほうでこの支援の仕組みを表に出したのが大体７月の終わりぐらいということで、定めていきたいというふうに考えております。かなり各論の部分に関しましては、本予算をお認めいただいた後に…","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ボーナスも減らされているという、危険手当をもらいたいのに逆に減らされているという、それが医療機関の現実だと思うのです。この支援については国に対しても言ってほしいと求めましたし、区としてもつかみながら、支援を強めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"介護保険特別会計の中で、その分介護給付が増えるわけですので、どういうふうに見ているのかということをちょっとお聞きしたいと思います。会計全体としてどういう状況になったかという、僅か２億８,０００万円と考えるのか、その辺の状況をちょっとご説明ほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"そこと相殺されてどのようになっていくかというところは、引き続きしっかり見守っていきたいと考えています。というようなことも視野に入れながら、今回、給付費の推移を見守っていきたいというふうに思っているところです。","id":"exchange-023"},{"speaker":"鈴木（博）委員長","kind":"質問","question":"きちんと保管できるかどうかなのですけど、その根拠というのはあるのですか、ということが１つ。万が一３,０００人やって３０人陽性が出たら、その辺のことはどのようにお考えになっているのか、その辺まとめてお聞きしたいのですけど。","respondent":"鷹箸保健予防課長、宮尾高齢者福祉課長","answer":"前半の検査の部分についてのみお答えいたします。あるいは２日前からの接触者について保健所のほうで十分な聞き取りが入りまして、その後の対応を進めていくということで考えております。 陽性者が出たときの対応ですけれども、例えばほかのサービス事業所に割り振る、こういったことが対応として考えられるかと思います。例えば複数の事業所を展開しているようなところでは、そこで何とか対応を…","id":"exchange-024"}]},{"id":"topic-02","title":"続きまして、第５９号議案 品川区指定居宅介護支援等の事業の人員および運営の基準等に関する条例の一部を改正する条例","agenda":"続きまして、第５９号議案 品川区指定居宅介護支援等の事業の人員および運営の基準等に関する条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"品川区内にこの居宅介護支援事業所というのは４６カ所あると思うのですが、この主任ケアマネを置いている事業所というのは何カ所あったのでしょうか。そのあたりをお伺いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"こちらの研修というのは東京都が実施主体で、年に２回行われているものです。ではそこから先、現実的にどうしていったらいいかというところをしっかりと丁寧に相談に乗ってまいりたいというふうに考えております。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"５年以上の実務経験があって研修が必要だということで、そうすると、最初の法律の改正ですね、国の改正に若干無理があったということなのでしょうか。法律に若干無理があったというような問題と捉えてよいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"現に、約３割の事業所については主任介護支援専門員の配置がまだできていないという実情がありますので、条例改正のご提案をするというものです。相談業務に支障が出るとか、そういったことは一切ございませんので…","id":"exchange-026"},{"speaker":"おくの委員","kind":"意見","question":"もう１点だけ、すみません。お願いしますとの意見を述べました。","respondent":"宮尾高齢者福祉課長","answer":"ただ、実情ではまだそこにギャップがあるというところで、今回の条例改正に至らせていただきました。来年の３月末に向けて、３割未配置でありますけれども、その努力をしていきたいというふうに考えているところです。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この研修そのものが何時間くらいの研修になるのか、それをちょっと伺いたいと思います。それから、そこら辺はこれからどういうふうにクリアされていくのかというあたりもちょっと教えていただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"例えばそこのキャパが小さくて、受けたいけれども受けることができない、こういったことは報告として受けておりません。それがネックになっているというところまでの認識はしていないところですが、先ほどから申し上げているように、進めてまいりたいと思ってあります。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"区としても把握していただいて、全員が受けられるような枠がなければ、東京都に対して働きかけをぜひ行っていただきたいなと思います。事業所としては続けていけるよ、これはどういう場合が想定されるのかということについてもお聞かせいただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"回数が年に２回というところで、特に規模が小さい事業所などではその辺のやりくりが難しいところがあるということで、我々も認識をしています。今回、それはしっかりと今回の国の省令の制度改正の趣旨を踏まえて、適切に対応していきたいというふうに考えております。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"取りあえずこれで努力していただくけれども、それで確保ができなかったとしても、居宅介護支援事業所を続けられないということはないですよ、ということが保証されると考えていいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"それから特例と２つの事柄が盛り込まれておりますので、来年の４月に入って配置ができないからすぐに、ということでは決してございません。ただ、今回の厚生労働省令の改正の趣旨をしっかりと踏まえて、全事業所が主任ケアマネを配置できるように検討してまいりたいと思います。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"確認","question":"今のご説明の趣旨を伺っていると、（２）では、これはどの時点のことをおっしゃっているのか。（２）の上で（１）が認められると、６年後に万が一確保できない場合でもこういうものを出せば許されるよ、そこだけちょっと確認させてほしいのです。","respondent":"宮尾高齢者福祉課長","answer":"（２）、例えば来年の４月１日で人事異動があって、原則として主任介護支援専門員でなければならない。そのＢさんも主任介護支援専門員でない、というときに、引き続き主任介護支援専門員でない方が管理者を務めることができるというものです。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"確認","question":"最後に確認ですけど、（２）の場合も、その計画書を出せば、いわゆる６年間、令和９年までそれは認められるよという意味なのかということが１つ。それと、これは今回の文言の中では読み取れなかったのですけど、どこかに書いてあるのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"ただいま私が申し上げた説明の内容について、今回の新旧対照表以外に何かあるかというと、ないです。３月３１日時点で管理者である介護支援専門員については、先ほど私がご答弁させていただいたことが網羅される解釈になるというふうに聞いております。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"確認","question":"網羅されている、説明はよく分かりました。６年後にはなっているだろうということで、６年延ばしたというように聞いていますので、ちょっと読み取れなかったので確認させていただきました。","respondent":"宮尾高齢者福祉課長","answer":"そのときに、今いただいた趣旨を踏まえて、きちんと今回の制度の趣旨が伝わるような丁寧な説明を心がけてまいりたいと思います。","id":"exchange-033"},{"speaker":"おくの委員","kind":"意見","question":"今のあくつ委員と鈴木副委員長のお話を聞きながら、新旧対照表などを見ていて思ったのですけど、この（２）の特例の話は、要するに令和９年以降もこの特例が通用するという理解でよろしいですね、第５条第２項にこの特例が定めてありますよねとの意見を述べました。","respondent":"宮尾高齢者福祉課長","answer":"今私が申し上げた（２）に関しましても、（１）と同様に令和９年３月３１日までの特例です。","id":"exchange-034"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、この新旧対照表の新の第５条第２項のただし書というのは、令和９年で廃止されるわけか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"令和９年３月３１日をもって実際にどういう条文になるのかというのは、また、そのときに備えてしっかりとやってまいりますが、先ほどの資料の改正案（１）、（２）、繰り返しになりますが、これは令和９年３月３１日までの措置だという認識でおります。","id":"exchange-035"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"区としてもぜひやるべきではないかなというふうに思うのですけど、それが１点、いかがでしょうか。そこのところも含めて総合的に検討するというのが前回のご答弁だったと思うのですが、その点はいかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"区が啓発を行うということですけれども、補聴器につきましては、大変専門性の高い医療機器というふうに認識しております。助成制度の問題ではなく、業界団体等の報告にも書いておりますので、区としてはその部分について同様の認識だというふうに申し上げたところです。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"耳鼻科の先生や学会の先生の講演なども伺ってきたところなのですけど、そしてとても微妙な調整が必要だということなのです。それは３カ月とか人によっては半年とか、難聴者に対して対応するということが重要だということは一致できるということでよろしいか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"耳鼻科等の方の見解については、そういう意見があるということも重々認識をしているということで、同様の認識だと申し上げたところです。今の段階では直接結びついていないというように考えているところでございまして、その主な理由としては…","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"前回は、そこのところが共通の認識にならなかったので、補聴器を早期につけて、そして加齢性難聴の方が難聴があっても補聴器によって通常の生活を継続させていくということが重要だ、必要だ、有効だ、そこのところは認識が一致したということで確認させていただいていいか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"施設等々で認知症の方と対応する際、もしくは認知症になる前の方と対応する際に、我々としては非常に重要視していると。それが全てではなくて、補聴器を使うことについてはしっかりと専門団体の方々に普及啓発をしていただきたいというところを申し上げているものです。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どういうふうにしていこうかというところの対策を持っているわけですから、そういうところでは、区としてぜひ認識してほしいと求めました。所管ですけど、これは、そこのところの所管の仕分けというのはどういうふうになっているのかということもお聞かせほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"支援が必要な高齢者の方は高齢者福祉課、元気な高齢者の方につきましては、高齢者地域支援課というふうに課がまたがっております。そういった意味で組織として対応する意味では、庶務担当課である福祉計画課のほうで合わせてご答弁をさせていただいているところです。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"４１デシベルぐらいになったところで既に補聴器をつけることがすごく大事なんだというようなことで強調されているわけではないですか。高齢者の生活の質を保つというようなところからも、そこの認識をぜひ持っていただきたいと思うのですけど、その点はいかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"全てが重要であるので、難聴だけをあえて重要と捉えているわけではなく、全てが重要だというふうに認識をしています。今のところ我々のほうは、補聴器の補助制度を創設することについて、考えはないというふうに申し上げているところです。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それはいかがでしょうか。区としても必要だということを認められるのであれば、そういうところにぜひいっていただきたいと思うのですが、どうでしょう。","respondent":"寺嶋福祉計画課長","answer":"繰り返しになりますが、補聴器の有効性自体を全く否定はしておりません。ただ、補助制度というものについて、今の段階で考える時点ではないということを申し上げているところです。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それは、正しい知識になっていないからなのです。そこのところが、区としても同じ認識であれば、そういうところは業者の方ではなくて区としてもやっていくべきなのではないか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"専門の方を配置している自治体があるということについて、私、不勉強でまだそこまでは把握していないので、引き続き調べたいと思いますけれども、業者任せにしているわけではなく、専門性がありますので、専門の方にぜひそこはお願いしたいということを申し上げているものです。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"請願なので、たしか自民党も補聴器の補助制度をしてほしいという要望を出されたというようなことを、区議会報告か何かで見たのですけれども。〔「どなたに質問されているのですか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"自民党に。〔「自民党に質問するのは……」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"委員同士で議論するというのも請願はいいのですよ。ぜひ自民党が要望された思いですとか、やはり補聴器の補助をすべきだというようなお考えなのか、その辺のところをお聞かせいただけたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"渡辺委員","kind":"意見","question":"そのうちの一つと考えています。それぞれ今、調査研究で上げている、そのさなかという表現だったかと記憶しておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"補聴器購入費の補助を要望したというようなニュースだったと思うのです。そういった意味では、補聴器はやはり区としてもしてほしいという、そういうのが自民党の考えなのかなというふうに思ったのですけど。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"渡辺委員","kind":"質問・要望","question":"まさにそのとおり、私たちは普段、当たり前のように政策の要望をする。だから、今どうしよう、要望も、やり取りはどの政策についても同じです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"自民党もそういうようなことで要望されているということですね。公明党はこの補聴器補助制度についていかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、要望だけを切り取られると誤解を招くので、要望をする、そして課題も考え、踏まえて、それぞれ判断していくと。要望だけを切り取られると非常に困りますので、要望する、そして長所も短所もある、課題もある。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。個別性も高いものだと思いますので、医療機関、専門機関でしっかりと受診していただくことを高齢者の方々に引き続き伝えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"渡部委員","kind":"質問・要望","question":"それは会派ですから様々な要望というのはみんなが出していて、要望出していますよね、その要望を出して。それが何か月かたったら話が変わるかもしれないわけですから、委員会ですから、各委員に同意を求めるのは結構ですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"渡部委員","kind":"質問","question":"というのが議会だと思いますので、ほかの会派が賛成でしたよね、というのは関係ないことですから、共産党がどうなのかということだけしっかり言っていただければ、私たちは会派の代表で来ているのですから、そこはしっかり意見は述べさせていただこうと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２万円から３万５,０００円ぐらい、１５万円から３０万円という高額なものを買えるのかどうかというところ、というところにも課題があると思います。だから現時点では、公的なものをここに出すということについては、採択はできないというところで、不採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"おくの委員","kind":"確認","question":"今日の議論から、早期着用が必要だというところは確認されたと思います。何らかの助成制度はやはりあったほうがよいと、あるべきだというふうに思いますので、採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのバランスを考えた中でも、この補助制度というのは、不採択という形でお願いしたいと思います。先ほどちょっと議論があったように、不十分なところもあると思いますので、そのあたりをまずしっかりやっていただくということを求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"}]},{"id":"topic-04","title":"令和２年陳情第３７号「荏原地域に障害者施設の整備を具体的に進めることを求める陳情」","agenda":"令和２年陳情第３７号「荏原地域に障害者施設の整備を具体的に進めることを求める陳情」","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"小山台と、１０件ほどということだと思うのですけれども、今言われたことで今のところ尽きているという理解でよろしいのでしょうか。それから、来年から６期目ということですけれども、それに盛り込むつもりでいらっしゃる計画などをご紹介してほしいと求めました。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"今、ご紹介させていただきました１０件というものの中にはグループホームに限らず、就労継続支援Ｂ型等の事業所も入ってあります。具体的に申し上げられる点につきましての、今のところの状況です。 第６期のほうに盛り込むかどうかというご質問についてですけれども、現在計画策定委員において、まだ案の段階ではあるのですけれども、主要テーマと今後の取組みというところで、事業所整備についても触れているところです。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"それから、ホームページで、「荏原地区福祉施設機能検討支援委託に係る簡易型プロポーザル実施要領」という資料を見つけたのですけれども、これは今の荏原地区のそういう増設計画などに関係のある資料なのでしょうか、お伺いいたします。","respondent":"松山障害者福祉課長","answer":"こちらの医療的ケア児を含む重度心身障害児に対する支援機能を拡充するために、今後の施設の在り方検討の基礎資料として作成を委託するものが１点目。２点目としましては、心身障害者福祉会館の機能の検討ということで…","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、荏原地区の施設の充実化ということには、あまり直結しない資料ということか尋ねました。","respondent":"松山障害者福祉課長","answer":"荏原地区の充実化というのは、この会館や戸越ルーム、２つの施設の検討というのが主です。やはり検討が必要だということは議会でも申し上げてきたものですので、こちらのほうと、また別な方向からのアプローチということになります。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"ここにそういう福祉施設、障害者施設をぜひ建ててほしいと思っているのですが、そういう計画はないのでしょうか。あるなしにかかわらず、障害者福祉課からも要望を出していただきたいと思うのですけれども、その点はいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"荏原四中といった区全体に関わるものにつきましては、私どもの所管というよりは企画調整課のほうの取扱いになっておりますので、区全体の中で総合的に考えて判断をしていくものと認識しております。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問・要望","question":"障害者福祉課から要望を出すというようなことも、お考えになっていないということか尋ねました。","respondent":"松山障害者福祉課長","answer":"障害者福祉課としましては、様々な手段を使いながら、活用しながら、当然、区の内部に要望を上げていくということは以前からしておりますし、今後もそのようにしていきたいと考えています。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今日のお話を伺っても、グループホームの独自助成を１００カ所に案内したり、その決意をこういう形で取組んでいただいているのだと思うのです。そういう点では１０件ほど相談があって、具体的なところで期待していいのかどうかという見通しが分かったら教えていただきたいのが１点です。","respondent":"松山障害者福祉課長","answer":"いわゆる指定を受けるといったことが必要になってきますので、一つずつ段階を経ないと具体的にお伝えすることが、今はできない状況です。住民説明会のほうでは、児童発達支援センター、それと就労継続支援Ｂ型というところを。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうことで言えば、それが荏原地域には何カ所あるかという、そこら辺のところが分かったら教えてほしいと求めました。これから６期の計画に向けても関わってきますので、区として建てていく方針が必要なのではないかと思うのですけれども、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"１点目の何を何カ所というご質問ですけれども、東京都への協議が必要だということなので、具体的にはまだお伝えできない段階です。今後の計画につきましても、その方向性というのは全く変わるものではなく、整備は促進していくということで一貫しております。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点で言えば、こういうことで動いているのは、これくらいにこうなるよというあたりを示していただけることがあったらお願いしたいと思います。これは特別支援学校とかから、例えば来年４月にはどのぐらい卒業生が出てきて、その辺の人数もおおよそ分かったら教えてほしいと求めました。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"開設のスケジュールにつきましては、事業所側の事情によるところが大きいかと思います。区のほうでは、具体的な計画になりましたらきちんとお伝えしたいと考えていますが、今のところそれがお伝えできる段階ではございません。 特別支援学校の卒業生の見込みですけれども、生活介護を利用される方は、七、八人程度だろうと見込んでおります。","id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、一番初めの利用率を１００％にしないで５０％ぐらいに抑えて受入れているという部分がありますね。先ほど利用率３５％ということでしたが、その卒業生が路頭に迷うことなく、受入れることは可能だと考えていいのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"受入れ枠としてはありますので、問題ございません。","id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"計画を組んで３年たちましたけれども、結局これが実現することにならなかったというのが、この３年間の計画の結果だったと思うのです。これができなかった一番の理由、ネックになっているものは何があると考えられているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"ただし、新型コロナウイルス感染症の状況等もあるかと思いますけれども、事業者側の経営状況といったものにも左右されるのではないかと考えています。区としてはできることを今精一杯やらせていただいておりますので、引き続き努力していきたいと考えています。","id":"exchange-066"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"障害者施設、高齢者施設を作るためには土地を確保できないというのは、これは本当に区の姿勢いかんだと思うのです。道路があれだけ土地を確保できているわけですから、それ以上に福祉を充実させるというのが自治体の責務なわけですから、ぜひ区として。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"西村委員","kind":"確認","question":"本日結論を出すで、不採択でお願いいたします。一事業所ずつ電話をするなどご努力いただいていることが確認できましたので、本陳情に関しましては不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"渡部委員","kind":"質問","question":"本日結論を出すで、不採択でお願いいたします。説明を伺っていまして、それに向けて着々と進んでいるですので、引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この陳情で求められている後半の部分は着実に早急に推進するようにということで、これは進められているということも確認させていただきました。具体的かどうかはともかくとして第５期に既に書き込んであり、第６期にもこれからそういうことが書き込まれるだろうということで、不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"おくの委員","kind":"意見","question":"いよいよこれからだというときですので、これからどんどん後押しをする意味でもこの陳情を採択して、後押しをしていきたいと思います。採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"第６期にもその旨盛り込んでいくという説明がありました。さらにスピード感を持って進めていってほしいということは要望いたしますが、この陳情に関しては、不採択ということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"}]},{"id":"topic-05","title":"令和２年陳情第３８号「医療的ケアを必要とする障害者が週５日通える生活介護の整備を求める陳情」","agenda":"令和２年陳情第３８号「医療的ケアを必要とする障害者が週５日通える生活介護の整備を求める陳情」","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"今のご説明ですと、ピッコロのほうはいつ頃からどういう体制になるのか、その予定を分かる限り教えてほしいと求めました。それをつかんでいらっしゃったら、教えてほしいと求めました。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"ピッコロの定員変更等の予定ですけれども、今現在東京都に相談しているところで、できましたら来年４月からという形で思ってはおります。人材確保等… 医療的ケアのニーズにつきましてですが、これは現在計画策定委員会においてちょうど進めているところですが、昨年度基礎調査を実施いたしました。… 先ほどの予定の部分ですけれども、１点、４月当初というのはちょっと難しいかなと考えています。できるだけご希望に沿うような形で環境設定はしていきたい…","id":"exchange-073"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから、ニーズを把握しているということですけれども、具体的な数字としてどういうものなのでしょうか。今年３月にアンケートを取られていて、集計の仕方がおかしいということで、そのクロス集計はもうやられたのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"その前に基礎調査のクロス集計につきましては実施しておりまして、集計したものにつきましては、委員の方に配付をさせていただきました。クロス集計から出てきた課題につきましては様々ありますので、そのあたりにつきましては、委員の皆様へ周知を図ったところです。","id":"exchange-074"},{"speaker":"おくの委員","kind":"質問・要望","question":"ピッコロや心身障害者福祉会館のような形である程度分かっているなら教えていただきたい。クロス集計で見えてきた課題というのは、見えてきたものがあれば教えていただきたいということなのですけれども、お分かりになればお願いいたします。","respondent":"築山障害者施策推進担当課長","answer":"総合支援施設の医療的ケアというところですけれども、始めるのであれば定員５名からのスタートになるかと思います。やはり受入れ施設等、受入れができる施設の整備、体制作りというところが今後の課題になってくるだろうと認識しております。","id":"exchange-075"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"総合支援施設ですけれども、重度の方５名というのは、来年の４月から生活介護で重度の方５名を受入れるということでいいのでしょうか。それは来年４月からを目指してやっていくのか、その確認をお願いします。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"定員変更等については東京都の承諾を得てという形になりますので、まだ今の時点ではお答えすることができませんけれども。職員体制は会館全体で２対１ということで、生活介護はその体制でいっております。 総合支援施設についてですけれども、まだ難しいかなと考えています。運営事業者のほうも受入れる体制を整えておりますので、ご相談いただきまして、受入れを行っていくということになると思います。","id":"exchange-076"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"けれども、先ほどのクロス集計をした結果でも、そこらへんはどう考えられているのかということをお聞かせほしいと求めました。そういうところで言えば、そこら辺については今後どのように整備していくお考えなのか説明を求めました。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"では、私から、人工呼吸器の方に対する受入れの見込みというのをお伝えいたします。その方の健康状況等も鑑みながら、どちらかというとやはり医療の形になるので、医師の判断というのが必要になってくるかと考えています。 その中で、やはり職員の育成というところが大きなところでございました。事業者といたしましても人材育成をやっていただきながら、それぞれの施設で受け入れられる体制を整えていけるように図っていきたいと考えています。","id":"exchange-077"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１週間に１回以上には増やせないと言われているということなのですが、そこら辺のところがよく分からないので教えてほしいと求めました。人工呼吸器をつけて、区としてどうつかんでいらっしゃるのかということもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"２点目ですけれども、人工呼吸器の方を受入れてほしいといったお声は頂いております。ただし、どちらかというとやはりかかりつけ医、あるいは事業所と提携を結んでいる医師の判断によるところが大きいと認識しております。","id":"exchange-078"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"親の介護と、そこら辺のところは毎回早急にと要望させていただいているところなのですけれども、仕組みをぜひ作ってほしいと求めました。その後はどうなっているのか、今後どうする方向なのか、その点についても説明を求めました。","respondent":"松山障害者福祉課長","answer":"メンバーを少し広げて実施していく予定ですけれども、看護師等医療職が多いことから、コロナ禍の中で日程調整が非常に厳しいところではあります。ただし、その支援関係機関連絡会を通じて区内の情報共有を行って、連携を密にしていきたいと考えています。","id":"exchange-079"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところでは、いつ頃やるかという見通しもまだ立っていないという状況でしょうか。ぜひこれは早く立ててやっていただきたいと思うのですが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"関係機関連絡会については、今、日程調整中です。ただ単に施策を作ることが目的ではなく、まずは情報共有を行って関係機関との連携を密にすることが、区の中で果たす一番の役割と認識しております。","id":"exchange-080"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"関係機関連絡会は、皆様コロナ禍で本当に大変な状況にあるのは重々承知していますけれども、医療的ケア児者の皆様も本当に大変で切実な状況がありますので、ぜひ一日も早く開いていただくようにお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"西村委員","kind":"確認","question":"本日結論を出すで、不採択でお願いいたします。各施設ごとに整備に向けて前向きに取組んでいただいていることが確認できましたので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"渡部委員","kind":"確認","question":"本日結論を出すということで、不採択でお願いいたします。ピッコロが週５回預かる方向に向けて動き出しているという確認と、問題ないかなと思いまして、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"あくつ委員","kind":"意見","question":"ピッコロ、また心身障害者福祉会館、そして障害児者総合支援施設も含めて前向きに整備を進めていると。そのことをぜひ品川区を代表するうちの会の代表の方から出ていますので、しっかりお伝えしていただければというところで、不採択としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"おくの委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。まだまだ整っていない状況ですので、これから整えていくという意味で、採択で頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれで進めているというご説明を頂きましたので、現状そういった方向で進んでいるということで、不採択としたいと思います。ただ、さらに次の段階にということとしては必要だと思いますので、そちらの連絡会準備会のほうを進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"おくの委員","kind":"質問","question":"あるいはまた別の基準を持っておられて、その基準で判断されているということなのでしょうか。それをお伺いいたします。","respondent":"鷹箸保健予防課長","answer":"１人患者が出ますと、周りの方との濃厚接触の状況を詳しく聞き取りますが、そこで濃厚接触者となった方には基本的に全員検査をしています。例えば福祉施設等で陽性者が１人見つかり、具体的に５分とか１５分とかということでなくても、現在は対象を広く取っているところです。","id":"exchange-087"},{"speaker":"おくの委員","kind":"質問","question":"では、今のＱ＆Ａに準じていると理解しておいてよろしいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"委員ご指摘のとおりです。","id":"exchange-088"},{"speaker":"おくの委員","kind":"質問","question":"それまではやる考えはないということだったと思うのですけれども、これは区の考え方がある程度変わったということで理解してよろしいのでしょうか。今後、対象を拡大していくという考えはおありなのでしょうか、どうか尋ねました。","respondent":"鷹箸保健予防課長","answer":"検査の基準というのは区独自に決めているものではございませんで、基本的には国の考えにのっとって全国統一の中でやっているところです。国の方針の変更にも基づいて、職員の方等に対してまず１回ですけれども、検査をする方針になったということです。","id":"exchange-089"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、さっきの補正予算の考え方も、Ｑ＆Ａにあった基準の準用、その考え方、精神から来たものだというわけか尋ねました。","respondent":"鷹箸保健予防課長","answer":"はい、ご指摘のとおりです。","id":"exchange-090"},{"speaker":"おくの委員","kind":"質問","question":"ご存じでしょうけれども８月２８日の感染症対策本部の決定で、施設等に限らず、積極的な検査を実施するようお願いしたい。」とか、国が支援する仕組みを設ける」とあるのですけれども、これも国の基準に準じて具体化する場合があり得ると理解してよろしいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"後ほどご説明いたしますが、その中で必要と判断した場合には、もちろん国の基準にのっとって広く範囲を設定することは十分にあり得ると思います。","id":"exchange-091"},{"speaker":"おくの委員","kind":"質問","question":"その専用相談窓口は結局設置されているのでしょうか。ＣＯＣＯＡは書いてあるのか」「ＣＯＣＯＡでＰＣＲ検査やっている」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-092"},{"speaker":"おくの委員","kind":"質問","question":"ＰＣＲ検査の範囲の問題として質問しているのですが、その相談件数は今までにどのぐらいあるのでしょうか。検査を行った人の人数はどのぐらいなのか、伺っておきたいと思います。","respondent":"鷹箸保健予防課長、鈴木（博）委員長","answer":"稼働したのが７月からでございまして、そう読める通知が出たのが８月２１日でございまして、それ以降ということでご説明いたします。… どこでも、ＣＯＣＯＡについては後の所管事務調査で詳しく課長のほうからご説明があると思うので、ここでは詳しいご説明をしなくて結構です。 陳情第３９号、第４４号両方にあります「定期的に」というところについては、私どもの考え方の中にはありません。あくまでも陽性者の方がいたときに…","id":"exchange-093"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"仕組みを教えていただきたいのですが、この５０カ所で行うＰＣＲ検査というのは、そこら辺の仕組みについて教えてほしいと求めました。１７人ということでしたけれども、ああいう状況が起こった場合に、お聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"ただ元に戻りまして、そこはかかりつけ医などこれまでの医療の制度の中で考えていくべきものと考えております。広く面的な検査という方針だと確認しておりますので、必要な検査については今後も対象に関してしっかり対応していきたいと考えております。","id":"exchange-094"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この５０カ所でやられた検査数というのは、今ではまだ把握できない仕組みになっているということなのでしょうか。それから、これができるということにしていきますよというものなのかと思ったのですけれども、そういうものではないということなのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"３つ質問を頂きました。実はすごく変更があったところなので後段の所管事務調査で、詳しくご説明する予定なのですけれども、よろしいでしょうか。","id":"exchange-095"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私はクラスターが高齢者施設で２カ所、あと東大井で１カ所ということで、お願いしたいと思います。」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"これは情報公開のことなので聞かせてください。実際は６５人だったということで、それほど多くはなかったのだなと最終的には思ったのですけれども、その点について説明を求めました。","respondent":"鷹箸保健予防課長","answer":"８月、今現在８つのホテルを準備していただいており、必要な方は翌日にはホテルへ入所できているという状況です。過去においてもホテルに入れないため自宅療養となった方は、記憶の中では特段ございません。","id":"exchange-097"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう限界という状況の中、これから区としては、区として収束に向けた対策というのはどう考えられているかお聞かせほしいと求めました。無症状の感染者を見つけ出して保護隔離するという対策を強化するのが最も効果的ではないかと思うのですけれども、その点についても説明を求めました。","respondent":"鷹箸保健予防課長","answer":"基本的には国の方針、それからその考え方にのっとってできることというのは、やはり区民の皆様に向けて感染予防のための日頃の行動をしっかり取っていただくといったことが一番効果的と考えているところです。","id":"exchange-098"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回も「世田谷区のように」と書かれていますけれども、そして無症状の感染者が感染を広げるというのがこの新型コロナウイルス感染症の特徴ですから。全国でという取組みが大事だというこのコロナ対策ですから、対策を強化していく方向でも、ぜひ区としても取組んでいただきたいと要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"西村委員","kind":"意見","question":"感染拡大防止を最優先にして、現状できる最大限の判断の中で精いっぱい取組んでいただいていると思っています。現状、今後の取組みなどのご説明に一定の理解を示しましたので、本陳情に関しましては不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"渡部委員","kind":"質問・要望","question":"その中でどれだけ出ているよというのがもうあるわけだから、そこで注意喚起になっているので、何を求めているかがさっぱり分からない。ですから、もう不採択。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-101"},{"speaker":"あくつ委員","kind":"質問","question":"私どものこの前の一般質問でも国際感染症センターの大曲センター長の講演をこの前私も一緒に聞きまして、その方向に集約していくのではないかなと。出入りがある中で区だけでやるということについては、ちょっとまだ何とも判断できないということで、不採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"おくの委員","kind":"意見","question":"そのＰＣＲ検査で感染拡大を抑えていくという立場に立つべきだと思います。それゆえに、採択を主張いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"意見","question":"科学的な考え方、そのほか専門家の方の考え方で、区のほうは今できることをやられていると思います。そういった形で現状取り得ることが行われていると考えていますので、この陳情に関しては不採択ということでお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"確認をしたいのですが、接触確認アプリのＣＯＣＯＡの通知が来て、これは電話相談ではどのような形で促すのか。本人が受けたくないと言った場合、これは受けなくてはいけない法定の義務とか何か拘束力とか強制力があるのかどうか、ここについて説明を求めました。","respondent":"鷹箸保健予防課長","answer":"その日は１日どこにも行っていませんというような方も結構いらして、どうもこの通知は違うのではないかというのも今も実際にあるようです。今のところ義務もありませんし、強制力もありませんけれども、ぜひ受けたいという方が今は多くなっています。","id":"exchange-105"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２ページの一番下のところで、単身でも、希望すれば全てその食料とかを配送していただけるという仕組みになっているのでしょうか。そのことを伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"先ほどご説明したところですが、この方について、まだ何もご本人に対応していない時にすぐ救急車を呼ばれたという事例などもあります。この施設であれば、初めから百何人でも全部やりましょうとか、そういったことは決めて対応しています。","id":"exchange-106"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そうすると、陽性だということで、防護服だったりそういう対応をした救急隊が来てくださるという仕組みになっているのでしょうか。そこの確認だけお願いします。","respondent":"鷹箸保健予防課長","answer":"そういう説明がなくて、なったらどうしたらいいかというご質問にも一方で相談に乗っておりまして、分かっていれば防護服を着ていく。分からない場合も、元々はしっかり防護をされて現場に行かれているという状況になります。","id":"exchange-107"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3576#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":92220,"voices":305}}]);
